struct Stage24TouchShared {
    std::mutex mutex;
    // Pointer 0 remains the legacy cursor/LBUTTON owner. Pointer 1 is retained
    // separately so the Android compatibility layer can publish the original
    // touchcount contract and translate a two-finger span into zoomLevel.
    float x = 0.0f;
    float y = 0.0f;
    float x2 = 0.0f;
    float y2 = 0.0f;
    uint32_t pointerCount = 0;
    bool held = false;
    bool pressPending = false;
    bool releasePending = false;
    bool pinchBeginPending = false;
    bool pinchEndPending = false;
    uint64_t eventCount = 0;
};

struct Stage24TouchFrame {
    float x = 0.0f;
    float y = 0.0f;
    float x2 = 0.0f;
    float y2 = 0.0f;
    uint32_t pointerCount = 0;
    bool held = false;
    bool pressed = false;
    bool released = false;
    bool pinchBegan = false;
    bool pinchEnded = false;
    uint64_t eventCount = 0;
};

