// Stage 24.17.0: the ARMv7 ownership chain is now closed end-to-end.
// MyRenderer.nativeInit forwards its Java width/height arguments unchanged to
// EGL_createContext(); EGL_Context::width()/height() are then injected by the
// GameLua constructor as screenWidth/screenHeight. The presentation canvas is
// therefore the Context size itself, not a separate 480x320 gameplay canvas or
// a synthetic 480-high menu canvas.
static int gStage24133MenuLogicalW = 480;
static int gStage24133MenuLogicalH = 320;
static int gStage24133WindowW = 0;
static int gStage24133WindowH = 0;

// Stage 24.20.1 introduced the testing display harness. Native mode preserves
// the recovered 1.4.2 Context contract exactly. WVGA mode keeps an era-
// appropriate 854x480 logical Context. Stage 24.31.4f now preserves that Context
// as a literal 1:1 legacy raster and moves modern scaling outside KA3D into a
// final composited presentation pass. This outer presentation is a port
// compatibility layer; legacy renderer semantics remain the recovered contract.
#ifndef STAGE24_DEBUG_LOGICAL_W
#define STAGE24_DEBUG_LOGICAL_W 854
#endif
#ifndef STAGE24_DEBUG_LOGICAL_H
#define STAGE24_DEBUG_LOGICAL_H 480
#endif
static constexpr bool gStage24201DebugDisplay =
    (STAGE24_DEBUG_LOGICAL_W > 0 && STAGE24_DEBUG_LOGICAL_H > 0);
static constexpr int gStage24201DebugLogicalW = STAGE24_DEBUG_LOGICAL_W;
static constexpr int gStage24201DebugLogicalH = STAGE24_DEBUG_LOGICAL_H;

static int stage24201_effective_logical_w(int surfaceW) {
    return gStage24201DebugDisplay ? gStage24201DebugLogicalW : std::max(1, surfaceW);
}
static int stage24201_effective_logical_h(int surfaceH) {
    return gStage24201DebugDisplay ? gStage24201DebugLogicalH : std::max(1, surfaceH);
}

static void stage24133_resolve_menu_canvas_from_window() {
    std::lock_guard<std::mutex> lock(gStage24WindowMutex);
    if (!gStage24Window) return;
    const int w = ANativeWindow_getWidth(gStage24Window);
    const int h = ANativeWindow_getHeight(gStage24Window);
    if (w <= 0 || h <= 0) return;
    gStage24133WindowW = w;
    gStage24133WindowH = h;
    gStage24133MenuLogicalW = w;
    gStage24133MenuLogicalH = h;
}

