static Stage24TouchFrame stage24_consume_touch() {
    Stage24TouchFrame f;
    std::lock_guard<std::mutex> lock(gStage24Touch.mutex);
    f.x = gStage24Touch.x;
    f.y = gStage24Touch.y;
    f.x2 = gStage24Touch.x2;
    f.y2 = gStage24Touch.y2;
    f.pointerCount = gStage24Touch.pointerCount;
    f.held = gStage24Touch.held;
    f.pressed = gStage24Touch.pressPending;
    f.released = gStage24Touch.releasePending;
    f.pinchBegan = gStage24Touch.pinchBeginPending;
    f.pinchEnded = gStage24Touch.pinchEndPending;
    f.eventCount = gStage24Touch.eventCount;
    gStage24Touch.pressPending = false;
    gStage24Touch.releasePending = false;
    gStage24Touch.pinchBeginPending = false;
    gStage24Touch.pinchEndPending = false;
    return f;
}

static void stage24_reset_touch() {
    std::lock_guard<std::mutex> lock(gStage24Touch.mutex);
    gStage24Touch.pointerCount = 0;
    gStage24Touch.held = false;
    gStage24Touch.pressPending = false;
    gStage24Touch.releasePending = false;
    gStage24Touch.pinchBeginPending = false;
    gStage24Touch.pinchEndPending = false;
}

static const Proto* gLastLuaProto = nullptr;
static int gLastLuaPc = -1;
static std::map<const Proto*, std::string> gLuaProtoNames;

// Stage 24.25.5: audit-only context for exact ownership of the original
// audioRampVolume/audioRampLength globals.  No value is changed here.
static int gStage24255Frame = -1;
static std::string gStage24255Mode;
static std::string gStage24255Page;

static void index_global_lua_functions(lua_State* L) {
    gLuaProtoNames.clear();

    lua_pushvalue(L, LUA_GLOBALSINDEX);
    const int globals = lua_gettop(L);
    lua_pushnil(L);

    while (lua_next(L, globals) != 0) {
        if (lua_type(L, -2) == LUA_TSTRING &&
            lua_isfunction(L, -1) &&
            !lua_iscfunction(L, -1)) {
            const void* ptr = lua_topointer(L, -1);
            if (ptr) {
                const Closure* cl = static_cast<const Closure*>(ptr);
                gLuaProtoNames[cl->l.p] = lua_tostring(L, -2);
            }
        }
        lua_pop(L, 1);
    }

    lua_pop(L, 1);
}

static const char* proto_name(const Proto* p) {
    const auto it = gLuaProtoNames.find(p);
    if (it != gLuaProtoNames.end())
        return it->second.c_str();
    return "<unmapped-lua-proto>";
}

static std::string stage24_global_lua_function_name(lua_State* L, const char* globalName) {
    if (!L || !globalName) return "<invalid>";
    lua_getglobal(L, globalName);
    std::string out = "<non-function>";
    if (lua_isfunction(L, -1)) {
        if (lua_iscfunction(L, -1)) {
            out = "<native-c-function>";
        } else {
            const void* ptr = lua_topointer(L, -1);
            if (ptr) {
                const Closure* cl = static_cast<const Closure*>(ptr);
                out = proto_name(cl->l.p);
            } else {
                out = "<lua-function>";
            }
        }
    }
    lua_pop(L, 1);
    return out;
}

static void exact_vm_hook(lua_State* L, lua_Debug*) {
    if (!L || !L->ci || !L->ci->func)
        return;

    const TValue* fn = L->ci->func;
    if (!isLfunction(fn))
        return;

    const Closure* cl = clvalue(fn);
    const Proto* p = cl->l.p;
    gLastLuaProto = p;

    // Lua 5.1's VM increments pc before invoking the count hook.
    if (L->savedpc && p && p->code)
        gLastLuaPc = static_cast<int>(L->savedpc - p->code - 1);
    else
        gLastLuaPc = -1;

    // Stage 24.25.5: observe the exact untouched SETGLOBAL instruction that
    // owns the two audio ramp globals. The hook runs before the instruction
    // executes, so register A is the value about to be written.  Reading the
    // TValue directly avoids calling back into Lua from inside its VM hook.
    if (gLastLuaPc >= 0 && gLastLuaPc < p->sizecode && p->k) {
        const Instruction ins = p->code[gLastLuaPc];
        if (GET_OPCODE(ins) == OP_SETGLOBAL) {
            const int bx = GETARG_Bx(ins);
            if (bx >= 0 && bx < p->sizek && ttisstring(&p->k[bx])) {
                const char* key = svalue(&p->k[bx]);
                if (key && (!std::strcmp(key, "audioRampVolume") ||
                            !std::strcmp(key, "audioRampLength"))) {
                    const int a = GETARG_A(ins);
                    const TValue* value = L->base ? (L->base + a) : nullptr;
                    const char* source = (p->source ? getstr(p->source) : "<no-source>");
                    std::printf("[stage24.25.5-audio-ramp-write] frame=%d mode='%s' page='%s' owner='%s' source='%s' pc=%d global='%s' value=",
                                gStage24255Frame, gStage24255Mode.c_str(),
                                gStage24255Page.c_str(), proto_name(p), source,
                                gLastLuaPc, key);
                    if (!value) std::printf("<null>");
                    else if (ttisnil(value)) std::printf("nil");
                    else if (ttisnumber(value)) std::printf("%.9g", (double)nvalue(value));
                    else if (ttisboolean(value)) std::printf("%s", bvalue(value) ? "true" : "false");
                    else if (ttisstring(value)) std::printf("'%s'", svalue(value));
                    else std::printf("<type:%d>", ttype(value));
                    std::printf("\n");
                }
            }
        }
    }
}

static void stage17_print_constant(const TValue* value) {
    if (!value) {
        std::printf("<null>");
        return;
    }

    if (ttisnil(value)) {
        std::printf("nil");
    } else if (ttisboolean(value)) {
        std::printf("%s", bvalue(value) ? "true" : "false");
    } else if (ttisnumber(value)) {
        std::printf("%.9g", (double)nvalue(value));
    } else if (ttisstring(value)) {
        std::printf("'%s'", svalue(value));
    } else {
        std::printf("<tt=%d>", ttype(value));
    }
}

static void stage17_print_rk(const Proto* p, int operand) {
    if (!p || !ISK(operand))
        return;

    const int k = INDEXK(operand);
    if (k < 0 || k >= p->sizek)
        return;

    std::printf(" K[%d]=", k);
    stage17_print_constant(&p->k[k]);
}

static void dump_stage17_selection_bytecode(lua_State* L) {
    lua_getglobal(L, "updateGame");
    if (!lua_isfunction(L, -1) || lua_iscfunction(L, -1)) {
        std::printf(
            "[stage17-bytecode] updateGame is not an original Lua function\n");
        lua_pop(L, 1);
        return;
    }

    const void* ptr = lua_topointer(L, -1);
    const Closure* cl = static_cast<const Closure*>(ptr);
    const Proto* p = cl ? cl->l.p : nullptr;

    if (!p || !p->code) {
        std::printf("[stage17-bytecode] updateGame Proto missing\n");
        lua_pop(L, 1);
        return;
    }

    std::printf(
        "[stage17-bytecode] updateGame proto=%p sizecode=%d sizek=%d; "
        "selection window PC 620..780\n",
        static_cast<const void*>(p), p->sizecode, p->sizek);

    // First surface every interesting global/string constant and its exact
    // K index. This makes GETGLOBAL/SETGLOBAL Bx operands readable.
    static const char* interesting[] = {
        "LBUTTON",
        "touchcount",
        "currentBirdName",
        "selectedBird",
        "birdReady",
        "cursor",
        "cursorPhysics",
        "cursorWorld",
        "dragStarted",
        "draggingStartPosPhysics",
        "shootRange",
        "shootMaxLength",
        "rubberBandPos",
        "rubberBandLength",
        "levelStartPosition",
        "objects",
        "world"
    };

    for (int i = 0; i < p->sizek; ++i) {
        const TValue* k = &p->k[i];
        if (!ttisstring(k))
            continue;
        const char* text = svalue(k);
        for (const char* wanted : interesting) {
            if (std::strcmp(text, wanted) == 0) {
                std::printf(
                    "[stage17-bytecode] K[%d] = '%s'\n",
                    i, text);
                break;
            }
        }
    }

    const int begin = 620;
    const int end = p->sizecode < 781 ? p->sizecode : 781;

    for (int pc = begin; pc < end; ++pc) {
        const Instruction ins = p->code[pc];
        const OpCode op = GET_OPCODE(ins);
        const int a = GETARG_A(ins);
        const int b = GETARG_B(ins);
        const int c = GETARG_C(ins);
        const int bx = GETARG_Bx(ins);
        const int sbx = GETARG_sBx(ins);

        std::printf(
            "[stage17-bytecode] pc=%4d op=%-10s "
            "A=%d B=%d C=%d Bx=%d sBx=%d",
            pc,
            (op >= 0 && op < NUM_OPCODES)
                ? luaP_opnames[op] : "<bad-op>",
            a, b, c, bx, sbx);

        switch (op) {
            case OP_LOADK:
            case OP_GETGLOBAL:
            case OP_SETGLOBAL:
                if (bx >= 0 && bx < p->sizek) {
                    std::printf(" K[%d]=", bx);
                    stage17_print_constant(&p->k[bx]);
                }
                break;

            case OP_GETTABLE:
                stage17_print_rk(p, c);
                break;

            case OP_SETTABLE:
                stage17_print_rk(p, b);
                stage17_print_rk(p, c);
                break;

            case OP_EQ:
            case OP_LT:
            case OP_LE:
            case OP_ADD:
            case OP_SUB:
            case OP_MUL:
            case OP_DIV:
            case OP_MOD:
            case OP_POW:
                stage17_print_rk(p, b);
                stage17_print_rk(p, c);
                break;

            default:
                break;
        }

        std::printf("\n");
    }

    lua_pop(L, 1);
}


// Stage 24.12.3: static bytecode audit of the original font-selection path.
// This does not execute or replace any Lua function.  It prints the exact
// stripped Lua 5.1 instructions/constants for a small set of original
// closures so the next bridge can be based on observed semantics rather than
// a guessed FONT_BASIC fallback.
static void stage24123_dump_named_proto(lua_State* L, const char* globalName) {
    if (!L || !globalName) return;

    lua_getglobal(L, globalName);
    if (!lua_isfunction(L, -1) || lua_iscfunction(L, -1)) {
        std::printf("[stage24.12.3-font-audit] %s unavailable kind=%s\n",
                    globalName, lua_typename(L, lua_type(L, -1)));
        lua_pop(L, 1);
        return;
    }

    const void* ptr = lua_topointer(L, -1);
    const Closure* cl = static_cast<const Closure*>(ptr);
    const Proto* p = cl ? cl->l.p : nullptr;
    if (!p || !p->code) {
        std::printf("[stage24.12.3-font-audit] %s proto-missing\n", globalName);
        lua_pop(L, 1);
        return;
    }

    std::printf("[stage24.12.3-font-audit] BEGIN %s proto=%p sizecode=%d sizek=%d numparams=%d maxstack=%d\n",
                globalName, static_cast<const void*>(p), p->sizecode, p->sizek,
                (int)p->numparams, (int)p->maxstacksize);

    for (int i = 0; i < p->sizek; ++i) {
        std::printf("[stage24.12.3-font-audit] %s K[%d]=", globalName, i);
        stage17_print_constant(&p->k[i]);
        std::printf("\n");
    }

    // These functions are small enough to dump completely.  Cap pathological
    // cases so a malformed/unexpected closure cannot flood logcat/stdout.
    const int end = std::min(p->sizecode, 512);
    for (int pc = 0; pc < end; ++pc) {
        const Instruction ins = p->code[pc];
        const OpCode op = GET_OPCODE(ins);
        const int a = GETARG_A(ins);
        const int b = GETARG_B(ins);
        const int c = GETARG_C(ins);
        const int bx = GETARG_Bx(ins);
        const int sbx = GETARG_sBx(ins);

        std::printf("[stage24.12.3-font-audit] %s pc=%03d op=%-10s A=%d B=%d C=%d Bx=%d sBx=%d",
                    globalName, pc,
                    (op >= 0 && op < NUM_OPCODES) ? luaP_opnames[op] : "<bad-op>",
                    a, b, c, bx, sbx);

        switch (op) {
            case OP_LOADK:
            case OP_GETGLOBAL:
            case OP_SETGLOBAL:
                if (bx >= 0 && bx < p->sizek) {
                    std::printf(" K[%d]=", bx);
                    stage17_print_constant(&p->k[bx]);
                }
                break;
            case OP_GETTABLE:
                stage17_print_rk(p, c);
                break;
            case OP_SETTABLE:
                stage17_print_rk(p, b);
                stage17_print_rk(p, c);
                break;
            case OP_EQ:
            case OP_LT:
            case OP_LE:
            case OP_ADD:
            case OP_SUB:
            case OP_MUL:
            case OP_DIV:
            case OP_MOD:
            case OP_POW:
                stage17_print_rk(p, b);
                stage17_print_rk(p, c);
                break;
            default:
                break;
        }
        std::printf("\n");
    }
    if (p->sizecode > end) {
        std::printf("[stage24.12.3-font-audit] %s truncated sizecode=%d cap=%d\n",
                    globalName, p->sizecode, end);
    }
    std::printf("[stage24.12.3-font-audit] END %s\n", globalName);
    lua_pop(L, 1);
}



// Stage 24.12.6: targeted bytecode window around the concrete loader-time
// failure observed at prepareMenuPage pc=9178. Diagnostic only: does not
// execute or replace the closure and does not alter Lua/resource semantics.
static void stage24126_dump_preparemenupage_window(lua_State* L) {
    if (!L) return;
    lua_getglobal(L, "prepareMenuPage");
    if (!lua_isfunction(L, -1) || lua_iscfunction(L, -1)) {
        std::printf("[stage24.12.6-pmp-window] prepareMenuPage unavailable kind=%s\n",
                    lua_typename(L, lua_type(L, -1)));
        lua_pop(L, 1);
        return;
    }

    const void* ptr = lua_topointer(L, -1);
    const Closure* cl = static_cast<const Closure*>(ptr);
    const Proto* p = cl ? cl->l.p : nullptr;
    if (!p || !p->code) {
        std::printf("[stage24.12.6-pmp-window] prepareMenuPage proto-missing\n");
        lua_pop(L, 1);
        return;
    }

    const int begin = 9150;
    const int requestedEnd = 9206; // exclusive
    const int end = std::min(p->sizecode, requestedEnd);
    std::printf("[stage24.12.6-pmp-window] BEGIN proto=%p sizecode=%d sizek=%d range=%d..%d\n",
                static_cast<const void*>(p), p->sizecode, p->sizek,
                begin, end > begin ? end - 1 : begin);

    if (begin >= p->sizecode) {
        std::printf("[stage24.12.6-pmp-window] requested range outside proto\n");
        std::printf("[stage24.12.6-pmp-window] END\n");
        lua_pop(L, 1);
        return;
    }

    for (int pc = begin; pc < end; ++pc) {
        const Instruction ins = p->code[pc];
        const OpCode op = GET_OPCODE(ins);
        const int a = GETARG_A(ins);
        const int b = GETARG_B(ins);
        const int c = GETARG_C(ins);
        const int bx = GETARG_Bx(ins);
        const int sbx = GETARG_sBx(ins);

        std::printf("[stage24.12.6-pmp-window] pc=%04d op=%-10s A=%d B=%d C=%d Bx=%d sBx=%d",
                    pc,
                    (op >= 0 && op < NUM_OPCODES) ? luaP_opnames[op] : "<bad-op>",
                    a, b, c, bx, sbx);

        switch (op) {
            case OP_LOADK:
            case OP_GETGLOBAL:
            case OP_SETGLOBAL:
                if (bx >= 0 && bx < p->sizek) {
                    std::printf(" K[%d]=", bx);
                    stage17_print_constant(&p->k[bx]);
                }
                break;
            case OP_GETTABLE:
            case OP_SELF:
                stage17_print_rk(p, c);
                break;
            case OP_SETTABLE:
                stage17_print_rk(p, b);
                stage17_print_rk(p, c);
                break;
            case OP_EQ:
            case OP_LT:
            case OP_LE:
            case OP_ADD:
            case OP_SUB:
            case OP_MUL:
            case OP_DIV:
            case OP_MOD:
            case OP_POW:
                stage17_print_rk(p, b);
                stage17_print_rk(p, c);
                break;
            default:
                break;
        }
        if (pc == 9178) std::printf("  <== FAIL-PC");
        std::printf("\n");
    }
    std::printf("[stage24.12.6-pmp-window] END\n");
    lua_pop(L, 1);
}

