// Stage 24.28.0: giant menu/UI/navigation inventory.
// Diagnostic only.  This runs after the untouched initializeMenu() bootstrap,
// before Stage24 forces the direct Level1 gameplay path.  It does not execute
// callbacks, select pages, prepare pages, play video, save data, or mutate
// navigation state.
static bool stage24280_name_relevant(const std::string& value) {
    std::string low = value;
    std::transform(low.begin(), low.end(), low.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
    });
    static const char* terms[] = {
        "menu", "page", "popup", "episode", "level", "pause", "complete",
        "failed", "setting", "option", "credit", "about", "golden", "egg",
        "tutorial", "cutscene", "cut_scene", "cinematic", "movie", "video",
        "story", "comic", "intro", "startup", "splash", "loading", "save",
        "highscore", "star", "unlock", "achievement", "leaderboard", "crystal",
        "gamecenter", "advert", "replay", "retry", "next"
    };
    for (const char* t : terms) {
        if (low.find(t) != std::string::npos) return true;
    }
    return false;
}

static int stage24280_abs_index(lua_State* L, int idx) {
    if (idx < 0 && idx > LUA_REGISTRYINDEX)
        return lua_gettop(L) + idx + 1;
    return idx;
}

static std::string stage24280_scalar_repr(lua_State* L, int idx) {
    idx = stage24280_abs_index(L, idx);
    char buf[160];
    switch (lua_type(L, idx)) {
        case LUA_TNIL:
            return "nil";
        case LUA_TBOOLEAN:
            return lua_toboolean(L, idx) ? "true" : "false";
        case LUA_TNUMBER:
            std::snprintf(buf, sizeof(buf), "%.9g", (double)lua_tonumber(L, idx));
            return buf;
        case LUA_TSTRING: {
            const char* x = lua_tostring(L, idx);
            std::string out = "'";
            if (x) {
                for (const char* q = x; *q && out.size() < 300; ++q) {
                    if (*q == '\n') out += "\\n";
                    else if (*q == '\r') out += "\\r";
                    else if (*q == '\t') out += "\\t";
                    else if (*q == '\'') out += "\\'";
                    else out += *q;
                }
            }
            out += "'";
            return out;
        }
        case LUA_TFUNCTION:
            if (lua_iscfunction(L, idx)) return "<native-c-function>";
            else {
                const void* ptr = lua_topointer(L, idx);
                const Closure* cl = ptr ? static_cast<const Closure*>(ptr) : nullptr;
                if (cl && cl->l.p) {
                    std::snprintf(buf, sizeof(buf), "<lua-function:%s code=%d k=%d>",
                                  proto_name(cl->l.p), cl->l.p->sizecode, cl->l.p->sizek);
                    return buf;
                }
                return "<lua-function>";
            }
        case LUA_TTABLE:
            return "<table>";
        default:
            std::snprintf(buf, sizeof(buf), "<%s>", lua_typename(L, lua_type(L, idx)));
            return buf;
    }
}

static void stage24280_dump_table(lua_State* L, int idx,
                                  const std::string& path,
                                  int depth, int maxDepth,
                                  int* budget) {
    if (!budget || *budget <= 0) return;
    idx = stage24280_abs_index(L, idx);
    if (!lua_istable(L, idx)) return;

    lua_pushnil(L);
    while (lua_next(L, idx) != 0) {
        if (*budget <= 0) {
            lua_pop(L, 1);
            break;
        }
        std::string key;
        if (lua_type(L, -2) == LUA_TSTRING) {
            key = lua_tostring(L, -2) ? lua_tostring(L, -2) : "<null-string>";
        } else if (lua_type(L, -2) == LUA_TNUMBER) {
            char b[48];
            std::snprintf(b, sizeof(b), "[%.0f]", (double)lua_tonumber(L, -2));
            key = b;
        } else {
            key = "[<" + std::string(lua_typename(L, lua_type(L, -2))) + ">]";
        }
        const std::string child = path.empty() ? key : path + "." + key;
        const int t = lua_type(L, -1);
        std::printf("[stage24.28.0-menu-table] path='%s' type=%s value=%s\n",
                    child.c_str(), lua_typename(L, t),
                    stage24280_scalar_repr(L, -1).c_str());
        --(*budget);

        if (t == LUA_TTABLE && depth < maxDepth && *budget > 0)
            stage24280_dump_table(L, -1, child, depth + 1, maxDepth, budget);
        lua_pop(L, 1);
    }
}

static void stage24280_dump_proto_strings(const std::string& rootName,
                                          const Proto* p,
                                          const std::string& protoPath,
                                          int depth,
                                          int* budget) {
    if (!p || !budget || *budget <= 0 || depth > 8) return;
    bool hasRelevant = stage24280_name_relevant(rootName);
    for (int i = 0; i < p->sizek; ++i) {
        if (ttisstring(&p->k[i])) {
            const char* x = svalue(&p->k[i]);
            if (x && stage24280_name_relevant(x)) {
                hasRelevant = true;
                break;
            }
        }
    }
    if (hasRelevant) {
        std::printf("[stage24.28.0-menu-proto] root='%s' proto='%s' code=%d k=%d children=%d params=%d stack=%d\n",
                    rootName.c_str(), protoPath.c_str(), p->sizecode, p->sizek,
                    p->sizep, (int)p->numparams, (int)p->maxstacksize);
        --(*budget);
        for (int i = 0; i < p->sizek && *budget > 0; ++i) {
            if (!ttisstring(&p->k[i])) continue;
            const char* x = svalue(&p->k[i]);
            // For relevant roots, retain every string constant: callbacks and
            // destination page names are often semantically bland (e.g. "back").
            std::printf("[stage24.28.0-menu-proto] root='%s' proto='%s' K[%d]='%s'%s\n",
                        rootName.c_str(), protoPath.c_str(), i, x ? x : "",
                        (x && stage24280_name_relevant(x)) ? " RELEVANT" : "");
            --(*budget);
        }
    }
    for (int i = 0; i < p->sizep && *budget > 0; ++i) {
        char child[64];
        std::snprintf(child, sizeof(child), "%s/child%d", protoPath.c_str(), i);
        stage24280_dump_proto_strings(rootName, p->p[i], child, depth + 1, budget);
    }
}

static bool stage24280_table_has_items(lua_State* L, int idx) {
    idx = stage24280_abs_index(L, idx);
    if (!lua_istable(L, idx)) return false;
    lua_getfield(L, idx, "items");
    const bool yes = lua_istable(L, -1);
    lua_pop(L, 1);
    return yes;
}

static void stage24280_dump_menu_ui_inventory(lua_State* L, const char* reason) {
    if (!L) return;
    std::printf("[stage24.28.0-menu-inventory] BEGIN reason='%s' screen=%.0fx%.0f mode='%s' currentPage='%s' newPage='%s' popup='%s'\n",
                reason ? reason : "<none>",
                get_global_number(L, "screenWidth"), get_global_number(L, "screenHeight"),
                stage24_global_lua_function_name(L, "currentGameMode").c_str(),
                table_field_table_name(L, "currentMenuPage").c_str(),
                table_field_table_name(L, "newMenuPage").c_str(),
                table_field_table_name(L, "popupPage").c_str());

    // Global Lua closure graph.  Recursing through child Protos catches menu
    // callbacks that are not themselves stored as globals.
    std::vector<std::pair<std::string, const Proto*> > funcs;
    lua_pushvalue(L, LUA_GLOBALSINDEX);
    const int globals = lua_gettop(L);
    lua_pushnil(L);
    while (lua_next(L, globals) != 0) {
        if (lua_type(L, -2) == LUA_TSTRING && lua_isfunction(L, -1) && !lua_iscfunction(L, -1)) {
            const char* name = lua_tostring(L, -2);
            const void* ptr = lua_topointer(L, -1);
            const Closure* cl = ptr ? static_cast<const Closure*>(ptr) : nullptr;
            if (name && cl && cl->l.p)
                funcs.push_back(std::make_pair(std::string(name), cl->l.p));
        }
        lua_pop(L, 1);
    }
    lua_pop(L, 1);
    std::sort(funcs.begin(), funcs.end(), [](const std::pair<std::string,const Proto*>& a,
                                             const std::pair<std::string,const Proto*>& b) {
        return a.first < b.first;
    });
    int protoBudget = 12000;
    for (const auto& f : funcs) {
        stage24280_dump_proto_strings(f.first, f.second, "root", 0, &protoBudget);
        if (protoBudget <= 0) break;
    }
    std::printf("[stage24.28.0-menu-inventory] protoBudgetRemaining=%d globalLuaFunctions=%d\n",
                protoBudget, (int)funcs.size());

    // Global page/state tables.  Include name-relevant globals and any table
    // owning an `items` table; the latter finds page objects even when their
    // global name is unexpected.
    std::vector<std::string> tables;
    lua_pushvalue(L, LUA_GLOBALSINDEX);
    const int globals2 = lua_gettop(L);
    lua_pushnil(L);
    while (lua_next(L, globals2) != 0) {
        if (lua_type(L, -2) == LUA_TSTRING && lua_istable(L, -1)) {
            const char* name = lua_tostring(L, -2);
            if (name && (stage24280_name_relevant(name) || stage24280_table_has_items(L, -1)))
                tables.push_back(name);
        }
        lua_pop(L, 1);
    }
    lua_pop(L, 1);
    std::sort(tables.begin(), tables.end());
    tables.erase(std::unique(tables.begin(), tables.end()), tables.end());
    std::printf("[stage24.28.0-menu-inventory] candidateGlobalTables=%d\n", (int)tables.size());
    int tableBudget = 60000;
    for (const std::string& name : tables) {
        if (tableBudget <= 0) break;
        lua_getglobal(L, name.c_str());
        if (lua_istable(L, -1)) {
            const int before = tableBudget;
            std::printf("[stage24.28.0-menu-table] BEGIN global='%s' sharedBudget=%d\n", name.c_str(), tableBudget);
            stage24280_dump_table(L, -1, name, 0, 4, &tableBudget);
            std::printf("[stage24.28.0-menu-table] END global='%s' emitted=%d sharedRemaining=%d\n",
                        name.c_str(), before - tableBudget, tableBudget);
        }
        lua_pop(L, 1);
    }
    std::printf("[stage24.28.0-menu-inventory] tableBudgetRemaining=%d\n", tableBudget);

    static const char* platformGlobals[] = {
        "settings", "highscores", "levelSelectionPagesBasic", "levelSelectionPages",
        "levelComplete", "levelFailed", "pause", "currentMenuPage", "oldMenuPage",
        "newMenuPage", "popupPage", "newPopupPage", "loadLevelDelayed",
        "prepareMenusAfterAd", "videoAdRequested", "videoReady", "assetsCreated",
        "gameCenterEnabled", "checkForCrystalEnabled", "levelPath", "levelName",
        "levelFolder", "currentLevelNumber", "currentWorldNumber", "currentThemeNumber"
    };
    for (const char* name : platformGlobals) {
        lua_getglobal(L, name);
        std::printf("[stage24.28.0-menu-global] name='%s' type=%s value=%s\n",
                    name, lua_typename(L, lua_type(L, -1)),
                    stage24280_scalar_repr(L, -1).c_str());
        lua_pop(L, 1);
    }
    std::printf("[stage24.28.0-menu-inventory] END reason='%s'\n", reason ? reason : "<none>");
}

static std::string stage24280_global_signature(lua_State* L, const char* name) {
    lua_getglobal(L, name);
    std::string out = std::string(lua_typename(L, lua_type(L, -1))) + ":" +
                      stage24280_scalar_repr(L, -1);
    lua_pop(L, 1);
    return out;
}

static void stage24280_navigation_runtime(lua_State* L, int frame, const char* reason) {
    static std::string previous;
    const std::string mode = stage24_global_lua_function_name(L, "currentGameMode");
    const std::string page = table_field_table_name(L, "currentMenuPage");
    const std::string oldPage = table_field_table_name(L, "oldMenuPage");
    const std::string newPage = table_field_table_name(L, "newMenuPage");
    const std::string popup = table_field_table_name(L, "popupPage");
    const std::string newPopup = table_field_table_name(L, "newPopupPage");
    const std::string loadDelayed = stage24280_global_signature(L, "loadLevelDelayed");
    const std::string level = get_global_string(L, "levelName");
    const std::string sig = mode + "|" + page + "|" + oldPage + "|" + newPage + "|" +
                            popup + "|" + newPopup + "|" + loadDelayed + "|" + level;
    if (sig == previous && (frame % 300) != 0) return;
    previous = sig;
    std::printf("[stage24.28.0-navigation-runtime] frame=%d reason='%s' mode='%s' currentPage='%s' oldPage='%s' newPage='%s' popup='%s' newPopup='%s' loadLevelDelayed=%s level='%s' completed=%s failedTimer=%.6f completeTimer=%.6f prepareMenusAfterAd=%s videoAdRequested=%s videoReady=%s gameCenterEnabled=%s crystalCheck=%s\n",
                frame, reason ? reason : "frame", mode.c_str(), page.c_str(), oldPage.c_str(),
                newPage.c_str(), popup.c_str(), newPopup.c_str(), loadDelayed.c_str(), level.c_str(),
                get_global_bool(L, "levelCompleted", false) ? "true" : "false",
                get_global_number(L, "levelFailedTimer"), get_global_number(L, "levelCompleteTimer"),
                get_global_bool(L, "prepareMenusAfterAd", false) ? "true" : "false",
                get_global_bool(L, "videoAdRequested", false) ? "true" : "false",
                get_global_bool(L, "videoReady", false) ? "true" : "false",
                get_global_bool(L, "gameCenterEnabled", false) ? "true" : "false",
                get_global_bool(L, "checkForCrystalEnabled", false) ? "true" : "false");
}

static bool stage17_get_table_bool(lua_State* L,
                                   const char* tableName,
                                   const char* key,
                                   bool* out) {
    if (!out)
        return false;

    lua_getglobal(L, tableName);
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        return false;
    }

    lua_getfield(L, -1, key);
    const bool valid = lua_isboolean(L, -1);
    if (valid)
        *out = lua_toboolean(L, -1) != 0;
    lua_pop(L, 2);
    return valid;
}


static int traced_error_handler(lua_State* L) {
    const char* msg = lua_tostring(L, 1);
    std::fprintf(stderr,
        "[stage8-debug] error='%s'\n",
        msg ? msg : "<non-string error>");
    S24E("LUA ERROR: %s", msg ? msg : "<non-string error>");
    std::fprintf(stderr,
        "[stage8-debug] last stripped Lua instruction: function=%s pc=%d proto=%p\n",
        proto_name(gLastLuaProto),
        gLastLuaPc,
        static_cast<const void*>(gLastLuaProto));

    for (int level = 0; level < 16; ++level) {
        lua_Debug ar;
        if (!lua_getstack(L, level, &ar))
            break;
        if (!lua_getinfo(L, "nS", &ar))
            continue;

        std::fprintf(stderr,
            "[stage8-debug] stack[%d] name=%s namewhat=%s what=%s source=%s line=%d\n",
            level,
            ar.name ? ar.name : "?",
            ar.namewhat ? ar.namewhat : "?",
            ar.what ? ar.what : "?",
            ar.short_src,
            ar.currentline);
    }

    // Preserve the original error object for lua_pcall().
    lua_settop(L, 1);
    return 1;
}

struct SpriteInfo {
    int x = 0;
    int y = 0;
    int width = 0;
    int height = 0;
    int pivotX = 0;
    int pivotY = 0;
    std::string sheetName;
    std::string textureName;
};

struct SpriteSheetInfo {
    std::string sheetName;
    std::vector<std::string> textures;
    int spriteCount = 0;
};

struct CompoSpritePart {
    std::string spriteName;
    int x = 0;
    int y = 0;
};

struct CompoSpriteInfo {
    int minX = 0;
    int minY = 0;
    int maxX = 0;
    int maxY = 0;
    int itemCount = 0;
    std::vector<CompoSpritePart> parts;
};

class SpriteDB {
public:
    bool loadSheet(const std::string& path) {
        std::ifstream f(path.c_str(), std::ios::binary);
        if (!f) {
            std::printf("[stage6] sprite sheet open FAIL: %s\n", path.c_str());
            return false;
        }
        std::vector<unsigned char> d(
            (std::istreambuf_iterator<char>(f)),
            std::istreambuf_iterator<char>());

        size_t sprt = std::string::npos;
        for (size_t i = 0; i + 4 <= d.size(); ++i) {
            if (d[i] == 'S' && d[i+1] == 'P' && d[i+2] == 'R' && d[i+3] == 'T') {
                sprt = i;
                break;
            }
        }
        if (sprt == std::string::npos) {
            // Stage 24.15.5: the untouched 1.4.2 INGAME_SKIES_1.dat and
            // INGAME_GROUNDS_1.dat are the legacy headerless single-texture
            // form of the same sprite payload.  Stage24.15.4 exact-byte audit
            // proved their complete grammar (and exact file lengths):
            //   str16(texture), u16(spriteCount),
            //   spriteCount * { str16(name), i16 x,y,w,h,pivotX,pivotY }
            // There is no KA3D/SPRT wrapper, no version word, and the texture
            // count is therefore implicitly one.  Accept this form only when
            // the entire file parses exactly; trailing/short data is rejected.
            size_t q = 0;
            auto qneed = [&](size_t n) -> bool { return q + n <= d.size(); };
            auto qu16 = [&]() -> uint16_t {
                if (!qneed(2)) return 0;
                const uint16_t v = static_cast<uint16_t>(
                    (static_cast<uint16_t>(d[q]) << 8) | d[q+1]);
                q += 2;
                return v;
            };
            auto qi16 = [&]() -> int {
                const uint16_t u = qu16();
                return (u & 0x8000u) ? static_cast<int>(u) - 65536 : static_cast<int>(u);
            };
            auto qstr16 = [&]() -> std::string {
                if (!qneed(2)) return std::string();
                const uint16_t n = qu16();
                if (n == 0 || !qneed(n)) return std::string();
                std::string v(reinterpret_cast<const char*>(&d[q]), n);
                q += n;
                return v;
            };

            const std::string texture = qstr16();
            if (texture.empty() || !qneed(2)) {
                std::printf("[stage24.15.5-scene-dat] headerless parse FAIL header path=%s bytes=%zu\n",
                            path.c_str(), d.size());
                return false;
            }
            const uint16_t spriteCount = qu16();
            if (spriteCount == 0) {
                std::printf("[stage24.15.5-scene-dat] headerless parse FAIL zero sprites path=%s\n",
                            path.c_str());
                return false;
            }

            const std::string sheetName =
                path.substr(path.find_last_of("/\\") + 1);
            std::string sheetKey = sheetName;
            if (sheetKey.size() >= 4 &&
                sheetKey.compare(sheetKey.size() - 4, 4, ".dat") == 0)
                sheetKey.resize(sheetKey.size() - 4);

            std::vector<std::pair<std::string, SpriteInfo>> parsed;
            parsed.reserve(spriteCount);
            for (uint16_t i = 0; i < spriteCount; ++i) {
                const std::string name = qstr16();
                if (name.empty() || !qneed(12)) {
                    std::printf("[stage24.15.5-scene-dat] headerless parse FAIL sprite=%u path=%s offset=%zu bytes=%zu\n",
                                (unsigned)i, path.c_str(), q, d.size());
                    return false;
                }
                SpriteInfo si;
                si.x = qi16();
                si.y = qi16();
                si.width = qi16();
                si.height = qi16();
                si.pivotX = qi16();
                si.pivotY = qi16();
                si.sheetName = sheetName;
                si.textureName = texture;
                parsed.push_back(std::make_pair(name, si));
            }
            if (q != d.size()) {
                std::printf("[stage24.15.5-scene-dat] headerless parse FAIL trailing path=%s consumed=%zu bytes=%zu\n",
                            path.c_str(), q, d.size());
                return false;
            }

            for (const auto& e : parsed) {
                sprites_[e.first] = e.second;
                spriteOwners_[e.first].push_back(e.second);
                spritesBySheet_[sheetKey + "\n" + e.first] = e.second;
            }
            SpriteSheetInfo sheet;
            sheet.sheetName = sheetName;
            sheet.textures.push_back(texture);
            sheet.spriteCount = static_cast<int>(parsed.size());
            sheets_.push_back(sheet);

            std::printf("[stage24.15.5-scene-dat] headerless-single-texture PASS sheet=%s texture='%s' sprites=%u bytes=%zu consumed=%zu\n",
                        sheetName.c_str(), texture.c_str(), (unsigned)spriteCount,
                        d.size(), q);
            return true;
        }
        if (sprt + 8 > d.size()) {
            std::printf("[stage6] malformed SPRT chunk: %s\n", path.c_str());
            return false;
        }

        size_t p = sprt + 8; // skip "SPRT" + big-endian chunk size
        auto need = [&](size_t n) -> bool { return p + n <= d.size(); };
        auto u16 = [&]() -> uint16_t {
            if (!need(2)) return 0;
            uint16_t v = static_cast<uint16_t>((d[p] << 8) | d[p+1]);
            p += 2;
            return v;
        };
        auto i16 = [&]() -> int {
            uint16_t u = u16();
            return (u & 0x8000u) ? static_cast<int>(u) - 65536 : static_cast<int>(u);
        };
        auto str16 = [&]() -> std::string {
            const uint16_t n = u16();
            if (!need(n)) return std::string();
            std::string s(reinterpret_cast<const char*>(&d[p]), n);
            p += n;
            return s;
        };

        const std::string sheetName =
            path.substr(path.find_last_of("/\\") + 1);

        if (!need(2)) return false;
        const uint16_t textureCount = u16();
        std::vector<std::string> textures;
        textures.reserve(textureCount);
        for (uint16_t i = 0; i < textureCount; ++i) {
            const std::string texture = str16();
            if (texture.empty()) {
                std::printf("[stage23.0] malformed texture entry in %s\n", path.c_str());
                return false;
            }
            textures.push_back(texture);
        }

        if (!need(2)) return false;
        const uint16_t spriteCount = u16();
        int loaded = 0;
        for (uint16_t i = 0; i < spriteCount; ++i) {
            const std::string name = str16();
            if (!need(12) || name.empty()) {
                std::printf("[stage6] malformed sprite entry in %s\n", path.c_str());
                return false;
            }
            SpriteInfo s;
            s.x = i16();
            s.y = i16();
            s.width = i16();
            s.height = i16();
            s.pivotX = i16();
            s.pivotY = i16();
            s.sheetName = sheetName;
            if (textures.size() == 1)
                s.textureName = textures[0];
            sprites_[name] = s;
            spriteOwners_[name].push_back(s);
            std::string sheetKey = sheetName;
            if (sheetKey.size() >= 4 && sheetKey.compare(sheetKey.size() - 4, 4, ".dat") == 0)
                sheetKey.resize(sheetKey.size() - 4);
            spritesBySheet_[sheetKey + "\n" + name] = s;
            ++loaded;
        }

        SpriteSheetInfo sheet;
        sheet.sheetName = sheetName;
        sheet.textures = textures;
        sheet.spriteCount = loaded;
        sheets_.push_back(sheet);

        std::printf("[stage23.0-sheet] %-24s textures=%u sprites=%d",
                    sheetName.c_str(), (unsigned)textureCount, loaded);
        for (size_t i = 0; i < textures.size(); ++i)
            std::printf(" texture[%zu]='%s'", i, textures[i].c_str());
        std::printf("\n");
        return true;
    }

    // Stage 24.12.7: KA3D COMP parser for the original 1.4.2
    // TUTORIALS_composprites.dat.  The old COMP payload is a list of named
    // composite sprites; each composite is a list of normal sprite names plus
    // signed x/y offsets.  Resources.getCompoSpriteBounds() derives the union
    // of the referenced normal SPRT rectangles after applying each sprite's
    // pivot.  This matches the recovered ARM-era API shape
    // (minX,minY,maxX,maxY), not width/height.
    bool loadCompoSheet(const std::string& path) {
        std::ifstream f(path.c_str(), std::ios::binary);
        if (!f) {
            std::printf("[stage24.12.7-compo] open FAIL: %s\n", path.c_str());
            return false;
        }
        std::vector<unsigned char> d(
            (std::istreambuf_iterator<char>(f)),
            std::istreambuf_iterator<char>());

        if (d.size() < 20 ||
            !(d[0] == 'K' && d[1] == 'A' && d[2] == '3' && d[3] == 'D')) {
            std::printf("[stage24.12.7-compo] unsupported/missing KA3D header: %s bytes=%zu\n",
                        path.c_str(), d.size());
            return false;
        }

        size_t comp = std::string::npos;
        for (size_t i = 0; i + 4 <= d.size(); ++i) {
            if (d[i] == 'C' && d[i+1] == 'O' && d[i+2] == 'M' && d[i+3] == 'P') {
                comp = i;
                break;
            }
        }
        if (comp == std::string::npos || comp + 10 > d.size()) {
            std::printf("[stage24.12.7-compo] COMP chunk missing: %s\n", path.c_str());
            return false;
        }

        auto be16at = [&](size_t q) -> uint16_t {
            return q + 2 <= d.size()
                ? static_cast<uint16_t>((static_cast<uint16_t>(d[q]) << 8) | d[q+1])
                : 0;
        };
        auto signed16 = [](uint16_t u) -> int {
            return (u & 0x8000u) ? static_cast<int>(u) - 65536 : static_cast<int>(u);
        };

        // getDatInfo/readComp from the recovered KA3D tooling enters old COMP
        // payload ten bytes after the fourcc.  In KA3D files the format lives
        // at offset 8; the legacy version word used by COMP v2 is at offset 16.
        const int version = d.size() >= 18 ? signed16(be16at(16)) : 0;
        size_t q = comp + 10;
        auto need = [&](size_t n) -> bool { return q + n <= d.size(); };
        auto u16 = [&]() -> uint16_t {
            if (!need(2)) return 0;
            const uint16_t v = static_cast<uint16_t>((static_cast<uint16_t>(d[q]) << 8) | d[q+1]);
            q += 2;
            return v;
        };
        auto i16 = [&]() -> int { return signed16(u16()); };
        auto str16 = [&]() -> std::string {
            if (!need(2)) return std::string();
            const uint16_t n = u16();
            if (!need(n)) return std::string();
            std::string out(reinterpret_cast<const char*>(&d[q]), n);
            q += n;
            return out;
        };

        if (!need(2)) return false;
        const uint16_t compoCount = u16();
        int loaded = 0;
        int missingParts = 0;
        int totalParts = 0;

        for (uint16_t ci = 0; ci < compoCount; ++ci) {
            const std::string compoName = str16();
            if (compoName.empty() || !need(2)) {
                std::printf("[stage24.12.7-compo] malformed composite header index=%u path=%s\n",
                            (unsigned)ci, path.c_str());
                return false;
            }
            const uint16_t itemCount = u16();
            CompoSpriteInfo c;
            c.itemCount = static_cast<int>(itemCount);
            bool haveBounds = false;

            for (uint16_t ii = 0; ii < itemCount; ++ii) {
                const std::string spriteName = str16();
                if (spriteName.empty() || !need(4)) {
                    std::printf("[stage24.12.7-compo] malformed item compo=%s index=%u\n",
                                compoName.c_str(), (unsigned)ii);
                    return false;
                }
                const int x = i16();
                const int y = i16();
                ++totalParts;
                c.parts.push_back(CompoSpritePart{spriteName, x, y});

                const SpriteInfo* part = find(spriteName.c_str());
                if (!part) {
                    ++missingParts;
                    std::printf("[stage24.12.7-compo] missing child sprite compo='%s' child='%s' offset=(%d,%d)\n",
                                compoName.c_str(), spriteName.c_str(), x, y);
                    continue;
                }

                const int x0 = x - part->pivotX;
                const int y0 = y - part->pivotY;
                const int x1 = x + part->width - part->pivotX;
                const int y1 = y + part->height - part->pivotY;
                if (!haveBounds) {
                    c.minX = x0; c.minY = y0; c.maxX = x1; c.maxY = y1;
                    haveBounds = true;
                } else {
                    c.minX = std::min(c.minX, x0);
                    c.minY = std::min(c.minY, y0);
                    c.maxX = std::max(c.maxX, x1);
                    c.maxY = std::max(c.maxY, y1);
                }
            }

            // Old KA3D COMP version 2 carries one extra 16-bit value after
            // every composite.  It is not part of the geometry.
            if (version == 2) {
                if (!need(2)) return false;
                q += 2;
            }

            if (!haveBounds)
                c.minX = c.minY = c.maxX = c.maxY = 0;
            compos_[compoName] = c;
            ++loaded;
        }

        std::printf("[stage24.12.7-compo] PASS file=%s version=%d compos=%d parts=%d missingParts=%d bytes=%zu\n",
                    path.c_str(), version, loaded, totalParts, missingParts, d.size());
        S24I("COMPO metadata bridge PASS file=TUTORIALS_composprites.dat version=%d compos=%d parts=%d missingParts=%d",
             version, loaded, totalParts, missingParts);
        return true;
    }

    // Stage 24.30.1: dynamic Resources::createSpriteSheet ownership.
    // The original Resources registry is populated when a sheet is created and
    // pruned when that same sheet is released. Static Stage24 bootstrap sheets
    // remain resident; only sheets explicitly loaded through the dynamic bridge
    // are removed by that bridge.
    static std::string normalizeSheetKey(std::string sheet) {
        const size_t slash = sheet.find_last_of("/\\");
        if (slash != std::string::npos) sheet = sheet.substr(slash + 1);
        if (sheet.size() >= 4 && sheet.compare(sheet.size() - 4, 4, ".dat") == 0)
            sheet.resize(sheet.size() - 4);
        return sheet;
    }

    bool getSheetInfo(const std::string& raw, SpriteSheetInfo* out) const {
        const std::string key = normalizeSheetKey(raw);
        for (auto it = sheets_.rbegin(); it != sheets_.rend(); ++it) {
            if (normalizeSheetKey(it->sheetName) == key) {
                if (out) *out = *it;
                return true;
            }
        }
        return false;
    }

    bool hasSheet(const std::string& raw) const {
        return getSheetInfo(raw, nullptr);
    }

    bool unloadSheet(const std::string& raw, SpriteSheetInfo* removed) {
        const std::string key = normalizeSheetKey(raw);
        SpriteSheetInfo info;
        if (!getSheetInfo(key, &info)) return false;

        std::vector<std::string> names;
        const std::string prefix = key + "\n";
        for (auto it = spritesBySheet_.begin(); it != spritesBySheet_.end(); ) {
            if (it->first.compare(0, prefix.size(), prefix) == 0) {
                names.push_back(it->first.substr(prefix.size()));
                it = spritesBySheet_.erase(it);
            } else {
                ++it;
            }
        }

        for (const std::string& name : names) {
            auto oit = spriteOwners_.find(name);
            if (oit == spriteOwners_.end()) continue;
            auto& owners = oit->second;
            owners.erase(std::remove_if(owners.begin(), owners.end(),
                [&](const SpriteInfo& si) {
                    return normalizeSheetKey(si.sheetName) == key;
                }), owners.end());
            if (owners.empty()) {
                spriteOwners_.erase(oit);
                sprites_.erase(name);
            } else {
                // loadSheet() overwrites the global registry on every add, so
                // the most recently retained owner is the observable fallback.
                sprites_[name] = owners.back();
            }
        }

        sheets_.erase(std::remove_if(sheets_.begin(), sheets_.end(),
            [&](const SpriteSheetInfo& si) {
                return normalizeSheetKey(si.sheetName) == key;
            }), sheets_.end());
        if (removed) *removed = info;
        std::printf("[stage24.30.1-dynamic-sheet] REGISTRY_RELEASE sheet='%s' sprites=%zu textures=%zu\n",
                    key.c_str(), names.size(), info.textures.size());
        return true;
    }

    const SpriteInfo* find(const char* name) const {
        auto it = sprites_.find(name ? name : "");
        return it == sprites_.end() ? nullptr : &it->second;
    }

    const SpriteInfo* findInSheet(const char* sheet, const char* name) const {
        const std::string spriteName = name ? name : "";
        if (!sheet || !*sheet) return find(spriteName.c_str());
        std::string sheetKey = sheet;
        const size_t slash = sheetKey.find_last_of("/\\");
        if (slash != std::string::npos) sheetKey = sheetKey.substr(slash + 1);
        if (sheetKey.size() >= 4 && sheetKey.compare(sheetKey.size() - 4, 4, ".dat") == 0)
            sheetKey.resize(sheetKey.size() - 4);
        auto it = spritesBySheet_.find(sheetKey + "\n" + spriteName);
        return it == spritesBySheet_.end() ? nullptr : &it->second;
    }

    size_t ownerCount(const char* name) const {
        auto it = spriteOwners_.find(name ? name : "");
        return it == spriteOwners_.end() ? 0u : it->second.size();
    }

    const SpriteInfo* findUniqueGlobal(const char* name) const {
        const std::string key = name ? name : "";
        auto oit = spriteOwners_.find(key);
        if (oit == spriteOwners_.end() || oit->second.size() != 1u) return nullptr;
        auto it = sprites_.find(key);
        return it == sprites_.end() ? nullptr : &it->second;
    }

    const CompoSpriteInfo* findCompo(const char* name) const {
        auto it = compos_.find(name ? name : "");
        return it == compos_.end() ? nullptr : &it->second;
    }

    size_t size() const { return sprites_.size(); }
    size_t compoSize() const { return compos_.size(); }
    const std::vector<SpriteSheetInfo>& sheets() const { return sheets_; }
    const std::map<std::string, SpriteInfo>& all() const { return sprites_; }

private:
    std::map<std::string, SpriteInfo> sprites_;
    std::map<std::string, std::vector<SpriteInfo>> spriteOwners_;
    std::map<std::string, SpriteInfo> spritesBySheet_;
    std::map<std::string, CompoSpriteInfo> compos_;
    std::vector<SpriteSheetInfo> sheets_;
};


