// Legacy draw-order compatibility model.
//
// The original ARMv7 renderer exposes a stable hash-table traversal order.
// This implementation preserves the observable contract required by the game:
// the legacy string hash, capacity progression, load threshold, bucket number,
// collision ordering, deletion behavior, and bucket-by-bucket iteration.
//
// The representation here intentionally differs from the historical KA3D
// Hashtable implementation: each bucket owns an explicit primary entry and
// an overflow sequence rather than using a shared indexed node/next layout.
//
// This is a compatibility reimplementation made after historical source and
// runtime analysis; it is not described as a clean-room implementation.
class LegacyStringOrder236C {
    struct Bucket {
        bool primaryUsed = false;
        std::string primary;
        std::vector<std::string> overflow;
    };

    std::vector<Bucket> buckets_;
    int cap_ = 0;
    int entries_ = 0;
    int entryLimit_ = 0;
    int collisions_ = 0;

    static int nextCapacity(int current) {
        static const int capacities[] = {
            37, 67, 131, 257, 521, 1031, 2053,
            4099, 8209, 16411, 32771, 65543, 129403
        };

        for (int candidate : capacities) {
            if (candidate > current)
                return candidate;
        }

        return (current + capacities[12]) | 1;
    }

    static uint32_t legacyStringHash(const std::string& key) {
        uint32_t hash = 0;

        for (unsigned char c : key)
            hash = hash * 31u + static_cast<uint32_t>(c);

        return hash;
    }

    int slotFor(const std::string& key) const {
        if (cap_ <= 0)
            return -1;

        return static_cast<int>(
            (legacyStringHash(key) & 0x7fffffffu) %
            static_cast<uint32_t>(cap_)
        );
    }

    void putNoGrow(const std::string& key) {
        const int slot = slotFor(key);
        Bucket& bucket = buckets_[static_cast<size_t>(slot)];

        // Duplicate lookup must inspect the entire bucket before deciding
        // whether an unused primary slot can be reused.
        if (bucket.primaryUsed && bucket.primary == key)
            return;

        for (const std::string& existing : bucket.overflow) {
            if (existing == key)
                return;
        }

        if (!bucket.primaryUsed) {
            bucket.primary = key;
            bucket.primaryUsed = true;
            ++entries_;
            return;
        }

        // Legacy collision-chain insertion is immediately after the bucket
        // head, therefore overflow traversal is newest-first.
        bucket.overflow.insert(bucket.overflow.begin(), key);
        ++entries_;
        ++collisions_;
    }

    void grow() {
        const std::vector<std::string> oldOrder = iterationOrder();

        cap_ = nextCapacity(cap_);
        buckets_.assign(static_cast<size_t>(cap_), Bucket());

        entries_ = 0;
        collisions_ = 0;
        entryLimit_ = static_cast<int>(cap_ * 0.75f);

        for (const std::string& key : oldOrder)
            putNoGrow(key);
    }

public:
    void put(const std::string& key) {
        if (entries_ + 1 >= entryLimit_)
            grow();

        putNoGrow(key);
    }

    void remove(const std::string& key) {
        if (cap_ <= 0)
            return;

        const int slot = slotFor(key);
        Bucket& bucket = buckets_[static_cast<size_t>(slot)];

        if (bucket.primaryUsed && bucket.primary == key) {
            bucket.primaryUsed = false;
            bucket.primary.clear();
            --entries_;
            return;
        }

        for (auto it = bucket.overflow.begin();
             it != bucket.overflow.end();
             ++it) {
            if (*it == key) {
                bucket.overflow.erase(it);
                --entries_;
                return;
            }
        }
    }

    std::vector<std::string> iterationOrder() const {
        std::vector<std::string> out;

        if (cap_ <= 0)
            return out;

        out.reserve(static_cast<size_t>(entries_));

        for (const Bucket& bucket : buckets_) {
            if (bucket.primaryUsed)
                out.push_back(bucket.primary);

            for (const std::string& key : bucket.overflow)
                out.push_back(key);
        }

        return out;
    }

    void clear() {
        buckets_.clear();
        cap_ = 0;
        entries_ = 0;
        entryLimit_ = 0;
        collisions_ = 0;
    }

    int capacity() const {
        return cap_;
    }

    int entries() const {
        return entries_;
    }

    int collisions() const {
        return collisions_;
    }

    int bucket(const std::string& key) const {
        return slotFor(key);
    }
};

