    struct LevelSceneResetStats {
        size_t bodies = 0;
        size_t renderTransforms = 0;
        size_t renderMeta = 0;
        int renderOrderEntries = 0;
    };

    LevelSceneResetStats resetLevelSceneForLoad() {
        LevelSceneResetStats st;
        st.bodies = bodies.size();
        st.renderTransforms = renderTransforms.size();
        st.renderMeta = renderMeta236C.size();
        st.renderOrderEntries = renderOrder236C.entries();

        // Level ownership is transactional in the original Lua lifecycle:
        // loadLevelInternal() creates a fresh objects.world/joints/counts/themeSprites
        // set for every load.  The reconstructed native bridge therefore must not
        // retain Box2D/RenderObjectData state from the previous level.  Destroy the
        // old native scene at the level-load boundary before the new level's
        // createBox/createCircle calls materialize its objects.  Explicitly
        // destroy reconstructed joints first; Box2D would also destroy them
        // with their bodies, but clearing our name->pointer records before
        // body teardown prevents stale native handles across level reloads.
        for (auto& kv : joints24431) {
            if (kv.second.joint)
                world.DestroyJoint(kv.second.joint);
        }
        joints24431.clear();
        for (const auto& kv : bodies) {
            if (kv.second) world.DestroyBody(kv.second);
        }
        bodies.clear();
        renderTransforms.clear();
        renderMeta236C.clear();
        renderOrder236C.clear();
        renderCreationOrdinal236C = 0;
        renderHistoryIndex = 0;
        renderAlpha = 0.0f;
        deferredVelocity24421.clear();
        glassWoodAuditArmed24421 = false;
        glassWoodFixedSteps24421 = 0;
        rubberImpacts24471.clear();
        rubberBirdBegins24471 = 0;
        rubberAmbientBegins24471 = 0;
        rubberSolverLogs24471 = 0;
        rubberAfterLogs24471 = 0;
        rubberStepDt24471 = 0.0f;
        springBefore24472.clear();
        springHotUntil24472 = -1;
        springSamples24472 = 0;
        springLines24472 = 0;

        return st;
    }

    b2Body* find(const char* name) {
        auto it = bodies.find(name ? name : "");
        return it == bodies.end() ? nullptr : it->second;
    }

    b2Body* findPrefix(const char* prefix, std::string* matchedName = nullptr) {
        const std::string p = prefix ? prefix : "";
        for (auto& kv : bodies) {
            if (kv.first.rfind(p, 0) == 0) {
                if (matchedName) *matchedName = kv.first;
                return kv.second;
            }
        }
        return nullptr;
    }

    b2Body* findPrefixWithType(const char* prefix, b2BodyType type,
                               std::string* matchedName = nullptr) {
        const std::string p = prefix ? prefix : "";
        for (auto& kv : bodies) {
            if (kv.first.rfind(p, 0) == 0 && kv.second->GetType() == type) {
                if (matchedName) *matchedName = kv.first;
                return kv.second;
            }
        }
        return nullptr;
    }

    int countPrefixWithType(const char* prefix, b2BodyType type) const {
        const std::string p = prefix ? prefix : "";
        int count = 0;
        for (const auto& kv : bodies) {
            if (kv.first.rfind(p, 0) == 0 && kv.second->GetType() == type)
                ++count;
        }
        return count;
    }


    std::string nameOf(const b2Body* body) const {
        for (const auto& kv : bodies) {
            if (kv.second == body)
                return kv.first;
        }
        return std::string();
    }

    static std::string canonicalPair(const std::string& a,
                                     const std::string& b) {
        return a < b ? (a + "|" + b) : (b + "|" + a);
    }

    void dumpContactCandidates(const char* tag,
                               const std::string& focusA,
                               const std::string& focusB) {
        int index = 0;
        for (b2Contact* c = world.GetContactList(); c; c = c->GetNext()) {
            b2Fixture* fa = c->GetFixtureA();
            b2Fixture* fb = c->GetFixtureB();
            const std::string a = nameOf(fa->GetBody());
            const std::string b = nameOf(fb->GetBody());

            const bool relevant =
                a == focusA || b == focusA ||
                a == focusB || b == focusB;
            if (!relevant)
                continue;

            const b2Manifold* m = c->GetManifold();

            std::printf(
                "[stage16-contactdump] %s #%d %s <-> %s "
                "touching=%s enabled=%s sensorA=%s sensorB=%s "
                "manifoldPoints=%d "
                "bodyTypeA=%d bodyTypeB=%d\n",
                tag ? tag : "<tag>",
                index,
                a.c_str(), b.c_str(),
                c->IsTouching() ? "true" : "false",
                c->IsEnabled() ? "true" : "false",
                fa->IsSensor() ? "true" : "false",
                fb->IsSensor() ? "true" : "false",
                m ? m->pointCount : -1,
                (int)fa->GetBody()->GetType(),
                (int)fb->GetBody()->GetType());

            const b2Filter filterA = fa->GetFilterData();
            const b2Filter filterB = fb->GetFilterData();
            std::printf(
                "[stage16-contactdump]   filters "
                "A(cat=0x%04x mask=0x%04x group=%d) "
                "B(cat=0x%04x mask=0x%04x group=%d)\n",
                (unsigned)filterA.categoryBits,
                (unsigned)filterA.maskBits,
                (int)filterA.groupIndex,
                (unsigned)filterB.categoryBits,
                (unsigned)filterB.maskBits,
                (int)filterB.groupIndex);

            ++index;
        }

        if (index == 0) {
            std::printf(
                "[stage16-contactdump] %s no contacts involving "
                "'%s' or '%s'\n",
                tag ? tag : "<tag>",
                focusA.c_str(), focusB.c_str());
        }
    }

