    std::map<std::string, double> scoreTableSnapshot24191() const {
        std::map<std::string, double> out;
        if (!L)
            return out;

        lua_getglobal(L, "scoreTable");
        if (!lua_istable(L, -1)) {
            lua_pop(L, 1);
            return out;
        }

        lua_pushnil(L);
        while (lua_next(L, -2) != 0) {
            std::string key;
            if (lua_type(L, -2) == LUA_TSTRING) {
                const char* k = lua_tostring(L, -2);
                if (k) key = k;
            } else if (lua_type(L, -2) == LUA_TNUMBER) {
                char buf[64];
                std::snprintf(buf, sizeof(buf), "#%.0f", lua_tonumber(L, -2));
                key = buf;
            }

            if (!key.empty() && lua_istable(L, -1)) {
                lua_getfield(L, -1, "score");
                if (lua_isnumber(L, -1))
                    out[key] = lua_tonumber(L, -1);
                lua_pop(L, 1);
            }
            lua_pop(L, 1);
        }
        lua_pop(L, 1);
        return out;
    }

    void logScoreTableDelta24191(
        const char* reason,
        const char* subject,
        const std::map<std::string, double>& before,
        const std::map<std::string, double>& after,
        double globalBefore,
        double globalAfter) const {

        std::set<std::string> keys;
        for (const auto& kv : before) keys.insert(kv.first);
        for (const auto& kv : after) keys.insert(kv.first);

        bool any = false;
        for (const std::string& key : keys) {
            const auto ib = before.find(key);
            const auto ia = after.find(key);
            const double b = (ib == before.end()) ? 0.0 : ib->second;
            const double a = (ia == after.end()) ? 0.0 : ia->second;
            if (std::fabs(a - b) < 0.0001)
                continue;
            any = true;
            std::printf(
                "[stage24.19.1-score-ledger] frame=%d reason=%s subject='%s' "
                "key='%s' before=%.3f after=%.3f delta=%+.3f\n",
                contactFrame,
                reason ? reason : "<none>",
                subject ? subject : "",
                key.c_str(), b, a, a - b);
        }

        if ((std::isfinite(globalBefore) || std::isfinite(globalAfter)) &&
            (!std::isfinite(globalBefore) || !std::isfinite(globalAfter) ||
             std::fabs(globalAfter - globalBefore) >= 0.0001)) {
            any = true;
            std::printf(
                "[stage24.19.1-score-ledger] frame=%d reason=%s subject='%s' "
                "key='__GLOBAL__' before=%.3f after=%.3f delta=%+.3f\n",
                contactFrame,
                reason ? reason : "<none>",
                subject ? subject : "",
                globalBefore, globalAfter, globalAfter - globalBefore);
        }

        if (!any && reason && std::strcmp(reason, "birdCollision") == 0) {
            std::printf(
                "[stage24.19.1-score-ledger] frame=%d reason=birdCollision "
                "subject='%s' delta=NONE\n",
                contactFrame, subject ? subject : "");
        }
    }

