static float stage24242Random01() {
    // KA3D's recovered math path uses the C rand() family. Keep the same
    // process-global RNG domain as the bundled Lua math library rather than
    // introducing a second synthetic generator.
    return static_cast<float>(std::rand()) /
           (static_cast<float>(RAND_MAX) + 1.0f);
}

static float stage24242Uniform(float lo, float hi) {
    return lo + (hi - lo) * stage24242Random01();
}

