    const float h = (float)luaL_checknumber(L, 6);
    const float density = (float)luaL_checknumber(L, 7);
    const float friction = (float)luaL_checknumber(L, 8);
    const float restitution = (float)luaL_checknumber(L, 9);
    const bool renderFlag86 = lua_toboolean(L, 10) != 0;
    const bool renderFlag87 = lua_toboolean(L, 11) != 0;
    const float renderLayer = (float)luaL_checknumber(L, 12);

    b2Body* b = gPhysics->createBox(name, x, y, w, h, density, friction, restitution);
    RenderObjectMeta236C meta;
    meta.flag86=renderFlag86; meta.flag87=renderFlag87; meta.layer=renderLayer; meta.spriteName=sprite ? sprite : "";
    gPhysics->registerRenderMeta236C(name ? name : "", meta);
    create_lua_object_box(L, name, sprite, x, y, w, h);

    std::printf("[Level1/GameLua] BOX    %-18s pos=(%7.3f,%7.3f) size=(%6.3f,%6.3f) density=%5.2f mass=%8.5f render=(f86=%d f87=%d layer=%.3f bucket=%d)\n",
                name, (double)x, (double)y, (double)w, (double)h,
                (double)density, (double)b->GetMass(), renderFlag86?1:0, renderFlag87?1:0,
                (double)renderLayer, gPhysics->renderOrder236C.bucket(name ? name : ""));
