static int l_removeObject(lua_State* L) {
    const char* name = luaL_checkstring(L, 1);
    auto it = gPhysics->bodies.find(name);

    if (it == gPhysics->bodies.end()) {
        std::printf(
            "[stage16-removeObject] name='%s' already absent "
            "from native map\n",
            name);
        return 0;
    }

    b2Body* body = it->second;
    const b2Vec2 p = body->GetPosition();
    const b2Vec2 v = body->GetLinearVelocity();
    const float av = body->GetAngularVelocity();
    const bool wasOutside24441 =
        gStage24440OutsideBodiesPrev.count(name ? name : "") != 0;
    int outsideSince24441 = -1;
    int outsideLinger24441 = -1;
    auto outsideIt24441 = gStage24441OutsideFirstFrame.find(name ? name : "");
    if (outsideIt24441 != gStage24441OutsideFirstFrame.end()) {
        outsideSince24441 = outsideIt24441->second;
        if (gStage24441LastObservedFrame >= outsideSince24441)
            outsideLinger24441 = gStage24441LastObservedFrame - outsideSince24441;
    }
    if (wasOutside24441) {
        std::printf(
            "[stage24.44.1-bounds] REMOVE_OBJECT_WHILE_OUTSIDE frameApprox=%d "
            "body='%s' outsideSince=%d lingerFrames=%d pos=(%.6f,%.6f) "
            "vel=(%.6f,%.6f) speed2=%.9g angVel=%.9g limits=(%d,%d) "
            "action=OBSERVE_ONLY\n",
            gStage24441LastObservedFrame, name ? name : "",
            outsideSince24441, outsideLinger24441,
            (double)p.x, (double)p.y, (double)v.x, (double)v.y,
            (double)(v.x * v.x + v.y * v.y), (double)av,
            gStage24440LevelLimitMinX, gStage24440LevelLimitMaxX);
    }

    // Architectural core recovered from ARMv7 GameLua::removeObject:
    // native object lookup -> b2World::DestroyBody -> remove native record.
    // WoodBlock2_6 is an ordinary unjointed Level1 block.
    gPhysics->world.DestroyBody(body);
    gPhysics->eraseJointRecordsForBodyAfterDestroy24431(name ? name : "");
    gPhysics->bodies.erase(it);
    gPhysics->eraseRenderTransform(name);
    gPhysics->eraseRenderMeta236C(name ? name : "");

    ++gPhysics->nativeRemoveObjectCalls;
    gPhysics->removedObjectNames.emplace_back(name);

    std::printf(
        "[stage16-removeObject] DestroyBody('%s') "
        "pos=(%.6f,%.6f) nativeBodiesNow=%zu\n",
        name, (double)p.x, (double)p.y,
        gPhysics->bodies.size());
    return 0;
}

