static int l_setObjectParameter(lua_State* L) {
    const char* name = luaL_checkstring(L, 1);
    const float selectorF = (float)luaL_checknumber(L, 2);
    const float valueF = (float)luaL_checknumber(L, 3);
    const int selector = (int)selectorF;
    const int valueInt = (int)valueF;

    set_object_field_number(L, name, "lastObjectParameterSelector", selectorF);
    set_object_field_number(L, name, "lastObjectParameterValue", valueF);

    // Recovered from the original ARMv7 GameLua:
    // selector 1 writes RenderObjectData byte +0x89 only when value==1;
    // selector 2 toggles Box2D body type (0=static, nonzero=dynamic).
    if (selector == 1) {
        if (RenderObjectMeta236C* m=gPhysics->renderMeta(name ? name : ""))
            m->flag89 = (valueInt == 1);
    } else if (selector == 2) {
        b2Body* b = gPhysics->find(name);
        if (b) b->SetType(valueF != 0.0f ? b2_dynamicBody : b2_staticBody);
    }
    return 0;
}

