static int l_stage236b_setTopLeft(lua_State* L) {
    const float x = (float)luaL_checknumber(L, 1);
    const float y = (float)luaL_checknumber(L, 2);
    Stage236BCameraBridge& c = gStage236BCamera;
    if (c.havePreviousTopLeft) {
        const float dx = x - c.previousTopLeftX;
        const float dy = y - c.previousTopLeftY;
        c.maxTopLeftStep = std::max(c.maxTopLeftStep, std::sqrt(dx*dx + dy*dy));
    }
    c.topLeftX = x;
    c.topLeftY = y;
    c.previousTopLeftX = x;
    c.previousTopLeftY = y;
    c.havePreviousTopLeft = true;
    ++c.setTopLeftCalls;
    return 0;
}

static int l_stage236b_setWorldScale(lua_State* L) {
    const float scale = (float)luaL_checknumber(L, 1);
    if (!std::isfinite(scale) || scale <= 0.0f)
        return luaL_error(L, "setWorldScale: invalid scale %.9f", (double)scale);
    Stage236BCameraBridge& c = gStage236BCamera;
    c.worldScale = scale;
    c.minWorldScaleSeen = std::min(c.minWorldScaleSeen, scale);
    c.maxWorldScaleSeen = std::max(c.maxWorldScaleSeen, scale);
    ++c.setWorldScaleCalls;
    return 0;
}

