// Stage 24.15.2: the original ARMv7 setTheme() body is now recovered far
// enough to prove the exact Lua keys it consumes: blockTable.themes[theme],
// color, groundColor, bgLayers and fgLayers.  Keep this boundary audit-only
// for one more pass and dump the *actual original Lua values* instead of
// guessing layer names, parallax factors, repetition flags, or offsets.
static std::string stage24152_lua_value_repr(lua_State* L, int idx) {
    const int t = lua_type(L, idx);
    char buf[96];
    switch (t) {
        case LUA_TNIL: return "nil";
        case LUA_TBOOLEAN: return lua_toboolean(L, idx) ? "bool:true" : "bool:false";
        case LUA_TNUMBER:
            std::snprintf(buf, sizeof(buf), "number:%.9g", (double)lua_tonumber(L, idx));
            return buf;
        case LUA_TSTRING: {
            size_t n = 0;
            const char* v = lua_tolstring(L, idx, &n);
            return std::string("string:'") + std::string(v ? v : "", n) + "'";
        }
        case LUA_TTABLE: return "table";
        default: return lua_typename(L, t);
    }
}

static bool stage24152_get_rgb(lua_State* L, int themeTableIndex, const char* field,
                               double* r, double* g, double* b) {
    const int absTheme = themeTableIndex < 0 ? lua_gettop(L) + themeTableIndex + 1 : themeTableIndex;
    lua_getfield(L, absTheme, field);
    if (!lua_istable(L, -1)) { lua_pop(L, 1); return false; }
    lua_getfield(L, -1, "r"); const bool hr = lua_isnumber(L, -1); if (hr) *r = lua_tonumber(L, -1); lua_pop(L, 1);
    lua_getfield(L, -1, "g"); const bool hg = lua_isnumber(L, -1); if (hg) *g = lua_tonumber(L, -1); lua_pop(L, 1);
    lua_getfield(L, -1, "b"); const bool hb = lua_isnumber(L, -1); if (hb) *b = lua_tonumber(L, -1); lua_pop(L, 1);
    lua_pop(L, 1);
    return hr && hg && hb;
}

static void stage24152_dump_layer_table(lua_State* L, int themeTableIndex,
                                        const char* field, int provenArity) {
    const int absTheme = themeTableIndex < 0 ? lua_gettop(L) + themeTableIndex + 1 : themeTableIndex;
    lua_getfield(L, absTheme, field);
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.15.2-theme] %s=<%s>\n", field, lua_typename(L, lua_type(L, -1)));
        lua_pop(L, 1);
        return;
    }
    const int layers = lua_gettop(L);
    int count = 0;
    for (int i = 1;; ++i) {
        lua_rawgeti(L, layers, i);
        if (lua_isnil(L, -1)) { lua_pop(L, 1); break; }
        ++count;
        if (!lua_istable(L, -1)) {
            const std::string v = stage24152_lua_value_repr(L, -1);
            std::printf("[stage24.15.2-theme] %s[%d]=%s\n", field, i, v.c_str());
            lua_pop(L, 1);
            continue;
        }
        const int entry = lua_gettop(L);
        std::string line = std::string("[stage24.15.2-theme] ") + field + "[" + std::to_string(i) + "]";
        for (int j = 1; j <= provenArity; ++j) {
            lua_rawgeti(L, entry, j);
            line += " v" + std::to_string(j) + "=" + stage24152_lua_value_repr(L, -1);
            lua_pop(L, 1);
        }
        std::printf("%s\n", line.c_str());
        lua_pop(L, 1);
    }
    std::printf("[stage24.15.2-theme] %s count=%d\n", field, count);
    lua_pop(L, 1);
}

static void stage24152_dump_theme_contract(lua_State* L, const std::string& theme) {
    const int top = lua_gettop(L);
    lua_getglobal(L, "blockTable");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.15.2-theme] contract theme='%s' blockTable=NOT_TABLE\n", theme.c_str());
        lua_settop(L, top);
        return;
    }
    lua_getfield(L, -1, "themes");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.15.2-theme] contract theme='%s' blockTable.themes=NOT_TABLE\n", theme.c_str());
        lua_settop(L, top);
        return;
    }
    lua_getfield(L, -1, theme.c_str());
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.15.2-theme] contract theme='%s' entry=NOT_TABLE\n", theme.c_str());
        lua_settop(L, top);
        return;
    }
    const int themeTable = lua_gettop(L);
    double cr=0, cg=0, cb=0, gr=0, gg=0, gb=0;
    const bool haveColor = stage24152_get_rgb(L, themeTable, "color", &cr, &cg, &cb);
    const bool haveGround = stage24152_get_rgb(L, themeTable, "groundColor", &gr, &gg, &gb);
    std::printf("[stage24.15.2-theme] contract theme='%s' color=%s(%.9g,%.9g,%.9g) groundColor=%s(%.9g,%.9g,%.9g)\n",
                theme.c_str(), haveColor ? "RGB" : "MISSING", cr,cg,cb,
                haveGround ? "RGB" : "MISSING", gr,gg,gb);
    // ARMv7 setTheme() proves bgLayers entries consume indices 1..6 and
    // fgLayers consume indices 1..2.  Dump exactly those slots, preserving
    // nil/default evidence for the next implementation pass.
    stage24152_dump_layer_table(L, themeTable, "bgLayers", 6);
    stage24152_dump_layer_table(L, themeTable, "fgLayers", 2);
    lua_settop(L, top);
}


static bool stage24153_parse_theme_scene(lua_State* L, const std::string& theme) {
    const int top = lua_gettop(L);
    Stage24153ThemeScene next;
    next.theme = theme;

    lua_getglobal(L, "blockTable");
    if (!lua_istable(L, -1)) { lua_settop(L, top); return false; }
    lua_getfield(L, -1, "themes");
    if (!lua_istable(L, -1)) { lua_settop(L, top); return false; }
    lua_getfield(L, -1, theme.c_str());
    if (!lua_istable(L, -1)) { lua_settop(L, top); return false; }
    const int themeTable = lua_gettop(L);

    double cr=0, cg=0, cb=0, gr=0, gg=0, gb=0;
    if (!stage24152_get_rgb(L, themeTable, "color", &cr, &cg, &cb) ||
        !stage24152_get_rgb(L, themeTable, "groundColor", &gr, &gg, &gb)) {
        lua_settop(L, top);
        return false;
    }
    next.colorR=(float)cr; next.colorG=(float)cg; next.colorB=(float)cb;
    next.groundR=(float)gr; next.groundG=(float)gg; next.groundB=(float)gb;

    lua_getfield(L, themeTable, "bgLayers");
    if (!lua_istable(L, -1)) { lua_settop(L, top); return false; }
    const int bgTable = lua_gettop(L);
    for (int i=1;;++i) {
        lua_rawgeti(L, bgTable, i);
        if (lua_isnil(L, -1)) { lua_pop(L,1); break; }
        if (!lua_istable(L, -1)) { lua_settop(L, top); return false; }
        const int entry=lua_gettop(L);
        Stage24153BgLayer b;
        lua_rawgeti(L, entry, 1);
        if (!lua_isstring(L,-1)) { lua_settop(L, top); return false; }
        b.sheet=lua_tostring(L,-1); lua_pop(L,1);
        lua_rawgeti(L, entry, 2);
        if (!lua_isstring(L,-1)) { lua_settop(L, top); return false; }
        b.sprite=lua_tostring(L,-1); lua_pop(L,1);
        lua_rawgeti(L, entry, 3);
        b.parallax=lua_isnumber(L,-1) ? (float)lua_tonumber(L,-1) : 1.0f;
        lua_pop(L,1);
        lua_rawgeti(L, entry, 4);
        b.layerScale=lua_isnumber(L,-1) ? (float)lua_tonumber(L,-1) : 1.0f;
        lua_pop(L,1);
        lua_rawgeti(L, entry, 5);
        b.repeat=lua_isboolean(L,-1) ? (lua_toboolean(L,-1)!=0) : true;
        lua_pop(L,1);
        lua_rawgeti(L, entry, 6);
        b.offset=lua_isnumber(L,-1) ? (float)lua_tonumber(L,-1) : 4.0f;
        lua_pop(L,1);
        if (!std::isfinite(b.parallax) || !std::isfinite(b.layerScale) || b.layerScale<=0.0f ||
            !std::isfinite(b.offset)) { lua_settop(L, top); return false; }
        next.bg.push_back(std::move(b));
        lua_pop(L,1);
    }
    lua_pop(L,1); // bgLayers

    lua_getfield(L, themeTable, "fgLayers");
    if (!lua_istable(L, -1)) { lua_settop(L, top); return false; }
    const int fgTable=lua_gettop(L);
    for (int i=1;;++i) {
        lua_rawgeti(L, fgTable, i);
        if (lua_isnil(L,-1)) { lua_pop(L,1); break; }
        if (!lua_istable(L,-1)) { lua_settop(L,top); return false; }
        const int entry=lua_gettop(L);
        Stage24153FgLayer f;
        lua_rawgeti(L,entry,1);
        if (!lua_isstring(L,-1)) { lua_settop(L,top); return false; }
        f.sheet=lua_tostring(L,-1); lua_pop(L,1);
        lua_rawgeti(L,entry,2);
        if (!lua_isstring(L,-1)) { lua_settop(L,top); return false; }
        f.sprite=lua_tostring(L,-1); lua_pop(L,1);
        next.fg.push_back(std::move(f));
        lua_pop(L,1);
    }
    lua_pop(L,1); // fgLayers

    next.valid = !next.bg.empty() && !next.fg.empty();
    lua_settop(L, top);
    if (!next.valid) return false;
    gStage24153ThemeScene = std::move(next);
    return true;
}

static int l_stage24152_setTheme_audit(lua_State* L) {
    const char* raw = luaL_checkstring(L, 1);
    const std::string theme = raw ? raw : "";
    const double currentThemeIndex = get_global_number(L, "currentThemeIndex");
    const std::string levelName = get_global_string(L, "levelName");
    const bool parsed = stage24153_parse_theme_scene(L, theme);
    if (!parsed)
        return luaL_error(L, "setTheme: exact original scene contract unavailable for '%s'", theme.c_str());
    // updateGame may call this boundary repeatedly. Log and inspect only a
    // distinct theme/level state so diagnostics stay compact.
    static std::string lastTheme;
    static std::string lastLevel;
    if (theme != lastTheme || levelName != lastLevel) {
        lastTheme = theme;
        lastLevel = levelName;
        std::printf("[stage24.15.3-theme] setTheme call theme='%s' currentThemeIndex=%.6f level='%s' semantic=ARMV7_SETTHEME_RECONSTRUCTED\n",
                    theme.c_str(), currentThemeIndex, levelName.c_str());
        stage24152_dump_theme_contract(L, theme);
        S24I("Stage24.15.3 reconstructed setTheme theme=%s currentThemeIndex=%.6f level=%s bg=%d fg=%d",
             theme.c_str(), currentThemeIndex, levelName.c_str(),
             (int)gStage24153ThemeScene.bg.size(), (int)gStage24153ThemeScene.fg.size());
        std::fflush(stdout);
    }
    return 0;
}

