static std::string stage24130_arg_summary(lua_State* L, int idx) {
    const int t = lua_type(L, idx);
    char buf[128];
    switch (t) {
        case LUA_TNIL: return "nil";
        case LUA_TBOOLEAN: return lua_toboolean(L, idx) ? "true" : "false";
        case LUA_TNUMBER:
            std::snprintf(buf, sizeof(buf), "%.4f", (double)lua_tonumber(L, idx));
            return buf;
        case LUA_TSTRING: {
            const char* v = lua_tostring(L, idx);
            std::string out = v ? v : "";
            if (out.size() > 80) out = out.substr(0, 77) + "...";
            return std::string("'") + out + "'";
        }
        case LUA_TTABLE: return "<table>";
        case LUA_TFUNCTION: return lua_iscfunction(L, idx) ? "<C-function>" : "<Lua-function>";
        default: return lua_typename(L, t);
    }
}

static int l_stage24130_draw_audit(lua_State* L) {
    if (!gStage24132AuditActive) return 0;
    const char* name = lua_tostring(L, lua_upvalueindex(1));
    ++gStage24130PrimitiveCalls;
    std::string args;
    const int n = lua_gettop(L);
    const int show = std::min(n, 16);
    for (int i = 1; i <= show; ++i) {
        if (!args.empty()) args += ", ";
        args += stage24130_arg_summary(L, i);
    }
    if (n > show) args += ", ...";
    std::printf("[stage24.13-draw-audit] call=%d fn=%s argc=%d args=[%s]\n",
                gStage24130PrimitiveCalls, name ? name : "<unknown>", n, args.c_str());
    return 0;
}

static void stage24130_set_global_audit(lua_State* L, const char* name) {
    lua_pushstring(L, name);
    lua_pushcclosure(L, l_stage24130_draw_audit, 1);
    lua_setglobal(L, name);
}

static void stage24132_log_real_call(lua_State* L, const char* name) {
    if (!gStage24132AuditActive) return;
    ++gStage24130PrimitiveCalls;
    std::string args;
    const int n = lua_gettop(L);
    const int show = std::min(n, 16);
    for (int i = 1; i <= show; ++i) {
        if (!args.empty()) args += ", ";
        args += stage24130_arg_summary(L, i);
    }
    if (n > show) args += ", ...";
    std::printf("[stage24.13-draw-audit] call=%d fn=%s argc=%d args=[%s]\n",
                gStage24130PrimitiveCalls, name, n, args.c_str());
}

