static bool stage24242ReadParticleDefinition(lua_State* L,
                                               const std::string& type,
                                               Stage24242ParticleDefinition* out) {
    auto cached = gStage24242ParticleDefs.find(type);
    if (cached != gStage24242ParticleDefs.end()) {
        *out = cached->second;
        return out->valid;
    }

    Stage24242ParticleDefinition d;
    d.type = type;
    lua_getglobal(L, "particleTable");
    if (!lua_istable(L, -1)) { lua_pop(L, 1); return false; }
    lua_getfield(L, -1, "particles");
    if (!lua_istable(L, -1)) { lua_pop(L, 2); return false; }
    lua_getfield(L, -1, type.c_str());
    if (!lua_istable(L, -1)) { lua_pop(L, 3); return false; }
    const int item = lua_gettop(L);

    auto num = [&](const char* key, float fallback)->float {
        lua_getfield(L, item, key);
        float v = fallback;
        if (lua_isnumber(L, -1)) {
            const double x = static_cast<double>(lua_tonumber(L, -1));
            if (std::isfinite(x)) v = static_cast<float>(x);
        }
        lua_pop(L, 1);
        return v;
    };
    auto str = [&](const char* key)->std::string {
        lua_getfield(L, item, key);
        std::string v;
        if (lua_isstring(L, -1)) {
            const char* p = lua_tostring(L, -1);
            if (p) v = p;
        }
        lua_pop(L, 1);
        return v;
    };

    d.sheet = str("sheet");
    d.minVel = num("minVel", 0.f);
    d.maxVel = num("maxVel", 0.f);
    d.gravityX = num("gravityX", 0.f);
    d.gravityY = num("gravityY", 0.f);
    d.minAngleVel = num("minAngleVel", 0.f);
    d.maxAngleVel = num("maxAngleVel", 0.f);
    d.minScaleBegin = num("minScaleBegin", 1.f);
    d.maxScaleBegin = num("maxScaleBegin", 1.f);
    d.minScaleEnd = num("minScaleEnd", 1.f);
    d.maxScaleEnd = num("maxScaleEnd", 1.f);
    d.lifeTime = num("lifeTime", 0.f);
    d.animationLifeTime = (str("animation") == "lifeTime");

    lua_getfield(L, item, "randomizeBirthPosition");
    d.randomizeBirthPosition = lua_isnil(L, -1) ? true : (lua_toboolean(L, -1) != 0);
    lua_pop(L, 1);

    lua_getfield(L, item, "sprites");
    if (lua_istable(L, -1)) {
        const int n = static_cast<int>(lua_objlen(L, -1));
        d.sprites.reserve(std::max(0, n));
        for (int i = 1; i <= n; ++i) {
            lua_rawgeti(L, -1, i);
            if (lua_isstring(L, -1)) {
                const char* p = lua_tostring(L, -1);
                if (p) d.sprites.emplace_back(p);
            }
            lua_pop(L, 1);
        }
    }
    lua_pop(L, 1); // sprites
    lua_pop(L, 3); // item, particleTable.particles, particleTable

    d.valid = !d.sheet.empty() && !d.sprites.empty() &&
              std::isfinite(d.lifeTime) && d.lifeTime > 0.f;
    gStage24242ParticleDefs[type] = d;
    *out = d;
    return d.valid;
}

static int l_headless_particle_addParticles(lua_State* L) {
    ++gHeadlessParticleSpawnCalls;
    ++gStage24242SpawnRequests;

    // Exact native signature recovered in Stage 24.24.0/1:
    //   addParticles(type, count, x, y, width, height, angle, bypassLimits)
    const char* typeRaw = lua_isstring(L, 1) ? lua_tostring(L, 1) : nullptr;
    const std::string type = typeRaw ? typeRaw : std::string();
    float count  = lua_isnumber(L, 2) ? static_cast<float>(lua_tonumber(L, 2)) : 0.f;
    const float x      = lua_isnumber(L, 3) ? static_cast<float>(lua_tonumber(L, 3)) : 0.f;
    const float y      = lua_isnumber(L, 4) ? static_cast<float>(lua_tonumber(L, 4)) : 0.f;
    const float width  = lua_isnumber(L, 5) ? static_cast<float>(lua_tonumber(L, 5)) : 0.f;
    const float height = lua_isnumber(L, 6) ? static_cast<float>(lua_tonumber(L, 6)) : 0.f;
    const float emitterAngle = lua_isnumber(L, 7) ? static_cast<float>(lua_tonumber(L, 7)) : 0.f;
    const bool bypassLimits = lua_toboolean(L, 8) != 0;

    Stage24242ParticleDefinition d;
    if (type.empty() || !stage24242ReadParticleDefinition(L, type, &d)) {
        std::fprintf(stderr,
            "[stage24.24.2-particles] definition unavailable type='%s'\n",
            type.empty() ? "<non-string>" : type.c_str());
        return 0;
    }

    const int activeBefore = static_cast<int>(gStage24242Particles.size());
    const float requestedCount = count;
    bool softApplied = false;
    bool hardApplied = false;
    if (!bypassLimits) {
        if (static_cast<float>(activeBefore) + count > 40.f) {
            count *= 0.5f;
            softApplied = true;
        }
        if (static_cast<float>(activeBefore) + count > 125.f) {
            count = 125.f - static_cast<float>(activeBefore);
            hardApplied = true;
        }
    }
    if (!(count > 0.f) || !std::isfinite(count)) {
        std::printf(
            "[stage24.24.2-particle-spawn] type='%s' requested=%.6f adjusted=%.6f activeBefore=%d created=0 soft=%s hard=%s bypass=%s\n",
            type.c_str(), (double)requestedCount, (double)count, activeBefore,
            softApplied ? "yes" : "no", hardApplied ? "yes" : "no",
            bypassLimits ? "yes" : "no");
        return 0;
    }

    constexpr float kPi = 3.14159265358979323846f;
    const float ec = std::cos(emitterAngle);
    const float es = std::sin(emitterAngle);
    int created = 0;
    for (int i = 0; static_cast<float>(i) < count; ++i) {
        Stage24242Particle p;
        p.type = type;
        p.sheet = d.sheet;
        p.sprites = d.sprites;
        p.animationLifeTime = d.animationLifeTime;
        p.lifeTime = d.lifeTime;
        p.gravityX = d.gravityX;
        p.gravityY = d.gravityY;

        if (d.randomizeBirthPosition) {
            const float dx = (stage24242Random01() - 0.5f) * width;
            const float dy = (stage24242Random01() - 0.5f) * height;
            p.x = x + dx * ec - dy * es;
            p.y = y + dx * es + dy * ec;
        } else {
            p.x = x;
            p.y = y;
        }

        p.vx = stage24242Uniform(d.minVel, d.maxVel);
        p.vy = stage24242Uniform(d.minVel, d.maxVel);
        p.angle = stage24242Uniform(0.f, 360.f) * (kPi / 180.f);
        p.angularVelocity = stage24242Uniform(d.minAngleVel, d.maxAngleVel);
        p.startScale = stage24242Uniform(d.minScaleBegin, d.maxScaleBegin);
        p.endScale = stage24242Uniform(d.minScaleEnd, d.maxScaleEnd);
        p.scale = p.startScale;
        p.age = 0.f;

        if (p.animationLifeTime) {
            p.spriteIndex = 0;
        } else {
            int index = static_cast<int>(stage24242Random01() * static_cast<float>(p.sprites.size()));
            if (index < 0) index = 0;
            if (index >= static_cast<int>(p.sprites.size()))
                index = static_cast<int>(p.sprites.size()) - 1;
            p.spriteIndex = index;
        }

        gStage24242Particles.push_back(std::move(p));
        ++created;
        ++gStage24242ParticlesBorn;
    }

    std::printf(
        "[stage24.24.2-particle-spawn] type='%s' requested=%.6f adjusted=%.6f activeBefore=%d created=%d activeAfter=%zu soft=%s hard=%s bypass=%s emitter=(%.3f,%.3f %.3fx%.3f angle=%.6f) source=ARMV7_PARTICLES_ADDPARTICLES_EXACT\n",
        type.c_str(), (double)requestedCount, (double)count, activeBefore,
        created, gStage24242Particles.size(), softApplied ? "yes" : "no",
        hardApplied ? "yes" : "no", bypassLimits ? "yes" : "no",
        (double)x, (double)y, (double)width, (double)height,
        (double)emitterAngle);
    return 0;
}

static void stage24242UpdateParticles(float dt) {
    if (!(dt > 0.f) || !std::isfinite(dt) || gStage24242Particles.empty()) return;
    size_t write = 0;
    for (size_t read = 0; read < gStage24242Particles.size(); ++read) {
        Stage24242Particle p = std::move(gStage24242Particles[read]);
        p.age += dt;
        if (p.age > p.lifeTime) {
            ++gStage24242ParticlesExpired;
            continue;
        }

        p.vx += p.gravityX * dt;
        p.vy += p.gravityY * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.angle += p.angularVelocity * dt;
        const float t = p.lifeTime > 0.f ? p.age / p.lifeTime : 1.f;
        p.scale = p.startScale + (p.endScale - p.startScale) * t;

        if (p.animationLifeTime && !p.sprites.empty()) {
            int frame = static_cast<int>(std::ceil(
                static_cast<float>(p.sprites.size()) * p.age / p.lifeTime));
            if (frame < 1) frame = 1;
            if (frame > static_cast<int>(p.sprites.size()))
                frame = static_cast<int>(p.sprites.size());
            p.spriteIndex = frame - 1;
        }

        if (write != read) gStage24242Particles[write] = std::move(p);
        else gStage24242Particles[write] = std::move(p);
        ++write;
    }
    gStage24242Particles.resize(write);
}


static bool install_particle_environment_bridge(lua_State* L) {
    // Original split recovered in Stage 13:
    //
    //   particleTable.particles[type]  -> definitions from particles.lua
    //   _G.particles.addParticles(...) -> runtime/native particle surface
    //
    // Executing particles.lua directly in the bootstrap leaves only the
    // definitions table in _G.particles, so preserve it under particleTable.
    lua_getglobal(L, "particles");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        std::fprintf(stderr,
            "[stage16-particles] particles.lua definitions table missing\n");
        return false;
    }

    const int definitions = lua_gettop(L);
    int definitionCount = 0;
    lua_pushnil(L);
    while (lua_next(L, definitions) != 0) {
        ++definitionCount;
        lua_pop(L, 1);
    }

    lua_newtable(L);
    lua_pushvalue(L, definitions);
    lua_setfield(L, -2, "particles");
    lua_setglobal(L, "particleTable");

    // Temporary runtime table. initialize()/loadLevelInternal() will recreate
    // _G.particles, so the method surface is attached again after loading.
    lua_newtable(L);
    lua_setglobal(L, "particles");

    lua_pop(L, 1);  // definitions

    lua_pushnumber(L, 0.0f);
    lua_setglobal(L, "particleAmount");

    std::printf(
        "[stage16-particles] reconstructed namespace split: "
        "particleTable.particles definitions=%d\n",
        definitionCount);
    return true;
}


static bool attach_particle_runtime_surface(lua_State* L) {
    // A level load/restart reconstructs the original native particle runtime.
    gStage24242Particles.clear();

    // Exact original Lua resets:
    //   initialize()       -> _G.particles = {}
    //   loadLevelInternal()-> _G.particles = {}
    //
    // Attach the native runtime method only after the final level-loader reset.
    lua_getglobal(L, "particles");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        std::fprintf(stderr,
            "[stage16-particles] post-loader runtime particles table missing\n");
        return false;
    }

    const int runtimeTable = lua_gettop(L);

    // Keep addParticles out of pairs(particles) by exposing it through __index.
    lua_newtable(L);  // runtime, mt
    lua_newtable(L);  // runtime, mt, methods
    lua_pushcfunction(L, l_headless_particle_addParticles);
    lua_setfield(L, -2, "addParticles");
    lua_setfield(L, -2, "__index");
    lua_setmetatable(L, runtimeTable);

    lua_getfield(L, runtimeTable, "addParticles");
    const bool ok = lua_isfunction(L, -1);
    lua_pop(L, 2);

    std::printf(
        "[stage16-particles] post-loader runtime surface attached: "
        "_G.particles.addParticles=%s\n",
        ok ? "function" : "MISSING");
    return ok;
}



// Stage 23.6B intentionally removed the old native camera-profile alias.
// Original initCameras() now owns deviceModel profile fallback/copy.

// Stage 24.12.8: the original GameLua resource boundary receives logical
// level paths such as "data/levels/pack1/Level1" (without a .lua suffix).
// The old harness called luaL_loadfile() on that logical name verbatim, which
// only worked for the initial Stage24 smoke because that first call supplied
// an absolute argv[2] path.  Reconstruct the resource-path part of the native
// boundary here: preserve an already-existing/absolute path, otherwise resolve
// the logical path below the app-private Stage24 root and append .lua when the
// script omitted it.
static bool stage24128_regular_file_exists(const std::string& path) {
    std::ifstream f(path.c_str(), std::ios::binary);
    return f.good();
}

static bool stage24128_has_lua_suffix(const std::string& path) {
    return path.size() >= 4 && path.compare(path.size() - 4, 4, ".lua") == 0;
}

static std::string stage24128_resolve_lua_resource_path(const std::string& logical) {
    std::vector<std::string> candidates;
    candidates.push_back(logical);
    if (!stage24128_has_lua_suffix(logical))
        candidates.push_back(logical + ".lua");

    const bool absolute = !logical.empty() && logical[0] == '/';
    const bool dataRelativeLevel = !absolute && logical.rfind("levels/", 0) == 0;
    if (!absolute && !gStage24Root.empty()) {
        // Stage 24.47.0A: the untouched Golden Eggs menu is the first caller
        // that supplies a level path relative to the original data root
        // ("levels/goldeneggs1/...") instead of spelling "data/levels/...".
        // The original resource boundary searches that data root. Reconstruct
        // that generic search-root candidate rather than special-casing any GE
        // filename or menu slot.
        if (dataRelativeLevel) {
            candidates.push_back(gStage24Root + "/data/" + logical);
            if (!stage24128_has_lua_suffix(logical))
                candidates.push_back(gStage24Root + "/data/" + logical + ".lua");
        }
        candidates.push_back(gStage24Root + "/" + logical);
        if (!stage24128_has_lua_suffix(logical))
            candidates.push_back(gStage24Root + "/" + logical + ".lua");
    }

    for (const std::string& candidate : candidates) {
        if (stage24128_regular_file_exists(candidate))
            return candidate;
    }

    // Keep a deterministic resolved name in the eventual Lua error.  For
    // logical paths this is the app-private resource candidate the bridge
    // expected; for absolute paths it remains the caller's original path.
    if (!absolute && !gStage24Root.empty()) {
        if (dataRelativeLevel) {
            return gStage24Root + "/data/" + logical +
                   (stage24128_has_lua_suffix(logical) ? "" : ".lua");
        }
        return gStage24Root + "/" + logical +
               (stage24128_has_lua_suffix(logical) ? "" : ".lua");
    }
    return logical;
}


// Stage 24.15.0: audit the exact per-level scene contract before reconstructing
// skies/parallax/foreground.  This is telemetry only: it never creates, moves,
// filters or redraws an object.  The untouched level environment is inspected
// exactly as produced by the original level chunk.
static int stage24150_abs_index(lua_State* L, int idx) {
    return idx < 0 ? lua_gettop(L) + idx + 1 : idx;
}

static std::string stage24150_field_string(lua_State* L, int idx, const char* key) {
    idx = stage24150_abs_index(L, idx);
    lua_getfield(L, idx, key);
    const char* v = lua_isstring(L, -1) ? lua_tostring(L, -1) : nullptr;
    const std::string out = v ? v : "";
    lua_pop(L, 1);
    return out;
}

static bool stage24150_field_number(lua_State* L, int idx, const char* key, double* out) {
    idx = stage24150_abs_index(L, idx);
    lua_getfield(L, idx, key);
    const bool ok = lua_isnumber(L, -1);
    if (ok && out) *out = (double)lua_tonumber(L, -1);
    lua_pop(L, 1);
    return ok;
}

static void stage24150_dump_level_scene_contract(lua_State* L, int envIdx,
                                                  const std::string& logical) {
    envIdx = stage24150_abs_index(L, envIdx);
    const int base = lua_gettop(L);

    const std::string theme = stage24150_field_string(L, envIdx, "theme");
    double worldGravity = NAN, physicsToWorld = NAN, waterLevel = NAN;
    const bool hasGravity = stage24150_field_number(L, envIdx, "worldGravity", &worldGravity);
    const bool hasPtw = stage24150_field_number(L, envIdx, "physicsToWorld", &physicsToWorld);
    const bool hasWater = stage24150_field_number(L, envIdx, "waterLevel", &waterLevel);

    lua_getfield(L, envIdx, "themeSprites");
    int themeSpriteCount = 0;
    if (lua_istable(L, -1)) {
        lua_pushnil(L);
        while (lua_next(L, -2) != 0) {
            ++themeSpriteCount;
            if (lua_istable(L, -1)) {
                const std::string definition = stage24150_field_string(L, -1, "definition");
                const std::string name = stage24150_field_string(L, -1, "name");
                double x=NAN, y=NAN, layer=NAN, angle=NAN;
                const bool hx=stage24150_field_number(L, -1, "x", &x);
                const bool hy=stage24150_field_number(L, -1, "y", &y);
                const bool hl=stage24150_field_number(L, -1, "layer", &layer);
                const bool ha=stage24150_field_number(L, -1, "angle", &angle);
                std::printf("[stage24.15.0-scene] themeSprite level='%s' index=%d name='%s' definition='%s' x=%s%.6f y=%s%.6f layer=%s%.6f angle=%s%.6f\n",
                            logical.c_str(), themeSpriteCount, name.c_str(), definition.c_str(),
                            hx?"":"<nil>", hx?x:0.0, hy?"":"<nil>", hy?y:0.0,
                            hl?"":"<nil>", hl?layer:0.0, ha?"":"<nil>", ha?angle:0.0);
            }
            lua_pop(L, 1);
        }
    }
    lua_pop(L, 1);

    std::printf("[stage24.15.0-scene] levelContract level='%s' theme='%s' themeSprites=%d physicsToWorld=%s%.6f worldGravity=%s%.6f waterLevel=%s%.6f\n",
                logical.c_str(), theme.c_str(), themeSpriteCount,
                hasPtw?"":"<nil>", hasPtw?physicsToWorld:0.0,
                hasGravity?"":"<nil>", hasGravity?worldGravity:0.0,
                hasWater?"":"<nil>", hasWater?waterLevel:0.0);
    S24I("Stage24.15.0 scene contract level=%s theme=%s themeSprites=%d",
         logical.c_str(), theme.empty()?"<nil>":theme.c_str(), themeSpriteCount);
    lua_settop(L, base);
}

static void stage24262_reset_trajectory_for_level_load(const char* logical);

static int l_loadLevel(lua_State* L) {
    const char* raw = luaL_checkstring(L, 1);
    const std::string logical = raw ? raw : "";
    const std::string path = stage24128_resolve_lua_resource_path(logical);
    std::printf("[stage24.12.8-levelpath] loadLevel logical='%s' resolved='%s'\n",
                logical.c_str(), path.c_str());
    S24I("ARMv7 loadLevel resource path logical=%s resolved=%s",
         logical.c_str(), path.c_str());

    int rc = luaL_loadfile(L, path.c_str());
    if (rc != 0) {
        return luaL_error(L, "loadLevel: luaL_loadfile failed logical='%s' resolved='%s': %s",
                          logical.c_str(), path.c_str(), lua_tostring(L, -1));
    }

    // Reconstruct the old GameLua level-loading environment:
    // level globals are written into a private table while reads fall through
    // to the game global environment. The resulting table becomes loadedObjects.
    lua_newtable(L);                 // func, env
    lua_newtable(L);                 // func, env, mt
    lua_pushvalue(L, LUA_GLOBALSINDEX);
    lua_setfield(L, -2, "__index");
    lua_setmetatable(L, -2);         // func, env

    lua_pushvalue(L, -1);            // func, env, env-copy
    lua_setfenv(L, -3);              // func, env

    lua_insert(L, -2);               // env, func
    rc = lua_pcall(L, 0, 0, 0);     // env
    if (rc != 0) {
        const char* err = lua_tostring(L, -1);
        return luaL_error(L, "loadLevel: level chunk failed: %s",
                          err ? err : "<no message>");
    }

    // Stack now holds the private level environment.

    stage24150_dump_level_scene_contract(L, -1, logical);

    // Stage 24.14.6: each successful level load owns a fresh native scene.
    // The untouched Lua loadLevelInternal() has already entered a new-level
    // lifecycle and will materialize this private level table through
    // createBox/createCircle after loadLevel() returns.  Clear only the
    // previous level's native Box2D/render ownership here; resource atlases,
    // menus, fonts and global Lua state are intentionally untouched.
    PhysicsBridge::LevelSceneResetStats resetStats;
    if (gPhysics) resetStats = gPhysics->resetLevelSceneForLoad();
    std::printf("[stage24.14.6-lifecycle] native level scene reset logical='%s' bodies=%zu transforms=%zu renderMeta=%zu renderOrder=%d\n",
                logical.c_str(), resetStats.bodies, resetStats.renderTransforms,
                resetStats.renderMeta, resetStats.renderOrderEntries);
    S24I("Stage24.14.6 native level scene reset logical=%s bodies=%zu transforms=%zu renderMeta=%zu renderOrder=%d",
         logical.c_str(), resetStats.bodies, resetStats.renderTransforms,
         resetStats.renderMeta, resetStats.renderOrderEntries);

    // Untouched ARMv7 GameLua::loadLevel clears all six normal trajectory
    // arrays and all six puff arrays while preserving the current 0/3 bank
    // selector.  Mirror that native ownership at the same per-level boundary.
    stage24262_reset_trajectory_for_level_load(logical.c_str());

    lua_getglobal(L, "deviceModel");
    const char* deviceModel =
        lua_isstring(L, -1) ? lua_tostring(L, -1) : "android";
    const std::string deviceModelCopy = deviceModel ? deviceModel : "android";
    lua_pop(L, 1);

    // Stage 23.6B deliberately does NOT alias camera profiles in native code.
    // The original 1.4.2 initCameras() bytecode contains its own
    // deviceModel fallback/copy path (including iphone -> android) and is now
    // allowed to execute unchanged.
    std::printf("[GameLua] camera profile resolution delegated to ORIGINAL initCameras deviceModel='%s'\n",
                deviceModelCopy.c_str());

    lua_getfield(L, -1, "world");
    int worldCount = 0;
    if (lua_istable(L, -1)) {
        lua_pushnil(L);
        while (lua_next(L, -2) != 0) {
            ++worldCount;
            lua_pop(L, 1);
        }
    }
    lua_pop(L, 1);

    lua_getfield(L, -1, "physicsToWorld");
    const double ptw = lua_isnumber(L, -1) ? (double)lua_tonumber(L, -1) : -1.0;
    lua_pop(L, 1);

    lua_pushvalue(L, -1);
    lua_setglobal(L, "loadedObjects");
    lua_pop(L, 1);

    // Stage 24.13.4a: loadLevelInternal() recreates _G.particles = {} on
    // every load/restart before it calls the native loadLevel boundary.
    // The original runtime particle service therefore has to be rebound for
    // every level load, not only after the bootstrap load.  This is the same
    // namespace/lifecycle semantics recovered in Stage 14.2 / 16.1; moving
    // the attachment to this per-load boundary prevents Restart from leaving
    // particles.addParticles nil on the next collision.
    if (!attach_particle_runtime_surface(L)) {
        return luaL_error(L,
            "loadLevel: failed to restore runtime particles.addParticles surface");
    }
    std::printf("[stage24.13.4a-reload] particle runtime surface restored logical='%s'\n",
                logical.c_str());

    std::printf("[GameLua] loadLevel -> loadedObjects world=%d physicsToWorld=%.6f\n",
                worldCount, ptw);
    return 0;
}


