// Stage 24.25.2: first audible backend, constrained to the exact untouched
// WAV contract recovered in Stage24.25.1: PCM format=1, 16 kHz, signed 16-bit,
// 167 mono files + one stereo file.  The original Lua createAssets() audio
// slice still owns alias/group construction; this bridge only implements the
// native Resources/AudioOutput side that the untouched Lua calls.
struct Stage24252AudioClip {
    std::string logicalPath;
    int channels = 0;
    int sampleRate = 0;
    int peakAbs = 0;
    std::vector<int16_t> samples;
    bool loaded = false;
    bool supported = false;
    bool isMp3 = false;
    bool decodeAttempted = false;
};

struct Stage24252AudioVoice {
    bool active = false;
    int handle = -1;
    std::string alias;
    const Stage24252AudioClip* clip = nullptr;
    size_t frame = 0;
    float volume = 1.0f;
    bool loop = false;
    int track = 0;
    // Stage 24.25.8 diagnostic-only lifecycle counters. They do not alter
    // playback semantics; they prove the recovered EOF/loop behavior against
    // real MP3/WAV voices in the ARM64 runtime.
    unsigned long long loopWraps = 0;
};

struct Stage24252AudioBackend {
    std::mutex mutex;
    std::map<std::string, Stage24252AudioClip> clips;
    std::vector<Stage24252AudioVoice> voices;
    std::array<float, 16> trackVolume{};
    float masterVolume = 1.0f;
    bool outputEnabled = true;
    int nextHandle = 0;
    unsigned long long createCalls = 0;
    unsigned long long playCalls = 0;
    unsigned long long successfulPlays = 0;
    unsigned long long missingPlays = 0;
    unsigned long long unsupportedCreates = 0;
    unsigned long long wavCreates = 0;
    unsigned long long mp3Creates = 0;
    unsigned long long mp3Decoded = 0;
    unsigned long long mp3DecodeFailures = 0;

    // Stage 24.25.8 diagnostic-only closure counters.
    unsigned long long voiceEnds = 0;
    unsigned long long loopWraps = 0;
    unsigned long long queryCalls = 0;
    unsigned long long stopByNameCalls = 0;
    unsigned long long stopAllCalls = 0;
    unsigned long long outputStopCalls = 0;
    unsigned long long outputStartCalls = 0;

    // Stage24.25.3 diagnostic counters. These are written while mutex is held
    // (the OpenSL callback takes the same mutex), so snapshots are coherent.
    unsigned long long callbackCalls = 0;
    unsigned long long callbackEnqueues = 0;
    unsigned long long callbackNonZeroBuffers = 0;
    unsigned long long callbackSilentBuffers = 0;
    int lastCallbackPeak = 0;
    int maxCallbackPeak = 0;
    int primePeak0 = 0;
    int primePeak1 = 0;

    SLObjectItf engineObject = nullptr;
    SLEngineItf engine = nullptr;
    SLObjectItf outputMixObject = nullptr;
    SLObjectItf playerObject = nullptr;
    SLPlayItf playerPlay = nullptr;
    SLAndroidSimpleBufferQueueItf bufferQueue = nullptr;
    bool outputReady = false;
    int callbackBuffer = 0;
    static constexpr int kFramesPerBuffer = 512;
    std::array<int16_t, kFramesPerBuffer * 2> buffers[2]{};

    Stage24252AudioBackend() { trackVolume.fill(1.0f); }
};

static Stage24252AudioBackend gStage24252Audio;

static uint16_t stage24252_u16le(const unsigned char* p) {
    return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}
static uint32_t stage24252_u32le(const unsigned char* p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static bool stage24252_read_asset(const std::string& assetPath, std::vector<unsigned char>& out) {
    out.clear();
    if (!gStage24AssetManager) return false;
    AAsset* a = AAssetManager_open(gStage24AssetManager, assetPath.c_str(), AASSET_MODE_STREAMING);
    if (!a) return false;
    const off_t len = AAsset_getLength(a);
    if (len > 0) out.reserve((size_t)len);
    unsigned char buf[32768];
    bool ok = true;
    for (;;) {
        const int n = AAsset_read(a, buf, sizeof(buf));
        if (n < 0) { ok = false; break; }
        if (n == 0) break;
        out.insert(out.end(), buf, buf + n);
    }
    AAsset_close(a);
    return ok;
}

static bool stage24252_parse_original_wav(const std::vector<unsigned char>& bytes,
                                          Stage24252AudioClip& clip,
                                          std::string& why) {
    if (bytes.size() < 44 || std::memcmp(bytes.data(), "RIFF", 4) != 0 ||
        std::memcmp(bytes.data() + 8, "WAVE", 4) != 0) {
        why = "not-RIFF-WAVE";
        return false;
    }
    uint16_t format = 0, channels = 0, bits = 0;
    uint32_t rate = 0;
    const unsigned char* data = nullptr;
    size_t dataBytes = 0;
    bool haveFmt = false;
    for (size_t pos = 12; pos + 8 <= bytes.size();) {
        const unsigned char* h = bytes.data() + pos;
        const uint32_t chunkSize = stage24252_u32le(h + 4);
        const size_t payload = pos + 8;
        if (payload + chunkSize > bytes.size()) break;
        if (std::memcmp(h, "fmt ", 4) == 0 && chunkSize >= 16) {
            format = stage24252_u16le(bytes.data() + payload + 0);
            channels = stage24252_u16le(bytes.data() + payload + 2);
            rate = stage24252_u32le(bytes.data() + payload + 4);
            bits = stage24252_u16le(bytes.data() + payload + 14);
            haveFmt = true;
        } else if (std::memcmp(h, "data", 4) == 0) {
            data = bytes.data() + payload;
            dataBytes = chunkSize;
        }
        pos = payload + chunkSize + (chunkSize & 1u);
    }
    if (!haveFmt || !data) { why = "missing-fmt-or-data"; return false; }
    if (format != 1 || (channels != 1 && channels != 2) || rate != 16000 || bits != 16) {
        char msg[128];
        std::snprintf(msg, sizeof(msg), "unsupported fmt=%u channels=%u rate=%u bits=%u",
                      (unsigned)format, (unsigned)channels, (unsigned)rate, (unsigned)bits);
        why = msg;
        return false;
    }
    if ((dataBytes % (channels * sizeof(int16_t))) != 0) {
        why = "unaligned-data";
        return false;
    }
    clip.channels = (int)channels;
    clip.sampleRate = (int)rate;
    clip.samples.resize(dataBytes / 2u);
    int peakAbs = 0;
    for (size_t i = 0; i < clip.samples.size(); ++i) {
        clip.samples[i] = (int16_t)stage24252_u16le(data + i * 2u);
        const int v = (int)clip.samples[i];
        const int a = v < 0 ? -v : v;
        if (a > peakAbs) peakAbs = a;
    }
    clip.peakAbs = peakAbs;
    clip.loaded = true;
    clip.supported = true;
    return true;
}


// Stage 24.25.7: MP3 decode backend.  The original 1.4.2 binary owns MP3
// semantics through mpg123, but Stage24.25.5/25.6 closed the observable
// AudioClip/AudioClipInstance contract: decoded signed PCM is consumed by the
// same mixer, EOF is a zero-byte fetch, loop=true rewinds the clip cursor to
// zero and continues filling the same mix request, and non-loop EOF marks the
// voice ended.  Android MediaExtractor/MediaCodec is used only as an ARM64
// compatibility decoder for the original MP3 payload; Lua aliases, groups,
// handles, track/master gain, loop ownership and voice lifetime stay in the
// recovered Rovio-facing bridge.
static bool stage24257_decode_original_mp3_asset(const std::string& assetPath,
                                                  Stage24252AudioClip& clip,
                                                  std::string& why) {
    if (!gStage24AssetManager) { why = "no-asset-manager"; return false; }

    AAsset* asset = AAssetManager_open(gStage24AssetManager, assetPath.c_str(), AASSET_MODE_RANDOM);
    if (!asset) { why = "asset-open"; return false; }

    off_t start = 0, length = 0;
    const int fd = AAsset_openFileDescriptor(asset, &start, &length);
    if (fd < 0 || length <= 0) {
        if (fd >= 0) close(fd);
        AAsset_close(asset);
        why = "asset-not-fd-backed";
        return false;
    }

    AMediaExtractor* extractor = AMediaExtractor_new();
    if (!extractor) {
        close(fd); AAsset_close(asset);
        why = "extractor-new";
        return false;
    }
    const media_status_t ds = AMediaExtractor_setDataSourceFd(
        extractor, fd, (off64_t)start, (off64_t)length);
    // NDK MediaExtractor duplicates/owns its data-source state after this call.
    close(fd);
    AAsset_close(asset);
    if (ds != AMEDIA_OK) {
        AMediaExtractor_delete(extractor);
        char msg[96]; std::snprintf(msg, sizeof(msg), "extractor-datasource:%d", (int)ds);
        why = msg;
        return false;
    }

    size_t audioTrack = (size_t)-1;
    AMediaFormat* trackFormat = nullptr;
    std::string mime;
    int32_t declaredRate = 0, declaredChannels = 0;
    const size_t trackCount = AMediaExtractor_getTrackCount(extractor);
    for (size_t i = 0; i < trackCount; ++i) {
        AMediaFormat* f = AMediaExtractor_getTrackFormat(extractor, i);
        if (!f) continue;
        const char* m = nullptr;
        if (AMediaFormat_getString(f, AMEDIAFORMAT_KEY_MIME, &m) && m &&
            std::strncmp(m, "audio/", 6) == 0) {
            audioTrack = i;
            trackFormat = f;
            mime = m;
            AMediaFormat_getInt32(f, AMEDIAFORMAT_KEY_SAMPLE_RATE, &declaredRate);
            AMediaFormat_getInt32(f, AMEDIAFORMAT_KEY_CHANNEL_COUNT, &declaredChannels);
            break;
        }
        AMediaFormat_delete(f);
    }
    if (!trackFormat || audioTrack == (size_t)-1) {
        AMediaExtractor_delete(extractor);
        why = "no-audio-track";
        return false;
    }
    if (mime != "audio/mpeg") {
        AMediaFormat_delete(trackFormat);
        AMediaExtractor_delete(extractor);
        why = "mime-not-audio-mpeg:" + mime;
        return false;
    }
    if (declaredRate != 16000 || (declaredChannels != 1 && declaredChannels != 2)) {
        char msg[128];
        std::snprintf(msg, sizeof(msg), "unexpected-input-format rate=%d channels=%d",
                      (int)declaredRate, (int)declaredChannels);
        AMediaFormat_delete(trackFormat);
        AMediaExtractor_delete(extractor);
        why = msg;
        return false;
    }

    AMediaCodec* codec = AMediaCodec_createDecoderByType(mime.c_str());
    if (!codec) {
        AMediaFormat_delete(trackFormat);
        AMediaExtractor_delete(extractor);
        why = "codec-create";
        return false;
    }
    const media_status_t cfg = AMediaCodec_configure(codec, trackFormat, nullptr, nullptr, 0);
    if (cfg != AMEDIA_OK) {
        AMediaCodec_delete(codec);
        AMediaFormat_delete(trackFormat);
        AMediaExtractor_delete(extractor);
        char msg[96]; std::snprintf(msg, sizeof(msg), "codec-configure:%d", (int)cfg);
        why = msg;
        return false;
    }
    if (AMediaExtractor_selectTrack(extractor, audioTrack) != AMEDIA_OK) {
        AMediaCodec_delete(codec);
        AMediaFormat_delete(trackFormat);
        AMediaExtractor_delete(extractor);
        why = "extractor-select-track";
        return false;
    }
    const media_status_t started = AMediaCodec_start(codec);
    if (started != AMEDIA_OK) {
        AMediaCodec_delete(codec);
        AMediaFormat_delete(trackFormat);
        AMediaExtractor_delete(extractor);
        char msg[96]; std::snprintf(msg, sizeof(msg), "codec-start:%d", (int)started);
        why = msg;
        return false;
    }

    std::vector<unsigned char> pcm;
    bool inputEos = false, outputEos = false;
    int32_t outputRate = declaredRate, outputChannels = declaredChannels;
    unsigned long long inputSamples = 0, outputBuffers = 0;
    int idleRounds = 0;
    int safety = 0;

    while (!outputEos && safety++ < 200000) {
        bool progressed = false;

        if (!inputEos) {
            const ssize_t inIndex = AMediaCodec_dequeueInputBuffer(codec, 10000);
            if (inIndex >= 0) {
                size_t cap = 0;
                uint8_t* in = AMediaCodec_getInputBuffer(codec, (size_t)inIndex, &cap);
                if (!in || cap == 0) {
                    why = "codec-input-buffer";
                    break;
                }
                const ssize_t sampleBytes = AMediaExtractor_readSampleData(extractor, in, cap);
                if (sampleBytes < 0) {
                    const media_status_t q = AMediaCodec_queueInputBuffer(
                        codec, (size_t)inIndex, 0, 0, 0, AMEDIACODEC_BUFFER_FLAG_END_OF_STREAM);
                    if (q != AMEDIA_OK) {
                        char msg[96]; std::snprintf(msg, sizeof(msg), "queue-input-eos:%d", (int)q);
                        why = msg;
                        break;
                    }
                    inputEos = true;
                } else {
                    const int64_t pts = AMediaExtractor_getSampleTime(extractor);
                    const media_status_t q = AMediaCodec_queueInputBuffer(
                        codec, (size_t)inIndex, 0, (size_t)sampleBytes,
                        pts >= 0 ? (uint64_t)pts : 0u, 0);
                    if (q != AMEDIA_OK) {
                        char msg[96]; std::snprintf(msg, sizeof(msg), "queue-input:%d", (int)q);
                        why = msg;
                        break;
                    }
                    ++inputSamples;
                    AMediaExtractor_advance(extractor);
                }
                progressed = true;
            }
        }

        for (int drain = 0; drain < 64 && !outputEos; ++drain) {
            AMediaCodecBufferInfo info{};
            const ssize_t outIndex = AMediaCodec_dequeueOutputBuffer(
                codec, &info, inputEos ? 10000 : 0);
            if (outIndex >= 0) {
                size_t reportedCap = 0;
                uint8_t* out = AMediaCodec_getOutputBuffer(codec, (size_t)outIndex, &reportedCap);
                (void)reportedCap; // pre-API35 NDK reports this unreliably; info.size is authoritative.
                if (info.size > 0) {
                    if (!out || info.offset < 0 || info.size < 0) {
                        why = "codec-output-buffer";
                        outputEos = true;
                        break;
                    }
                    const unsigned char* begin = out + (size_t)info.offset;
                    pcm.insert(pcm.end(), begin, begin + (size_t)info.size);
                }
                ++outputBuffers;
                const bool eos = (info.flags & AMEDIACODEC_BUFFER_FLAG_END_OF_STREAM) != 0;
                AMediaCodec_releaseOutputBuffer(codec, (size_t)outIndex, false);
                progressed = true;
                if (eos) outputEos = true;
                continue;
            }
            if (outIndex == AMEDIACODEC_INFO_OUTPUT_FORMAT_CHANGED) {
                AMediaFormat* outFmt = AMediaCodec_getOutputFormat(codec);
                if (outFmt) {
                    AMediaFormat_getInt32(outFmt, AMEDIAFORMAT_KEY_SAMPLE_RATE, &outputRate);
                    AMediaFormat_getInt32(outFmt, AMEDIAFORMAT_KEY_CHANNEL_COUNT, &outputChannels);
                    AMediaFormat_delete(outFmt);
                }
                progressed = true;
                continue;
            }
            if (outIndex == AMEDIACODEC_INFO_OUTPUT_BUFFERS_CHANGED) {
                progressed = true;
                continue;
            }
            break; // TRY_AGAIN_LATER or other negative informational result.
        }

        if (progressed) idleRounds = 0;
        else if (++idleRounds > 500) {
            why = "codec-timeout";
            break;
        }
    }

    AMediaCodec_stop(codec);
    AMediaCodec_delete(codec);
    AMediaFormat_delete(trackFormat);
    AMediaExtractor_delete(extractor);

    if (!why.empty()) return false;
    if (!outputEos) { why = "codec-no-eos"; return false; }
    if (outputRate != 16000 || (outputChannels != 1 && outputChannels != 2)) {
        char msg[128];
        std::snprintf(msg, sizeof(msg), "unexpected-output-format rate=%d channels=%d",
                      (int)outputRate, (int)outputChannels);
        why = msg;
        return false;
    }
    const size_t frameBytes = (size_t)outputChannels * sizeof(int16_t);
    if (pcm.empty() || (pcm.size() % frameBytes) != 0) {
        why = pcm.empty() ? "empty-pcm" : "unaligned-pcm";
        return false;
    }

    clip.channels = (int)outputChannels;
    clip.sampleRate = (int)outputRate;
    clip.samples.resize(pcm.size() / 2u);
    int peakAbs = 0;
    for (size_t i = 0; i < clip.samples.size(); ++i) {
        clip.samples[i] = (int16_t)stage24252_u16le(pcm.data() + i * 2u);
        const int v = (int)clip.samples[i];
        const int a = v < 0 ? -v : v;
        if (a > peakAbs) peakAbs = a;
    }
    clip.peakAbs = peakAbs;
    clip.loaded = true;
    clip.supported = true;
    clip.isMp3 = true;
    std::printf("[stage24.25.7-mp3-decode] PASS asset='%s' mime='%s' inRate=%d inChannels=%d outRate=%d outChannels=%d compressedSamples=%llu outputBuffers=%llu pcmFrames=%zu peak=%d\n",
                assetPath.c_str(), mime.c_str(), (int)declaredRate, (int)declaredChannels,
                (int)outputRate, (int)outputChannels, inputSamples, outputBuffers,
                clip.samples.size() / (size_t)clip.channels, clip.peakAbs);
    return true;
}

static float stage24252_track_volume_locked(int track) {
    if (track < 0 || track >= (int)gStage24252Audio.trackVolume.size()) return 1.0f;
    return gStage24252Audio.trackVolume[(size_t)track];
}

static void stage24252_mix_locked(int16_t* dst, int frames) {
    if (!dst || frames <= 0) return;
    if (!gStage24252Audio.outputEnabled) {
        std::memset(dst, 0, (size_t)frames * 2u * sizeof(int16_t));
        return;
    }
    for (int f = 0; f < frames; ++f) {
        float left = 0.0f, right = 0.0f;
        for (auto& v : gStage24252Audio.voices) {
            if (!v.active || !v.clip || !v.clip->supported || v.clip->channels <= 0) continue;
            const size_t totalFrames = v.clip->samples.size() / (size_t)v.clip->channels;
            if (totalFrames == 0) { v.active = false; continue; }
            if (v.frame >= totalFrames) {
                if (v.loop) {
                    v.frame = 0;
                    ++v.loopWraps;
                    ++gStage24252Audio.loopWraps;
                    if (v.loopWraps <= 4 || (v.loopWraps % 20ull) == 0ull) {
                        std::printf("[stage24.25.8-audio-lifecycle] LOOP_WRAP handle=%d alias='%s' kind=%s wrap=%llu totalFrames=%zu track=%d volume=%.9g\n",
                                    v.handle, v.alias.c_str(),
                                    (v.clip && v.clip->isMp3) ? "mp3" : "wav",
                                    v.loopWraps, totalFrames, v.track, v.volume);
                    }
                } else {
                    v.active = false;
                    ++gStage24252Audio.voiceEnds;
                    std::printf("[stage24.25.8-audio-lifecycle] END handle=%d alias='%s' kind=%s totalFrames=%zu track=%d volume=%.9g totalEnds=%llu\n",
                                v.handle, v.alias.c_str(),
                                (v.clip && v.clip->isMp3) ? "mp3" : "wav",
                                totalFrames, v.track, v.volume, gStage24252Audio.voiceEnds);
                    continue;
                }
            }
            const float gain = v.volume * stage24252_track_volume_locked(v.track) * gStage24252Audio.masterVolume;
            if (v.clip->channels == 1) {
                const float smp = (float)v.clip->samples[v.frame] * gain;
                left += smp; right += smp;
            } else {
                left += (float)v.clip->samples[v.frame * 2u + 0u] * gain;
                right += (float)v.clip->samples[v.frame * 2u + 1u] * gain;
            }
            ++v.frame;
        }
        const int li = (int)std::lround(left);
        const int ri = (int)std::lround(right);
        dst[f * 2 + 0] = (int16_t)std::max(-32768, std::min(32767, li));
        dst[f * 2 + 1] = (int16_t)std::max(-32768, std::min(32767, ri));
    }
}

static int stage24253_pcm_peak(const int16_t* p, size_t samples) {
    int peak = 0;
    if (!p) return 0;
    for (size_t i = 0; i < samples; ++i) {
        const int v = (int)p[i];
        const int a = v < 0 ? -v : v;
        if (a > peak) peak = a;
    }
    return peak;
}

static int stage24253_active_voices_locked() {
    int n = 0;
    for (const auto& v : gStage24252Audio.voices) if (v.active) ++n;
    return n;
}

static void stage24253_output_snapshot_locked(const char* reason, const Stage24252AudioClip* clip) {
    SLuint32 playState = 0;
    SLresult playResult = (SLresult)~0u;
    if (gStage24252Audio.playerPlay)
        playResult = (*gStage24252Audio.playerPlay)->GetPlayState(gStage24252Audio.playerPlay, &playState);

    SLAndroidSimpleBufferQueueState qs{};
    SLresult queueResult = (SLresult)~0u;
    if (gStage24252Audio.bufferQueue)
        queueResult = (*gStage24252Audio.bufferQueue)->GetState(gStage24252Audio.bufferQueue, &qs);

    std::printf("[stage24.25.3-audio-output] SNAP reason='%s' ready=%s enabled=%s playResult=%u playState=%u queueResult=%u queueCount=%u queueIndex=%u callbacks=%llu cbEnqueues=%llu cbNonZero=%llu cbSilent=%llu lastPeak=%d maxPeak=%d primePeak0=%d primePeak1=%d activeVoices=%d clipPeak=%d\n",
                reason ? reason : "",
                gStage24252Audio.outputReady ? "true" : "false",
                gStage24252Audio.outputEnabled ? "true" : "false",
                (unsigned)playResult, (unsigned)playState, (unsigned)queueResult,
                (unsigned)qs.count, (unsigned)qs.index,
                gStage24252Audio.callbackCalls, gStage24252Audio.callbackEnqueues,
                gStage24252Audio.callbackNonZeroBuffers, gStage24252Audio.callbackSilentBuffers,
                gStage24252Audio.lastCallbackPeak, gStage24252Audio.maxCallbackPeak,
                gStage24252Audio.primePeak0, gStage24252Audio.primePeak1,
                stage24253_active_voices_locked(), clip ? clip->peakAbs : -1);
}

static void stage24252_buffer_callback(SLAndroidSimpleBufferQueueItf bq, void*) {
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.callbackCalls;
    if (!gStage24252Audio.outputReady || !bq) {
        if (gStage24252Audio.callbackCalls <= 8)
            std::printf("[stage24.25.3-audio-output] CALLBACK_DROP call=%llu ready=%s bq=%s\n",
                        gStage24252Audio.callbackCalls,
                        gStage24252Audio.outputReady ? "true" : "false", bq ? "yes" : "no");
        return;
    }
    const int idx = gStage24252Audio.callbackBuffer & 1;
    ++gStage24252Audio.callbackBuffer;
    const int activeBefore = stage24253_active_voices_locked();
    stage24252_mix_locked(gStage24252Audio.buffers[idx].data(), Stage24252AudioBackend::kFramesPerBuffer);
    const int peak = stage24253_pcm_peak(gStage24252Audio.buffers[idx].data(), gStage24252Audio.buffers[idx].size());
    gStage24252Audio.lastCallbackPeak = peak;
    if (peak > gStage24252Audio.maxCallbackPeak) gStage24252Audio.maxCallbackPeak = peak;
    if (peak > 0) ++gStage24252Audio.callbackNonZeroBuffers;
    else ++gStage24252Audio.callbackSilentBuffers;

    SLAndroidSimpleBufferQueueState before{};
    const SLresult beforeResult = (*bq)->GetState(bq, &before);
    const SLresult r = (*bq)->Enqueue(
        bq, gStage24252Audio.buffers[idx].data(),
        (SLuint32)(gStage24252Audio.buffers[idx].size() * sizeof(int16_t)));
    if (r == SL_RESULT_SUCCESS) ++gStage24252Audio.callbackEnqueues;
    SLAndroidSimpleBufferQueueState after{};
    const SLresult afterResult = (*bq)->GetState(bq, &after);

    const bool diagnosticBurst = gStage24252Audio.callbackCalls <= 12 || peak > 0 || activeBefore > 0;
    if (diagnosticBurst && (gStage24252Audio.callbackCalls <= 120 || (gStage24252Audio.callbackCalls % 30u) == 0u)) {
        std::printf("[stage24.25.3-audio-output] CALLBACK call=%llu idx=%d activeBefore=%d peak=%d beforeResult=%u beforeCount=%u beforeIndex=%u enqueueResult=%u afterResult=%u afterCount=%u afterIndex=%u\n",
                    gStage24252Audio.callbackCalls, idx, activeBefore, peak,
                    (unsigned)beforeResult, (unsigned)before.count, (unsigned)before.index,
                    (unsigned)r, (unsigned)afterResult, (unsigned)after.count, (unsigned)after.index);
    }
    if (r != SL_RESULT_SUCCESS)
        S24E("[stage24.25.2-audio] OpenSL enqueue callback failed result=%u", (unsigned)r);
}

static bool stage24252_init_output_locked() {
    if (gStage24252Audio.outputReady) return true;
    SLresult r = slCreateEngine(&gStage24252Audio.engineObject, 0, nullptr, 0, nullptr, nullptr);
    if (r != SL_RESULT_SUCCESS || !gStage24252Audio.engineObject) return false;
    r = (*gStage24252Audio.engineObject)->Realize(gStage24252Audio.engineObject, SL_BOOLEAN_FALSE);
    if (r != SL_RESULT_SUCCESS) return false;
    r = (*gStage24252Audio.engineObject)->GetInterface(gStage24252Audio.engineObject,
                                                       SL_IID_ENGINE, &gStage24252Audio.engine);
    if (r != SL_RESULT_SUCCESS || !gStage24252Audio.engine) return false;
    r = (*gStage24252Audio.engine)->CreateOutputMix(gStage24252Audio.engine,
                                                    &gStage24252Audio.outputMixObject,
                                                    0, nullptr, nullptr);
    if (r != SL_RESULT_SUCCESS || !gStage24252Audio.outputMixObject) return false;
    r = (*gStage24252Audio.outputMixObject)->Realize(gStage24252Audio.outputMixObject, SL_BOOLEAN_FALSE);
    if (r != SL_RESULT_SUCCESS) return false;

    SLDataLocator_AndroidSimpleBufferQueue locBuf = {SL_DATALOCATOR_ANDROIDSIMPLEBUFFERQUEUE, 2};
    SLDataFormat_PCM fmt = {
        SL_DATAFORMAT_PCM, 2, SL_SAMPLINGRATE_16,
        SL_PCMSAMPLEFORMAT_FIXED_16, SL_PCMSAMPLEFORMAT_FIXED_16,
        SL_SPEAKER_FRONT_LEFT | SL_SPEAKER_FRONT_RIGHT,
        SL_BYTEORDER_LITTLEENDIAN
    };
    SLDataSource src = {&locBuf, &fmt};
    SLDataLocator_OutputMix locOut = {SL_DATALOCATOR_OUTPUTMIX, gStage24252Audio.outputMixObject};
    SLDataSink sink = {&locOut, nullptr};
    const SLInterfaceID ids[] = {SL_IID_ANDROIDSIMPLEBUFFERQUEUE};
    const SLboolean req[] = {SL_BOOLEAN_TRUE};
    r = (*gStage24252Audio.engine)->CreateAudioPlayer(gStage24252Audio.engine,
                                                      &gStage24252Audio.playerObject,
                                                      &src, &sink, 1, ids, req);
    if (r != SL_RESULT_SUCCESS || !gStage24252Audio.playerObject) return false;
    r = (*gStage24252Audio.playerObject)->Realize(gStage24252Audio.playerObject, SL_BOOLEAN_FALSE);
    if (r != SL_RESULT_SUCCESS) return false;
    r = (*gStage24252Audio.playerObject)->GetInterface(gStage24252Audio.playerObject,
                                                       SL_IID_PLAY, &gStage24252Audio.playerPlay);
    if (r != SL_RESULT_SUCCESS || !gStage24252Audio.playerPlay) return false;
    r = (*gStage24252Audio.playerObject)->GetInterface(gStage24252Audio.playerObject,
                                                       SL_IID_ANDROIDSIMPLEBUFFERQUEUE,
                                                       &gStage24252Audio.bufferQueue);
    if (r != SL_RESULT_SUCCESS || !gStage24252Audio.bufferQueue) return false;
    r = (*gStage24252Audio.bufferQueue)->RegisterCallback(gStage24252Audio.bufferQueue,
                                                          stage24252_buffer_callback, nullptr);
    if (r != SL_RESULT_SUCCESS) return false;

    gStage24252Audio.callbackBuffer = 0;
    stage24252_mix_locked(gStage24252Audio.buffers[0].data(), Stage24252AudioBackend::kFramesPerBuffer);
    stage24252_mix_locked(gStage24252Audio.buffers[1].data(), Stage24252AudioBackend::kFramesPerBuffer);
    gStage24252Audio.primePeak0 = stage24253_pcm_peak(gStage24252Audio.buffers[0].data(), gStage24252Audio.buffers[0].size());
    gStage24252Audio.primePeak1 = stage24253_pcm_peak(gStage24252Audio.buffers[1].data(), gStage24252Audio.buffers[1].size());
    std::printf("[stage24.25.3-audio-output] PRIME peak0=%d peak1=%d activeVoices=%d\n",
                gStage24252Audio.primePeak0, gStage24252Audio.primePeak1, stage24253_active_voices_locked());
    for (int i = 0; i < 2; ++i) {
        r = (*gStage24252Audio.bufferQueue)->Enqueue(
            gStage24252Audio.bufferQueue, gStage24252Audio.buffers[i].data(),
            (SLuint32)(gStage24252Audio.buffers[i].size() * sizeof(int16_t)));
        if (r != SL_RESULT_SUCCESS) return false;
    }
    // Mark ready before PLAYING so an implementation that dispatches the first
    // buffer callback immediately cannot consume one of the two primed buffers
    // and then return merely because outputReady was still false.  The callback
    // will block on this mutex until initialization returns.
    gStage24252Audio.outputReady = true;
    r = (*gStage24252Audio.playerPlay)->SetPlayState(gStage24252Audio.playerPlay, SL_PLAYSTATE_PLAYING);
    if (r != SL_RESULT_SUCCESS) {
        gStage24252Audio.outputReady = false;
        return false;
    }
    S24I("[stage24.25.2-audio] OpenSL PCM mixer ready rate=16000 channels=2 bits=16 buffers=2x%d",
         Stage24252AudioBackend::kFramesPerBuffer);
    std::printf("[stage24.25.2-audio-backend] PASS backend=OpenSL-software-mixer rate=16000 channels=2 bits=16 bufferFrames=%d\n",
                Stage24252AudioBackend::kFramesPerBuffer);
    stage24253_output_snapshot_locked("after-SetPlayState", nullptr);
    return true;
}

static int l_res_createAudio252(lua_State* L) {
    const char* pathRaw = lua_tostring(L, 1);
    const char* nameRaw = lua_tostring(L, 2);
    const std::string path = pathRaw ? pathRaw : "";
    const std::string name = nameRaw ? nameRaw : "";
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.createCalls;

    Stage24252AudioClip clip;
    clip.logicalPath = path;
    const bool isWav = path.size() >= 4 && path.substr(path.size() - 4) == ".wav";
    const bool isMp3 = path.size() >= 4 && path.substr(path.size() - 4) == ".mp3";

    if (isWav) {
        std::vector<unsigned char> bytes;
        const std::string assetPath = "stage24/" + (path.size() && path[0] == '/' ? path.substr(1) : path);
        std::string why;
        if (stage24252_read_asset(assetPath, bytes) && stage24252_parse_original_wav(bytes, clip, why)) {
            ++gStage24252Audio.wavCreates;
        } else {
            S24E("[stage24.25.2-audio] WAV registration failed alias=%s logical=%s asset=%s reason=%s",
                 name.c_str(), path.c_str(), assetPath.c_str(), why.empty() ? "asset-open" : why.c_str());
        }
    } else if (isMp3) {
        // Keep createAudio cheap and faithful to the original resource registry:
        // decoding is deferred until the untouched Lua first calls playAudio().
        clip.isMp3 = true;
        clip.supported = true;
        clip.loaded = false;
        clip.decodeAttempted = false;
        ++gStage24252Audio.mp3Creates;
        std::printf("[stage24.25.7-mp3-register] alias='%s' logical='%s' mode=lazy-decode\n",
                    name.c_str(), path.c_str());
    } else {
        ++gStage24252Audio.unsupportedCreates;
    }
    gStage24252Audio.clips[name] = std::move(clip);
    return 0;
}

static std::string stage24258_audio_group_summary(lua_State* L, const std::string& key) {
    const int top = lua_gettop(L);
    std::string out = "nil";
    lua_getglobal(L, "audioGroups");
    if (lua_istable(L, -1)) {
        lua_getfield(L, -1, key.c_str());
        if (lua_istable(L, -1)) {
            const size_t n = (size_t)lua_objlen(L, -1);
            out = "table[len=" + std::to_string(n) + "]{";
            const size_t limit = std::min<size_t>(n, 16u);
            for (size_t i = 1; i <= limit; ++i) {
                lua_rawgeti(L, -1, (int)i);
                const char* v = lua_tostring(L, -1);
                if (i > 1) out += ",";
                out += v ? v : "<nonstring>";
                lua_pop(L, 1);
            }
            if (n > limit) out += ",...";
            out += "}";
        } else if (!lua_isnil(L, -1)) {
            out = lua_typename(L, lua_type(L, -1));
        }
    }
    lua_settop(L, top);
    return out;
}

static void stage24258_dump_audio_groups(lua_State* L) {
    const int top = lua_gettop(L);
    lua_getglobal(L, "audioGroups");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.25.8-audio-groups] FAIL type=%s\n",
                    lua_typename(L, lua_type(L, -1)));
        lua_settop(L, top);
        return;
    }
    int groups = 0;
    lua_pushnil(L);
    while (lua_next(L, -2) != 0) {
        const char* key = lua_tostring(L, -2);
        if (key && lua_istable(L, -1)) {
            const size_t n = (size_t)lua_objlen(L, -1);
            std::string vals;
            const size_t limit = std::min<size_t>(n, 20u);
            for (size_t i = 1; i <= limit; ++i) {
                lua_rawgeti(L, -1, (int)i);
                const char* v = lua_tostring(L, -1);
                if (i > 1) vals += ",";
                vals += v ? v : "<nonstring>";
                lua_pop(L, 1);
            }
            if (n > limit) vals += ",...";
            std::printf("[stage24.25.8-audio-groups] key='%s' len=%zu values='%s'\n",
                        key, n, vals.c_str());
            ++groups;
        }
        lua_pop(L, 1);
    }
    std::printf("[stage24.25.8-audio-groups] PASS groups=%d ground_collision=%s\n",
                groups, stage24258_audio_group_summary(L, "ground_collision").c_str());
    lua_settop(L, top);
}

static int l_res_playAudio252(lua_State* L) {
    const int argc = lua_gettop(L);
    const char* nameRaw = lua_tostring(L, 1);
    const std::string name = nameRaw ? nameRaw : "";
    const float volume = (argc >= 2 && lua_isnumber(L, 2)) ? (float)lua_tonumber(L, 2) : 1.0f;
    const bool loop = (argc >= 3) ? (lua_toboolean(L, 3) != 0) : false;
    const int track = (argc >= 4 && lua_isnumber(L, 4)) ? (int)lua_tonumber(L, 4) : 0;

    std::unique_lock<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.playCalls;
    auto it = gStage24252Audio.clips.find(name);

    // Stage24.25.7: decode original MP3 payload lazily on first play.  Do not
    // hold the software-mixer mutex while MediaCodec works, otherwise a first
    // music cue could starve the OpenSL callback.  The Lua VM invokes this on
    // its single game thread, so a per-clip decodeAttempted flag is sufficient.
    if (it != gStage24252Audio.clips.end() && it->second.isMp3 &&
        !it->second.loaded && !it->second.decodeAttempted) {
        const std::string logicalPath = it->second.logicalPath;
        it->second.decodeAttempted = true;
        lock.unlock();

        Stage24252AudioClip decoded;
        decoded.logicalPath = logicalPath;
        decoded.isMp3 = true;
        decoded.decodeAttempted = true;
        const std::string assetPath = "stage24/" +
            (logicalPath.size() && logicalPath[0] == '/' ? logicalPath.substr(1) : logicalPath);
        std::string why;
        const bool ok = stage24257_decode_original_mp3_asset(assetPath, decoded, why);

        lock.lock();
        it = gStage24252Audio.clips.find(name);
        if (it != gStage24252Audio.clips.end()) {
            if (ok) {
                it->second = std::move(decoded);
                ++gStage24252Audio.mp3Decoded;
            } else {
                it->second.loaded = false;
                it->second.supported = false;
                it->second.isMp3 = true;
                it->second.decodeAttempted = true;
                ++gStage24252Audio.mp3DecodeFailures;
                std::printf("[stage24.25.7-mp3-decode] FAIL alias='%s' logical='%s' reason='%s'\n",
                            name.c_str(), logicalPath.c_str(), why.c_str());
            }
        }
    }

    if (it == gStage24252Audio.clips.end() || !it->second.supported || !it->second.loaded) {
        ++gStage24252Audio.missingPlays;
        if (gStage24252Audio.missingPlays <= 20 || (gStage24252Audio.missingPlays % 300u) == 0u) {
            const char* reason = "unregistered";
            if (it != gStage24252Audio.clips.end()) {
                if (it->second.isMp3 && it->second.decodeAttempted) reason = "mp3-decode-failed";
                else if (it->second.isMp3) reason = "mp3-not-decoded";
                else reason = "unsupported";
            }
            std::printf("[stage24.25.2-audio-play] MISS call=%llu miss=%llu name='%s' volume=%.9g loop=%s track=%d reason=%s\n",
                        gStage24252Audio.playCalls, gStage24252Audio.missingPlays, name.c_str(),
                        volume, loop ? "true" : "false", track, reason);
            if (name == "ground_collision") {
                std::printf("[stage24.25.8-ground-collision] MISS call=%llu callsite='%s' pc=%d clipRegistered=%s group=%s contract=Resources::playAudio-missing-returns--1\n",
                            gStage24252Audio.playCalls, proto_name(gLastLuaProto), gLastLuaPc,
                            (it != gStage24252Audio.clips.end()) ? "yes" : "no",
                            stage24258_audio_group_summary(L, name).c_str());
            }
        }
        lua_pushnumber(L, (lua_Number)-1.0f);
        return 1;
    }

    Stage24252AudioVoice* slot = nullptr;
    for (auto& v : gStage24252Audio.voices) if (!v.active) { slot = &v; break; }
    if (!slot) { gStage24252Audio.voices.emplace_back(); slot = &gStage24252Audio.voices.back(); }
    slot->active = true;
    slot->handle = gStage24252Audio.nextHandle++;
    slot->alias = name;
    slot->clip = &it->second;
    slot->frame = 0;
    slot->volume = volume;
    slot->loop = loop;
    slot->track = track;
    slot->loopWraps = 0;
    if (!stage24252_init_output_locked()) {
        slot->active = false;
        S24E("[stage24.25.2-audio] OpenSL output init failed on play name=%s", name.c_str());
        lua_pushnumber(L, (lua_Number)-1.0f);
        return 1;
    }
    ++gStage24252Audio.successfulPlays;
    std::printf("[stage24.25.2-audio-play] PLAY call=%llu handle=%d name='%s' volume=%.9g loop=%s track=%d kind=%s frames=%zu\n",
                gStage24252Audio.playCalls, slot->handle, name.c_str(), volume,
                loop ? "true" : "false", track, it->second.isMp3 ? "mp3" : "wav",
                it->second.samples.size() / (size_t)std::max(1, it->second.channels));
    if (it->second.isMp3) {
        std::printf("[stage24.25.7-mp3-play] PLAY handle=%d alias='%s' loop=%s track=%d volume=%.9g frames=%zu rate=%d channels=%d\n",
                    slot->handle, name.c_str(), loop ? "true" : "false", track, volume,
                    it->second.samples.size() / (size_t)std::max(1, it->second.channels),
                    it->second.sampleRate, it->second.channels);
    }
    stage24253_output_snapshot_locked(name.c_str(), &it->second);
    lua_pushnumber(L, (lua_Number)slot->handle);
    return 1;
}

static int l_res_stopAudio252(lua_State* L) {
    const char* nameRaw = lua_tostring(L, 1);
    const std::string name = nameRaw ? nameRaw : "";
    int stopped = 0;
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.stopByNameCalls;
    for (auto& v : gStage24252Audio.voices) {
        if (v.active && v.alias == name) { v.active = false; ++stopped; }
    }
    std::printf("[stage24.25.2-audio-play] STOP name='%s' instances=%d\n", name.c_str(), stopped);
    std::printf("[stage24.25.8-audio-lifecycle] STOP_NAME call=%llu name='%s' instances=%d callsite='%s' pc=%d\n",
                gStage24252Audio.stopByNameCalls, name.c_str(), stopped,
                proto_name(gLastLuaProto), gLastLuaPc);
    return 0;
}

static int l_res_stopAllAudio252(lua_State*) {
    int stopped = 0;
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.stopAllCalls;
    for (auto& v : gStage24252Audio.voices) if (v.active) { v.active = false; ++stopped; }
    std::printf("[stage24.25.2-audio-play] STOP_ALL instances=%d\n", stopped);
    std::printf("[stage24.25.8-audio-lifecycle] STOP_ALL call=%llu instances=%d callsite='%s' pc=%d\n",
                gStage24252Audio.stopAllCalls, stopped, proto_name(gLastLuaProto), gLastLuaPc);
    return 0;
}

static int l_res_isAudioPlaying252(lua_State* L) {
    bool playing = false;
    std::string subject = "<unsupported>";
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.queryCalls;
    if (lua_isnumber(L, 1)) {
        const int handle = (int)lua_tonumber(L, 1);
        subject = "handle=" + std::to_string(handle);
        for (const auto& v : gStage24252Audio.voices)
            if (v.active && v.handle == handle) { playing = true; break; }
    } else if (lua_isstring(L, 1)) {
        const std::string name = lua_tostring(L, 1) ? lua_tostring(L, 1) : "";
        subject = "name='" + name + "'";
        for (const auto& v : gStage24252Audio.voices)
            if (v.active && v.alias == name) { playing = true; break; }
    }
    if (gStage24252Audio.queryCalls <= 80 || (gStage24252Audio.queryCalls % 250ull) == 0ull) {
        std::printf("[stage24.25.8-audio-lifecycle] QUERY call=%llu %s result=%s callsite='%s' pc=%d\n",
                    gStage24252Audio.queryCalls, subject.c_str(), playing ? "true" : "false",
                    proto_name(gLastLuaProto), gLastLuaPc);
    }
    lua_pushboolean(L, playing ? 1 : 0);
    return 1;
}

static std::string stage24254_pause_page_name(lua_State* L);
static bool stage24254_settings_audio_enabled(lua_State* L, bool* known);
static unsigned long long gStage24254TrackGetCalls = 0;
static unsigned long long gStage24254TrackSetCalls = 0;

static int l_res_getTrackVolume252(lua_State* L) {
    const int track = lua_isnumber(L, 1) ? (int)lua_tonumber(L, 1) : 0;
    float value = 1.0f;
    {
        std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
        value = stage24252_track_volume_locked(track);
    }
    ++gStage24254TrackGetCalls;
    if (gStage24254TrackGetCalls <= 40 || (gStage24254TrackGetCalls % 120ull) == 0ull) {
        bool known=false; const bool enabled=stage24254_settings_audio_enabled(L,&known);
        std::printf("[stage24.25.4-track-volume] GET call=%llu track=%d returned=%.9g mode='%s' page='%s' audioEnabled=%s callsite='%s' pc=%d\n",
                    gStage24254TrackGetCalls, track, value,
                    stage24_global_lua_function_name(L,"currentGameMode").c_str(),
                    stage24254_pause_page_name(L).c_str(),
                    known?(enabled?"true":"false"):"unknown", proto_name(gLastLuaProto), gLastLuaPc);
    }
    lua_pushnumber(L, (lua_Number)value);
    return 1;
}

static int l_res_setTrackVolume252(lua_State* L) {
    // Proven LuaResources contract: setTrackVolume(volume, track).  Untouched
    // ARMv7 AudioMixer::setTrackVolume clamps the first argument to [0,1]
    // BEFORE storage.  Preserve the raw Lua request in telemetry, but store
    // exactly the native-clamped value so feedback through getTrackVolume() is
    // faithful while we audit whether the Lua animation intentionally overshoots.
    const float rawVolume = lua_isnumber(L, 1) ? (float)lua_tonumber(L, 1) : 1.0f;
    const int track = lua_isnumber(L, 2) ? (int)lua_tonumber(L, 2) : 0;
    const float nativeClamped = std::max(0.0f, std::min(1.0f, rawVolume));
    float previous = 1.0f;
    {
        std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
        previous = stage24252_track_volume_locked(track);
        if (track >= 0 && track < (int)gStage24252Audio.trackVolume.size())
            gStage24252Audio.trackVolume[(size_t)track] = nativeClamped;
    }
    ++gStage24254TrackSetCalls;
    bool known=false; const bool enabled=stage24254_settings_audio_enabled(L,&known);
    std::printf("[stage24.25.4-track-volume] SET call=%llu track=%d rawLua=%.9g nativeStored=%.9g previous=%.9g clamped=%s mode='%s' page='%s' audioEnabled=%s callsite='%s' pc=%d\n",
                gStage24254TrackSetCalls, track, rawVolume, nativeClamped, previous,
                (rawVolume==nativeClamped)?"no":"yes",
                stage24_global_lua_function_name(L,"currentGameMode").c_str(),
                stage24254_pause_page_name(L).c_str(),
                known?(enabled?"true":"false"):"unknown", proto_name(gLastLuaProto), gLastLuaPc);
    std::printf("[stage24.25.2-audio-volume] setTrackVolume volume=%.9g track=%d source=ARMv7-clamp raw=%.9g\n", nativeClamped, track, rawVolume);
    return 0;
}

static int l_res_getMasterVolume252(lua_State* L) {
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    lua_pushnumber(L, (lua_Number)gStage24252Audio.masterVolume);
    return 1;
}
static int l_res_setMasterVolume252(lua_State* L) {
    const float volume = lua_isnumber(L, 1) ? (float)lua_tonumber(L, 1) : 1.0f;
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    gStage24252Audio.masterVolume = volume;
    std::printf("[stage24.25.2-audio-volume] setMasterVolume volume=%.9g\n", volume);
    return 0;
}
static std::string stage24258_active_voice_snapshot_locked() {
    std::string out;
    int active = 0;
    int shown = 0;
    for (const auto& v : gStage24252Audio.voices) {
        if (!v.active) continue;
        ++active;
        if (shown < 6) {
            if (!out.empty()) out += ";";
            out += "h=" + std::to_string(v.handle) + ":" + v.alias +
                   "@" + std::to_string(v.frame) + (v.loop ? ":loop" : ":once");
            ++shown;
        }
    }
    if (active > shown) out += ";...";
    return "active=" + std::to_string(active) + " [" + out + "]";
}

static int l_res_startAudioOutput252(lua_State*) {
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.outputStartCalls;
    const std::string before = stage24258_active_voice_snapshot_locked();
    gStage24252Audio.outputEnabled = true;
    std::printf("[stage24.25.2-audio-volume] startAudioOutput enabled=true\n");
    std::printf("[stage24.25.8-output-lifecycle] START call=%llu %s currentBridgeCursorPolicy=resume-existing-voices\n",
                gStage24252Audio.outputStartCalls, before.c_str());
    return 0;
}
static int l_res_stopAudioOutput252(lua_State*) {
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    ++gStage24252Audio.outputStopCalls;
    const std::string before = stage24258_active_voice_snapshot_locked();
    gStage24252Audio.outputEnabled = false;
    std::printf("[stage24.25.2-audio-volume] stopAudioOutput enabled=false\n");
    std::printf("[stage24.25.8-output-lifecycle] STOP call=%llu %s currentBridgeCursorPolicy=frozen-while-output-disabled\n",
                gStage24252Audio.outputStopCalls, before.c_str());
    return 0;
}

static int l_stage24252_noop(lua_State*) { return 0; }

static bool stage24252_replay_original_audio_slice(lua_State* L) {
    // Execute the untouched createAssets closure in an isolated environment.
    // Only the already-replayed image/composprite/font prefix is neutralized.
    // loadImages() must also be skipped here: in the untouched createAssets() it
    // precedes the audio tail and otherwise re-enters res.createSpriteSheet().
    // The 184 createAudio calls and audioGroups table construction are therefore
    // generated by original 1.4.2 bytecode, not a hand-authored alias list.
    lua_getglobal(L, "createAssets");
    if (!lua_isfunction(L, -1) || lua_iscfunction(L, -1)) {
        lua_pop(L, 1);
        std::printf("[stage24.25.2-audio-register] FAIL reason=createAssets-unavailable\n");
        return false;
    }
    const int fnRef = luaL_ref(L, LUA_REGISTRYINDEX);

    lua_rawgeti(L, LUA_REGISTRYINDEX, fnRef);
    lua_getfenv(L, -1);
    const int oldEnvRef = luaL_ref(L, LUA_REGISTRYINDEX);
    lua_pop(L, 1);

    lua_newtable(L);
    const int env = lua_gettop(L);
    lua_pushvalue(L, env); lua_setfield(L, env, "_G");
    lua_pushstring(L, "data/audio"); lua_setfield(L, env, "audioPath");
    for (const char* n : {"loadImages", "loadCompoSprites", "loadFonts", "setFont"}) {
        lua_pushcfunction(L, l_stage24252_noop); lua_setfield(L, env, n);
    }
    lua_newtable(L);
    lua_pushcfunction(L, l_res_createAudio252); lua_setfield(L, -2, "createAudio");
    lua_pushcfunction(L, l_res_startAudioOutput252); lua_setfield(L, -2, "startAudioOutput");
    lua_pushcfunction(L, l_res_stopAudioOutput252); lua_setfield(L, -2, "stopAudioOutput");
    lua_setfield(L, env, "res");
    lua_newtable(L);
    lua_pushvalue(L, LUA_GLOBALSINDEX); lua_setfield(L, -2, "__index");
    lua_setmetatable(L, env);
    lua_pushvalue(L, env);
    const int envRef = luaL_ref(L, LUA_REGISTRYINDEX);
    lua_pop(L, 1);

    lua_rawgeti(L, LUA_REGISTRYINDEX, fnRef);
    lua_rawgeti(L, LUA_REGISTRYINDEX, envRef);
    lua_setfenv(L, -2);
    const int rc = lua_pcall(L, 0, 0, 0);
    std::string err;
    if (rc != 0) {
        const char* e = lua_tostring(L, -1);
        err = e ? e : "<no message>";
        lua_pop(L, 1);
    }

    // Always restore the original closure environment.
    lua_rawgeti(L, LUA_REGISTRYINDEX, fnRef);
    lua_rawgeti(L, LUA_REGISTRYINDEX, oldEnvRef);
    lua_setfenv(L, -2);
    lua_pop(L, 1);

    bool groupsOk = false;
    int groupCount = 0;
    if (rc == 0) {
        lua_rawgeti(L, LUA_REGISTRYINDEX, envRef);
        lua_getfield(L, -1, "audioGroups");
        if (lua_istable(L, -1)) {
            lua_pushnil(L);
            while (lua_next(L, -2) != 0) { ++groupCount; lua_pop(L, 1); }
            lua_pushvalue(L, -1);
            lua_setglobal(L, "audioGroups");
            groupsOk = true;
        }
        lua_pop(L, 1);
        lua_getfield(L, -1, "currentMainMenuSong");
        if (!lua_isnil(L, -1)) { lua_pushvalue(L, -1); lua_setglobal(L, "currentMainMenuSong"); }
        lua_pop(L, 2);
    }

    luaL_unref(L, LUA_REGISTRYINDEX, envRef);
    luaL_unref(L, LUA_REGISTRYINDEX, oldEnvRef);
    luaL_unref(L, LUA_REGISTRYINDEX, fnRef);

    std::printf("[stage24.25.2-audio-register] %s createCalls=%llu wavLoaded=%llu mp3Registered=%llu unsupported=%llu groups=%d audioPath='data/audio'\n",
                (rc == 0 && groupsOk) ? "PASS" : "FAIL",
                gStage24252Audio.createCalls, gStage24252Audio.wavCreates,
                gStage24252Audio.mp3Creates, gStage24252Audio.unsupportedCreates, groupCount);
    if (!err.empty()) std::printf("[stage24.25.2-audio-register] error-detail='%s'\n", err.c_str());
    if (rc == 0 && groupsOk) stage24258_dump_audio_groups(L);
    return rc == 0 && groupsOk && gStage24252Audio.wavCreates > 0;
}

static void stage24252_shutdown_audio_backend() {
    // Do not hold the mixer mutex while asking OpenSL to stop/destroy objects:
    // an implementation is allowed to have a buffer callback in flight, and
    // that callback acquires the same mutex. First publish outputReady=false,
    // detach the OpenSL interfaces, then destroy outside the lock.
    SLObjectItf playerObject = nullptr;
    SLPlayItf playerPlay = nullptr;
    SLAndroidSimpleBufferQueueItf bufferQueue = nullptr;
    SLObjectItf outputMixObject = nullptr;
    SLObjectItf engineObject = nullptr;
    {
        std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
        gStage24252Audio.outputReady = false;
        playerObject = gStage24252Audio.playerObject;
        playerPlay = gStage24252Audio.playerPlay;
        bufferQueue = gStage24252Audio.bufferQueue;
        outputMixObject = gStage24252Audio.outputMixObject;
        engineObject = gStage24252Audio.engineObject;
        gStage24252Audio.playerObject = nullptr;
        gStage24252Audio.playerPlay = nullptr;
        gStage24252Audio.bufferQueue = nullptr;
        gStage24252Audio.outputMixObject = nullptr;
        gStage24252Audio.engineObject = nullptr;
        gStage24252Audio.engine = nullptr;
    }

    if (playerPlay) (*playerPlay)->SetPlayState(playerPlay, SL_PLAYSTATE_STOPPED);
    if (bufferQueue) (*bufferQueue)->Clear(bufferQueue);
    if (playerObject) (*playerObject)->Destroy(playerObject);
    if (outputMixObject) (*outputMixObject)->Destroy(outputMixObject);
    if (engineObject) (*engineObject)->Destroy(engineObject);

    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    gStage24252Audio.callbackBuffer = 0;
    gStage24252Audio.voices.clear();
    gStage24252Audio.clips.clear();
    gStage24252Audio.trackVolume.fill(1.0f);
    gStage24252Audio.masterVolume = 1.0f;
    gStage24252Audio.outputEnabled = true;
    gStage24252Audio.nextHandle = 0;
    gStage24252Audio.createCalls = 0;
    gStage24252Audio.playCalls = 0;
    gStage24252Audio.successfulPlays = 0;
    gStage24252Audio.missingPlays = 0;
    gStage24252Audio.unsupportedCreates = 0;
    gStage24252Audio.wavCreates = 0;
    gStage24252Audio.mp3Creates = 0;
    gStage24252Audio.mp3Decoded = 0;
    gStage24252Audio.mp3DecodeFailures = 0;
    gStage24252Audio.voiceEnds = 0;
    gStage24252Audio.loopWraps = 0;
    gStage24252Audio.queryCalls = 0;
    gStage24252Audio.stopByNameCalls = 0;
    gStage24252Audio.stopAllCalls = 0;
    gStage24252Audio.outputStopCalls = 0;
    gStage24252Audio.outputStartCalls = 0;
}

static void stage24252_dump_audio_runtime_state(lua_State* L) {
    int groups = 0;
    lua_getglobal(L, "audioGroups");
    if (lua_istable(L, -1)) {
        lua_pushnil(L);
        while (lua_next(L, -2) != 0) { ++groups; lua_pop(L, 1); }
    }
    lua_pop(L, 1);
    std::lock_guard<std::mutex> lock(gStage24252Audio.mutex);
    std::printf("[stage24.25.2-audio-summary] clips=%zu wavLoaded=%llu mp3Registered=%llu mp3Decoded=%llu mp3DecodeFailures=%llu unsupported=%llu groups=%d plays=%llu success=%llu misses=%llu track0=%.3f track2=%.3f track7=%.3f master=%.3f\n",
                gStage24252Audio.clips.size(), gStage24252Audio.wavCreates,
                gStage24252Audio.mp3Creates, gStage24252Audio.mp3Decoded,
                gStage24252Audio.mp3DecodeFailures, gStage24252Audio.unsupportedCreates, groups,
                gStage24252Audio.playCalls, gStage24252Audio.successfulPlays,
                gStage24252Audio.missingPlays,
                stage24252_track_volume_locked(0), stage24252_track_volume_locked(2),
                stage24252_track_volume_locked(7), gStage24252Audio.masterVolume);
    std::printf("[stage24.25.8-audio-summary] loopWraps=%llu voiceEnds=%llu queryCalls=%llu stopByName=%llu stopAll=%llu outputStops=%llu outputStarts=%llu %s\n",
                gStage24252Audio.loopWraps, gStage24252Audio.voiceEnds,
                gStage24252Audio.queryCalls, gStage24252Audio.stopByNameCalls,
                gStage24252Audio.stopAllCalls, gStage24252Audio.outputStopCalls,
                gStage24252Audio.outputStartCalls,
                stage24258_active_voice_snapshot_locked().c_str());
}

static void set_bool_field(lua_State* L, const char* key, bool value) {
    lua_pushboolean(L, value ? 1 : 0);
    lua_setfield(L, -2, key);
}

static bool sync_physics_to_lua(lua_State* L) {
    lua_getglobal(L, "objects");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        return false;
    }

    lua_getfield(L, -1, "world");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 2);
        return false;
    }

    // Stage 24.2: recovered directly from ARMv7 GameLua::update(float).
    // The original does NOT treat every tiny non-zero Box2D resting velocity
    // as "moving".  It maintains two motion gates:
    //   hasMovingObjects: speed^2 > 9.0 OR angularVelocity > 0.1
    //   hasMovingObjectsZeroTolerance: speed^2 > 0 for ordinary objects
    // The old ARM64 shim used speed^2 > 0.0001, which kept resting birds
    // logically moving forever under the recovered gravity (0,20).
    bool hasMovingObjects = false;
    bool hasMovingObjectsZeroTolerance = false;

    for (const auto& kv : gPhysics->bodies) {
        b2Body* body = kv.second;
        lua_getfield(L, -1, kv.first.c_str());

        if (lua_istable(L, -1)) {
            const b2Vec2 p = body->GetPosition();
            const b2Vec2 v = body->GetLinearVelocity();
            const float av = body->GetAngularVelocity();
            float renderX=p.x, renderY=p.y, renderAngle=body->GetAngle();
            gPhysics->getRenderTransform(kv.first, &renderX, &renderY, &renderAngle);

            set_number_field(L, "x", renderX);
            set_number_field(L, "y", renderY);
            set_number_field(L, "xVel", v.x);
            set_number_field(L, "yVel", v.y);
            set_number_field(L, "angle", renderAngle);
            set_number_field(L, "angularVelocity", av);
            set_number_field(L, "mass", body->GetMass());
            set_bool_field(L, "sleeping", !body->IsAwake());

            // Stage 24.44.2: exact ARMv7 level-limit consumer reconstruction.
            // GameLua::update(float) writes Lua object.frozen=true whenever a
            // positive-mass physics object crosses either stored horizontal
            // level limit, or its synchronized Y exceeds the original hard
            // lower-world threshold 20.0f.  Critically, the original then
            // continues through the same-frame motion-gate calculation; the
            // untouched Lua updateGame() consumes `frozen` and owns removal.
            //
            // ARMv7 sequence:
            //   if bodyPositiveMass:
            //     if y > 20.0f: frozen=true
            //     if x < intLimitMinX: frozen=true
            //     if intLimitMaxX < x: frozen=true
            //
            // Use the synchronized render transform because ARMv7 compares the
            // same RenderObjectData x/y fields it has just published to Lua.
            if (body->GetType() == b2_dynamicBody &&
                body->GetMass() > 0.0f &&
                gStage24440LevelLimitsValid) {
                const bool frozenByY = renderY > 20.0f;
                const bool frozenByMinX =
                    renderX < (float)gStage24440LevelLimitMinX;
                const bool frozenByMaxX =
                    (float)gStage24440LevelLimitMaxX < renderX;
                if (frozenByY || frozenByMinX || frozenByMaxX) {
                    set_bool_field(L, "frozen", true);
                    static unsigned long long stage24442FrozenWrites = 0;
                    ++stage24442FrozenWrites;
                    if (stage24442FrozenWrites <= 64) {
                        std::printf(
                            "[stage24.44.2-bounds] FROZEN_WRITE call=%llu "
                            "body='%s' sync=(%.6f,%.6f) limits=(%d,%d) "
                            "reasonY=%s reasonMinX=%s reasonMaxX=%s "
                            "mass=%.6f action=ORIGINAL_ARMV7_CONTRACT\n",
                            stage24442FrozenWrites, kv.first.c_str(),
                            (double)renderX, (double)renderY,
                            gStage24440LevelLimitMinX,
                            gStage24440LevelLimitMaxX,
                            frozenByY ? "true" : "false",
                            frozenByMinX ? "true" : "false",
                            frozenByMaxX ? "true" : "false",
                            (double)body->GetMass());
                    }
                }
            }

            if (body->GetType() == b2_dynamicBody) {
                const float speed2 = v.x * v.x + v.y * v.y;
                // ARMv7 literals in GameLua::update(): 9.0f and 0.1f.
                // This is the real gameplay terminal/camera motion gate.
                if (speed2 > 9.0f || av > 0.1f)
                    hasMovingObjects = true;

                // ARMv7 also maintains a zero-tolerance variant.  The
                // original suppresses this for flag87 objects; mirror that
                // recovered branch when metadata is available.
                const RenderObjectMeta236C* meta = gPhysics->renderMeta(kv.first);
                if (speed2 > 0.0f && (!meta || !meta->flag87))
                    hasMovingObjectsZeroTolerance = true;
            }
        }

        lua_pop(L, 1);
    }

    lua_pop(L, 2); // world, objects

    lua_pushboolean(L, hasMovingObjects ? 1 : 0);
    lua_setglobal(L, "hasMovingObjects");
    lua_pushboolean(L, hasMovingObjectsZeroTolerance ? 1 : 0);
    lua_setglobal(L, "hasMovingObjectsZeroTolerance");
    return true;
}


static bool get_object_bool(lua_State* L, const std::string& name,
                            const char* field, bool fallback=false) {
    bool out = fallback;

    lua_getglobal(L, "objects");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        return out;
    }

    lua_getfield(L, -1, "world");
    if (!lua_istable(L, -1)) {
        lua_pop(L, 2);
        return out;
    }

    lua_getfield(L, -1, name.c_str());
    if (lua_istable(L, -1)) {
        lua_getfield(L, -1, field);
        if (lua_isboolean(L, -1))
            out = lua_toboolean(L, -1) != 0;
        lua_pop(L, 1);
    }

    lua_pop(L, 3);
    return out;
}

static bool table_has_key(lua_State* L,
                          const char* globalName,
                          const char* key) {
    lua_getglobal(L, globalName);
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        return false;
    }
    lua_getfield(L, -1, key);
    const bool present = !lua_isnil(L, -1);
    lua_pop(L, 2);
    return present;
}

static bool nested_table_has_key(lua_State* L,
                                 const char* globalName,
                                 const char* childName,
                                 const char* key) {
    lua_getglobal(L, globalName);
    if (!lua_istable(L, -1)) {
        lua_pop(L, 1);
        return false;
    }
    lua_getfield(L, -1, childName);
    if (!lua_istable(L, -1)) {
        lua_pop(L, 2);
        return false;
    }
    lua_getfield(L, -1, key);
    const bool present = !lua_isnil(L, -1);
    lua_pop(L, 3);
    return present;
}


static int get_global_bool(lua_State* L, const char* name, bool fallback=false) {
    lua_getglobal(L, name);
    const int value = lua_isboolean(L, -1) ? lua_toboolean(L, -1) : (fallback ? 1 : 0);
    lua_pop(L, 1);
    return value;
}

static void stage24133_publish_screen_dimensions(lua_State* L, bool menuProfile, const char* reason) {
    (void)menuProfile; // Stage 24.17.0: menu/game share one Context geometry.
    stage24133_resolve_menu_canvas_from_window();
    const int iw = stage24201_effective_logical_w(gStage24133WindowW);
    const int ih = stage24201_effective_logical_h(gStage24133WindowH);
    const float w = static_cast<float>(iw);
    const float h = static_cast<float>(ih);
    lua_pushnumber(L, w); lua_setglobal(L, "screenWidth");
    lua_pushnumber(L, h); lua_setglobal(L, "screenHeight");

    static int lastW = -1, lastH = -1;
    if (iw != lastW || ih != lastH) {
        if (gStage24201DebugDisplay) {
            S24I("Stage24.20.1 debug display Context -> %dx%d physical=%dx%d reason=%s",
                 iw, ih, gStage24133WindowW, gStage24133WindowH, reason ? reason : "<none>");
            std::printf("[stage24.20.1-debug-display] luaScreen=%dx%d physicalWindow=%dx%d reason=%s mode=WVGA_TEST source=debug-harness\n",
                        iw, ih, gStage24133WindowW, gStage24133WindowH, reason ? reason : "<none>");
        } else {
            S24I("Stage24.17.0 Context screen -> %dx%d reason=%s",
                 iw, ih, reason ? reason : "<none>");
            std::printf("[stage24.17.0-context-presentation] luaScreen=%dx%d reason=%s source=ANativeWindow/Context\n",
                        iw, ih, reason ? reason : "<none>");
        }
        lastW = iw; lastH = ih;
    }
}

static std::string get_global_string(lua_State* L, const char* name) {
    lua_getglobal(L, name);
    std::string out;
    if (lua_isstring(L, -1))
        out = lua_tostring(L, -1);
    lua_pop(L, 1);
    return out;
}

static std::string get_global_table_string_field(lua_State* L,
                                                 const char* globalName,
                                                 const char* fieldName) {
    std::string out;
    lua_getglobal(L, globalName);
    if (lua_istable(L, -1)) {
        lua_getfield(L, -1, fieldName);
        if (lua_isstring(L, -1))
            out = lua_tostring(L, -1);
        lua_pop(L, 1);
    }
    lua_pop(L, 1);
    return out;
}


// Forward declaration needed by Stage227ReplayWriter::capture().
// The actual helper implementation remains unchanged later in this file.
static double get_global_number(lua_State* L, const char* name);



// Stage 24.18.1: slingshot Lua ownership audit.
// Stage 24.18.0 recovered the exact sprite names and the native drawGame
// interleave, but deliberately deferred implementation because the Lua owner
// of the wood/rubber geometry was still unknown. Scan the untouched 1.4.2
// closure tree before native bindings replace globals, report every Proto that
// owns exact sling/rubber constants, and dump only bytecode windows that
// reference those constants. This is diagnostic-only.
static bool stage24181_is_sling_target(const char* s) {
    if (!s) return false;
    static const char* targets[] = {
        "SLING_HOLDER",
        "SLING_SHOT_01_FRONT",
        "SLING_SHOT_01_BACK",
        "rubberBandPos",
        "rubberBandAngle",
        "rubberBandLength",
        "oldRubberBandLength",
        "rubberBandSpeed",
        "shootRange",
        "shootMaxLength",
        "levelStartPosition",
        "slingshot_stretched",
        "animateBirdToSlingShot"
    };
    for (const char* t : targets) {
        if (std::strcmp(s, t) == 0) return true;
    }
    return false;
}

static bool stage24181_k_is_target(const Proto* p, int k) {
    if (!p || k < 0 || k >= p->sizek) return false;
    const TValue* v = &p->k[k];
    return ttisstring(v) && stage24181_is_sling_target(svalue(v));
}

static void stage24181_print_instruction(const Proto* p, int pc) {
    if (!p || !p->code || pc < 0 || pc >= p->sizecode) return;
    const Instruction ins = p->code[pc];
    const OpCode op = GET_OPCODE(ins);
    const int a = GETARG_A(ins), b = GETARG_B(ins), c = GETARG_C(ins);
    const int bx = GETARG_Bx(ins), sbx = GETARG_sBx(ins);
    std::printf("[stage24.18.1-sling-lua] pc=%04d op=%-10s A=%d B=%d C=%d Bx=%d sBx=%d",
                pc,
                (op >= 0 && op < NUM_OPCODES) ? luaP_opnames[op] : "<bad-op>",
                a, b, c, bx, sbx);
    switch (op) {
        case OP_LOADK:
        case OP_GETGLOBAL:
        case OP_SETGLOBAL:
            if (bx >= 0 && bx < p->sizek) {
                std::printf(" K[%d]=", bx);
                stage17_print_constant(&p->k[bx]);
            }
            break;
        case OP_GETTABLE:
        case OP_SELF:
            stage17_print_rk(p, c);
            break;
        case OP_SETTABLE:
            stage17_print_rk(p, b);
            stage17_print_rk(p, c);
            break;
        case OP_EQ:
        case OP_LT:
        case OP_LE:
        case OP_ADD:
        case OP_SUB:
        case OP_MUL:
        case OP_DIV:
        case OP_MOD:
        case OP_POW:
            stage17_print_rk(p, b);
            stage17_print_rk(p, c);
            break;
        default:
            break;
    }
    std::printf("\n");
}

static void stage24181_scan_proto(const Proto* p,
                                  const std::string& root,
                                  const std::string& path,
                                  std::set<const Proto*>& visited) {
    if (!p || !p->code || visited.count(p)) return;
    visited.insert(p);

    std::vector<int> targetK;
    for (int k = 0; k < p->sizek; ++k) {
        if (stage24181_k_is_target(p, k)) targetK.push_back(k);
    }

    if (!targetK.empty()) {
        std::printf("[stage24.18.1-sling-lua] BEGIN root='%s' path='%s' proto=%p sizecode=%d sizek=%d sizep=%d\n",
                    root.c_str(), path.c_str(), static_cast<const void*>(p),
                    p->sizecode, p->sizek, p->sizep);
        for (int k : targetK) {
            std::printf("[stage24.18.1-sling-lua] HIT K[%d]=", k);
            stage17_print_constant(&p->k[k]);
            std::printf("\n");
        }

        std::set<int> refs;
        auto maybe_rk = [&](int operand, int pc) {
            if (!ISK(operand)) return;
            const int k = INDEXK(operand);
            if (stage24181_k_is_target(p, k)) refs.insert(pc);
        };
        for (int pc = 0; pc < p->sizecode; ++pc) {
            const Instruction ins = p->code[pc];
            const OpCode op = GET_OPCODE(ins);
            const int b = GETARG_B(ins), c = GETARG_C(ins), bx = GETARG_Bx(ins);
            switch (op) {
                case OP_LOADK:
                case OP_GETGLOBAL:
                case OP_SETGLOBAL:
                    if (stage24181_k_is_target(p, bx)) refs.insert(pc);
                    break;
                case OP_GETTABLE:
                case OP_SELF:
                    maybe_rk(c, pc);
                    break;
                case OP_SETTABLE:
                    maybe_rk(b, pc); maybe_rk(c, pc);
                    break;
                case OP_EQ:
                case OP_LT:
                case OP_LE:
                case OP_ADD:
                case OP_SUB:
                case OP_MUL:
                case OP_DIV:
                case OP_MOD:
                case OP_POW:
                    maybe_rk(b, pc); maybe_rk(c, pc);
                    break;
                default:
                    break;
            }
        }

        std::vector<std::pair<int,int>> windows;
        for (int pc : refs) {
            int lo = std::max(0, pc - 56);
            int hi = std::min(p->sizecode - 1, pc + 56);
            if (!windows.empty() && lo <= windows.back().second + 1) {
                windows.back().second = std::max(windows.back().second, hi);
            } else {
                windows.push_back(std::make_pair(lo, hi));
            }
        }
        if (windows.empty()) {
            std::printf("[stage24.18.1-sling-lua] target constants present but no direct RK/Bx references decoded\n");
        } else {
            for (const auto& w : windows) {
                std::printf("[stage24.18.1-sling-lua] WINDOW %d..%d\n", w.first, w.second);
                for (int pc = w.first; pc <= w.second; ++pc)
                    stage24181_print_instruction(p, pc);
            }
        }
        std::printf("[stage24.18.1-sling-lua] END root='%s' path='%s'\n",
                    root.c_str(), path.c_str());
    }

    for (int i = 0; i < p->sizep; ++i) {
        if (!p->p || !p->p[i]) continue;
        stage24181_scan_proto(
            p->p[i], root,
            path + "/child" + std::to_string(i),
            visited);
    }
}

static void stage24181_dump_slingshot_lua_owners(lua_State* L) {
    if (!L) return;
    std::printf("[stage24.18.1-sling-lua] SCAN_BEGIN source=untouched-1.4.2-closures\n");
    std::set<const Proto*> visited;

    lua_pushvalue(L, LUA_GLOBALSINDEX);
    const int globals = lua_gettop(L);
    lua_pushnil(L);
    while (lua_next(L, globals) != 0) {
        if (lua_type(L, -2) == LUA_TSTRING &&
            lua_isfunction(L, -1) &&
            !lua_iscfunction(L, -1)) {
            const char* key = lua_tostring(L, -2);
            const Closure* cl =
                static_cast<const Closure*>(lua_topointer(L, -1));
            if (cl && cl->l.p) {
                const std::string root = key ? key : "<unnamed>";
                stage24181_scan_proto(cl->l.p, root, root, visited);
            }
        }
        lua_pop(L, 1);
    }
    lua_pop(L, 1);
    std::printf("[stage24.18.1-sling-lua] SCAN_END uniqueProtos=%zu\n",
                visited.size());
}

static void stage24181_dump_slingshot_assets(const SpriteDB& sprites) {
    static const char* names[] = {
        "SLING_HOLDER",
        "SLING_SHOT_01_FRONT",
        "SLING_SHOT_01_BACK"
    };
    std::printf("[stage24.18.1-sling-assets] BEGIN\n");
    for (const char* name : names) {
        const SpriteInfo* s = sprites.find(name);
        if (!s) {
            std::printf("[stage24.18.1-sling-assets] sprite='%s' MISSING\n", name);
            continue;
        }
        std::printf(
            "[stage24.18.1-sling-assets] sprite='%s' sheet='%s' texture='%s' "
            "rect=%d,%d %dx%d pivot=%d,%d\n",
            name, s->sheetName.c_str(), s->textureName.c_str(),
            s->x, s->y, s->width, s->height, s->pivotX, s->pivotY);
    }
    std::printf("[stage24.18.1-sling-assets] END\n");
}


// Stage 24.19.0: gameplay score HUD Lua ownership audit.
// The score simulation is already recovered and live, but the in-game visual
// score HUD is still absent.  Before drawing any digits, recursively scan the
// untouched 1.4.2 closure tree for Protos that own score-related constants and
// dump bytecode windows around those references.  This recovers the exact
// draw call, font, anchor, screen-relative position and visibility gates rather
// than scaling a guessed modern HUD.
static bool stage24190_is_score_string(const char* s) {
    if (!s) return false;
    std::string q(s);
    std::transform(q.begin(), q.end(), q.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
    });
    return q.find("score") != std::string::npos;
}

static bool stage24190_k_is_score(const Proto* p, int k) {
    if (!p || k < 0 || k >= p->sizek) return false;
    const TValue* v = &p->k[k];
    return ttisstring(v) && stage24190_is_score_string(svalue(v));
}

static void stage24190_print_instruction(const Proto* p, int pc) {
    if (!p || !p->code || pc < 0 || pc >= p->sizecode) return;
    const Instruction ins = p->code[pc];
    const OpCode op = GET_OPCODE(ins);
    const int a = GETARG_A(ins), b = GETARG_B(ins), c = GETARG_C(ins);
    const int bx = GETARG_Bx(ins), sbx = GETARG_sBx(ins);
    std::printf("[stage24.19.0-score-hud-lua] pc=%04d op=%-10s A=%d B=%d C=%d Bx=%d sBx=%d",
                pc,
                (op >= 0 && op < NUM_OPCODES) ? luaP_opnames[op] : "<bad-op>",
                a, b, c, bx, sbx);
    switch (op) {
        case OP_LOADK:
        case OP_GETGLOBAL:
        case OP_SETGLOBAL:
            if (bx >= 0 && bx < p->sizek) {
                std::printf(" K[%d]=", bx);
                stage17_print_constant(&p->k[bx]);
            }
            break;
        case OP_GETTABLE:
        case OP_SELF:
            stage17_print_rk(p, c);
            break;
        case OP_SETTABLE:
            stage17_print_rk(p, b);
            stage17_print_rk(p, c);
            break;
        case OP_EQ:
        case OP_LT:
        case OP_LE:
        case OP_ADD:
        case OP_SUB:
        case OP_MUL:
        case OP_DIV:
        case OP_MOD:
        case OP_POW:
            stage17_print_rk(p, b);
            stage17_print_rk(p, c);
            break;
        default:
            break;
    }
    std::printf("\n");
}

static void stage24190_scan_score_proto(const Proto* p,
                                        const std::string& root,
                                        const std::string& path,
                                        std::set<const Proto*>& visited) {
    if (!p || !p->code || visited.count(p)) return;
    visited.insert(p);

    std::vector<int> scoreK;
    for (int k = 0; k < p->sizek; ++k) {
        if (stage24190_k_is_score(p, k)) scoreK.push_back(k);
    }
    if (!scoreK.empty()) {
        std::printf("[stage24.19.0-score-hud-lua] BEGIN root='%s' path='%s' proto=%p sizecode=%d sizek=%d sizep=%d\n",
                    root.c_str(), path.c_str(), static_cast<const void*>(p),
                    p->sizecode, p->sizek, p->sizep);
        for (int k : scoreK) {
            std::printf("[stage24.19.0-score-hud-lua] HIT K[%d]=", k);
            stage17_print_constant(&p->k[k]);
            std::printf("\n");
        }

        std::set<int> refs;
        auto maybe_rk = [&](int operand, int pc) {
            if (ISK(operand) && stage24190_k_is_score(p, INDEXK(operand))) refs.insert(pc);
        };
        for (int pc = 0; pc < p->sizecode; ++pc) {
            const Instruction ins = p->code[pc];
            const OpCode op = GET_OPCODE(ins);
            const int b = GETARG_B(ins), c = GETARG_C(ins), bx = GETARG_Bx(ins);
            switch (op) {
                case OP_LOADK:
                case OP_GETGLOBAL:
                case OP_SETGLOBAL:
                    if (stage24190_k_is_score(p, bx)) refs.insert(pc);
                    break;
                case OP_GETTABLE:
                case OP_SELF:
                    maybe_rk(c, pc);
                    break;
                case OP_SETTABLE:
                    maybe_rk(b, pc); maybe_rk(c, pc);
                    break;
                case OP_EQ:
                case OP_LT:
                case OP_LE:
                case OP_ADD:
                case OP_SUB:
                case OP_MUL:
                case OP_DIV:
                case OP_MOD:
                case OP_POW:
                    maybe_rk(b, pc); maybe_rk(c, pc);
                    break;
                default:
                    break;
            }
        }

        std::vector<std::pair<int,int>> windows;
        for (int pc : refs) {
            const int lo = std::max(0, pc - 88);
            const int hi = std::min(p->sizecode - 1, pc + 88);
            if (!windows.empty() && lo <= windows.back().second + 1)
                windows.back().second = std::max(windows.back().second, hi);
            else
                windows.push_back(std::make_pair(lo, hi));
        }
        for (const auto& w : windows) {
            std::printf("[stage24.19.0-score-hud-lua] WINDOW %d..%d\n", w.first, w.second);
            for (int pc = w.first; pc <= w.second; ++pc)
                stage24190_print_instruction(p, pc);
        }
        std::printf("[stage24.19.0-score-hud-lua] END root='%s' path='%s'\n",
                    root.c_str(), path.c_str());
    }

    for (int i = 0; i < p->sizep; ++i) {
        if (!p->p || !p->p[i]) continue;
        stage24190_scan_score_proto(
            p->p[i], root, path + "/child" + std::to_string(i), visited);
    }
}

static void stage24190_dump_score_hud_lua_owners(lua_State* L) {
    if (!L) return;
    std::printf("[stage24.19.0-score-hud-lua] SCAN_BEGIN source=untouched-1.4.2-closures policy=diagnostic-only\n");
    std::set<const Proto*> visited;
    lua_pushvalue(L, LUA_GLOBALSINDEX);
    const int globals = lua_gettop(L);
    lua_pushnil(L);
    while (lua_next(L, globals) != 0) {
        if (lua_type(L, -2) == LUA_TSTRING && lua_isfunction(L, -1) && !lua_iscfunction(L, -1)) {
            const char* key = lua_tostring(L, -2);
            const Closure* cl = static_cast<const Closure*>(lua_topointer(L, -1));
            if (cl && cl->l.p) {
                const std::string root = key ? key : "<unnamed>";
                stage24190_scan_score_proto(cl->l.p, root, root, visited);
            }
        }
        lua_pop(L, 1);
    }
    lua_pop(L, 1);
    std::printf("[stage24.19.0-score-hud-lua] SCAN_END uniqueProtos=%zu\n", visited.size());
}

