// Stage 24.12.9: diagnostic-only audit of the live level-complete menu.
// The menu is still intentionally not drawn in Stage24, so random pointer
// probing can otherwise make an action look like a camera/gameplay change.
// Keep this read-only: inspect the original Lua tables/functions and correlate
// the exact touch that changes levelName/currentGameMode.
static std::string stage24129_field_summary(lua_State* L, int tableIndex,
                                             const char* field) {
    tableIndex = stage2411_abs_index(L, tableIndex);
    lua_getfield(L, tableIndex, field);
    std::string out;
    const int t = lua_type(L, -1);
    if (t == LUA_TSTRING) {
        out = lua_tostring(L, -1);
    } else if (t == LUA_TNUMBER) {
        char buf[64];
        std::snprintf(buf, sizeof(buf), "%.3f", (double)lua_tonumber(L, -1));
        out = buf;
    } else if (t == LUA_TBOOLEAN) {
        out = lua_toboolean(L, -1) ? "true" : "false";
    } else if (t == LUA_TFUNCTION) {
        if (lua_iscfunction(L, -1)) out = "<C-function>";
        else {
            const Closure* cl = clvalue(L->top - 1);
            out = std::string("<Lua:") + proto_name(cl->l.p) + ">";
        }
    } else if (t == LUA_TTABLE) {
        out = "<table>";
    } else if (t != LUA_TNIL) {
        out = lua_typename(L, t);
    }
    lua_pop(L, 1);
    return out;
}

static void stage24129_dump_level_complete_items(lua_State* L, const char* phase) {
    lua_getglobal(L, "levelComplete");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.12.9-menu-audit] %s levelComplete unavailable type=%s\n",
                    phase ? phase : "?", luaL_typename(L, -1));
        lua_pop(L, 1);
        return;
    }
    const int pageIdx = lua_gettop(L);
    lua_getfield(L, pageIdx, "items");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.12.9-menu-audit] %s levelComplete.items unavailable type=%s\n",
                    phase ? phase : "?", luaL_typename(L, -1));
        lua_pop(L, 2);
        return;
    }
    const int itemsIdx = lua_gettop(L);
    const int n = (int)lua_objlen(L, itemsIdx);
    std::printf("[stage24.12.9-menu-audit] %s levelComplete.items count=%d pageName='%s'\n",
                phase ? phase : "?", n,
                stage24129_field_summary(L, pageIdx, "name").c_str());

    static const char* fields[] = {
        "name", "type", "sprite", "action", "returnValue", "filename", "folder",
        "text", "id", "x", "y", "width", "height", "w", "h", "scale", "xs", "ys",
        "visible", "enabled", "level", "levelIndex", "pageLevelIndex", "themeIndex",
        "worldNumber", "pageIndex", "anchor", "hanchor", "vanchor", "onClick", "callback"
    };

    for (int i = 1; i <= n; ++i) {
        lua_rawgeti(L, itemsIdx, i);
        if (!lua_istable(L, -1)) {
            lua_pop(L, 1);
            continue;
        }
        const int itemIdx = lua_gettop(L);
        std::string line;
        for (const char* field : fields) {
            const std::string v = stage24129_field_summary(L, itemIdx, field);
            if (v.empty()) continue;
            if (!line.empty()) line += " ";
            line += field;
            line += "='";
            line += v;
            line += "'";
        }
        std::printf("[stage24.12.9-menu-audit] item[%d] %s\n", i, line.c_str());
        lua_pop(L, 1);
    }
    lua_pop(L, 2);
}

