static void stage24470_dump_golden_eggs_map(lua_State* L, const char* phase) {
    const int base = lua_gettop(L);
    const char* expectedSlots[20] = {"",
        "LevelGE_4","LevelGE_3","LevelGE_2","SOUNDBOARD1","LevelGE_14",
        "LevelGE_15","RADIO","LevelGE_1","LevelGE_5","LevelGE_6",
        "LevelGE_7","KEYBOARD","LevelGE_8","LevelGE_9","LevelGE_10",
        "LevelGE_11","SEQUENCER","LevelGE_12","LevelGE_13"};
    const char* expectedOrder[16] = {"",
        "LevelGE_4","LevelGE_3","LevelGE_2","LevelGE_1","LevelGE_5",
        "LevelGE_6","LevelGE_7","LevelGE_8","LevelGE_9","LevelGE_10",
        "LevelGE_11","LevelGE_12","LevelGE_13","LevelGE_14","LevelGE_15"};

    bool pageExact = true;
    int slots = 0, gameplay = 0, soundboards = 0;
    std::string slotSequence;

    lua_getglobal(L, "levelSelectionPagesGoldenEggs");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.47.0-golden] MAP_FAIL phase='%s' reason=levelSelectionPagesGoldenEggs_missing action=OBSERVE_ONLY\n",
                    phase ? phase : "?");
        lua_settop(L, base); return;
    }
    lua_rawgeti(L, -1, 1);
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.47.0-golden] MAP_FAIL phase='%s' reason=page1_missing action=OBSERVE_ONLY\n",
                    phase ? phase : "?");
        lua_settop(L, base); return;
    }
    lua_getfield(L, -1, "items");
    if (!lua_istable(L, -1)) {
        std::printf("[stage24.47.0-golden] MAP_FAIL phase='%s' reason=page1_items_missing action=OBSERVE_ONLY\n",
                    phase ? phase : "?");
        lua_settop(L, base); return;
    }
    const size_t n = lua_objlen(L, -1);
    for (size_t i=1; i<=n; ++i) {
        lua_rawgeti(L, -1, (int)i);
        if (lua_istable(L, -1)) {
            int levelIndex=0, pageLevelIndex=0;
            std::string filename, folder, soundboard, sprite;
            const bool hasLevel = stage2411_table_int_field(L, -1, "levelIndex", &levelIndex);
            const bool hasPage = stage2411_table_int_field(L, -1, "pageLevelIndex", &pageLevelIndex);
            const bool hasFile = stage2411_table_string_field(L, -1, "filename", &filename);
            const bool hasSoundboard = stage2411_table_string_field(L, -1, "soundboard", &soundboard);
            (void)stage2411_table_string_field(L, -1, "folder", &folder);
            (void)stage2411_table_string_field(L, -1, "sprite", &sprite);
            if (hasLevel && hasPage && pageLevelIndex >= 1 && pageLevelIndex <= 19) {
                const std::string owner = hasFile ? filename : (hasSoundboard ? soundboard : std::string());
                if (!slotSequence.empty()) slotSequence += ",";
                slotSequence += owner;
                ++slots;
                if (hasFile) {
                    ++gameplay;
                    if (folder != "levels/goldeneggs1/") pageExact = false;
                } else if (hasSoundboard) {
                    ++soundboards;
                } else {
                    pageExact = false;
                }
                if (owner != expectedSlots[pageLevelIndex] || levelIndex != pageLevelIndex) pageExact = false;
                std::printf(
                    "[stage24.47.0-golden] SLOT phase='%s' item=%zu levelIndex=%d pageLevelIndex=%d "
                    "owner='%s' kind='%s' filename='%s' soundboard='%s' folder='%s' sprite='%s' action=OBSERVE_ONLY\n",
                    phase ? phase : "?", i, levelIndex, pageLevelIndex, owner.c_str(),
                    hasFile ? "LEVEL" : (hasSoundboard ? "SOUNDBOARD" : "UNKNOWN"),
                    filename.c_str(), soundboard.c_str(), folder.c_str(), sprite.c_str());
            }
        }
        lua_pop(L, 1);
    }
    lua_settop(L, base);

    bool orderExact = true;
    std::string orderSequence;
    lua_getglobal(L, "levelOrder_goldenEggs");
    if (!lua_istable(L, -1)) {
        orderExact = false;
    } else {
        for (int i=1; i<=15; ++i) {
            lua_rawgeti(L, -1, i);
            std::string value;
            if (lua_isstring(L, -1)) value = lua_tostring(L, -1);
            lua_pop(L, 1);
            if (!orderSequence.empty()) orderSequence += ",";
            orderSequence += value;
            if (value != expectedOrder[i]) orderExact = false;
        }
    }
    lua_settop(L, base);

    std::printf(
        "[stage24.47.0-golden] MAP_SUMMARY phase='%s' slots=%d gameplay=%d soundboards=%d "
        "slotSequence='%s' order='%s' expectedGameplay=15 expectedSoundboards=4 "
        "pageExact=%s orderExact=%s verdict=%s action=OBSERVE_ONLY\n",
        phase ? phase : "?", slots, gameplay, soundboards, slotSequence.c_str(),
        orderSequence.c_str(), pageExact ? "yes" : "no", orderExact ? "yes" : "no",
        (pageExact && orderExact && slots == 19 && gameplay == 15 && soundboards == 4) ? "PASS" : "MISMATCH");
    lua_settop(L, base);
}

static std::string stage23_field_or_dash(const std::string& value) {
    return value.empty() ? std::string("-") : value;
}

static bool write_stage23_sprite_manifest(const char* path,
                                          lua_State* L,
                                          const PhysicsBridge& physics,
                                          const SpriteDB& sprites) {
    std::ofstream out(path, std::ios::out | std::ios::trunc);
    if (!out) {
        std::fprintf(stderr, "[stage23.0] manifest open FAIL: %s\n", path);
        return false;
    }

    out << "ANGRY_STAGE23_0_SPRITE_MANIFEST\t1\n";
    out << "# Metadata is decoded from the original KA3D SPRT chunks.\n";
    out << "# A one-texture sheet gives an exact sprite->texture association; multi-texture sheets are intentionally marked unresolved.\n";

    int ambiguousSheets = 0;
    int level1ObjectSheets = 0;
    int level1AmbiguousSheets = 0;
    for (const SpriteSheetInfo& sheet : sprites.sheets()) {
        if (sheet.textures.size() != 1)
            ++ambiguousSheets;
        const bool isLevel1ObjectSheet =
            sheet.sheetName == "INGAME_BLOCKS_1.dat" ||
            sheet.sheetName == "INGAME_BIRDS_1.dat";
        if (isLevel1ObjectSheet) {
            ++level1ObjectSheets;
            if (sheet.textures.size() != 1)
                ++level1AmbiguousSheets;
        }
        out << "SHEET\t" << sheet.sheetName
            << "\ttextures=" << sheet.textures.size()
            << "\tsprites=" << sheet.spriteCount;
        for (size_t i = 0; i < sheet.textures.size(); ++i)
            out << "\ttexture[" << i << "]=" << sheet.textures[i];
        out << "\n";
    }

    out << "OBJECT_HEADER\tname\tdefinition\tsprite\tsheet\ttexture\tx\ty\tw\th\tpivotX\tpivotY\tdamageSprite\ttextureOverride\n";

    int spriteObjects = 0;
    int mapped = 0;
    int missing = 0;
    int unresolvedTexture = 0;

    // PhysicsBridge::bodies is a std::map, so this is deterministic by object name.
    for (const auto& kv : physics.bodies) {
        const std::string& name = kv.first;
        const std::string definition = physics.objectString(name, "definition");
        const std::string sprite = physics.objectString(name, "sprite");
        const std::string damageSprite = physics.objectString(name, "damageSprite");
        const std::string textureOverride = physics.objectString(name, "texture");

        if (sprite.empty()) {
            out << "OBJECT_NO_SPRITE\t" << name
                << "\tdefinition=" << stage23_field_or_dash(definition)
                << "\n";
            continue;
        }

        ++spriteObjects;
        const SpriteInfo* info = sprites.find(sprite.c_str());
        if (!info) {
            ++missing;
            out << "OBJECT_MISSING\t" << name
                << "\t" << stage23_field_or_dash(definition)
                << "\t" << sprite << "\n";
            continue;
        }

        ++mapped;
        if (info->textureName.empty())
            ++unresolvedTexture;

        out << "OBJECT\t" << name
            << "\t" << stage23_field_or_dash(definition)
            << "\t" << sprite
            << "\t" << info->sheetName
            << "\t" << stage23_field_or_dash(info->textureName)
            << "\t" << info->x
            << "\t" << info->y
            << "\t" << info->width
            << "\t" << info->height
            << "\t" << info->pivotX
            << "\t" << info->pivotY
            << "\t" << stage23_field_or_dash(damageSprite)
            << "\t" << stage23_field_or_dash(textureOverride)
            << "\n";
    }

    out << "BINDING_HEADER\tname\tstage23_0_status\n";
    out << "BINDING\tdrawRect\tstub\n";
    out << "BINDING\tdrawTexturedRect\tstub\n";
    out << "BINDING\tsetRenderState\tstub\n";
    out << "BINDING\tdrawGameNative\tstub\n";
    out << "BINDING\tdrawBackgroundNative\tstub\n";
    out << "BINDING\tdrawParticlesNative\tstub\n";
    out << "BINDING\tsetSprite\trecovered_RenderObjectData_sprite_pointer_by_name\n";
    out << "BINDING\tsetTexture\tmetadata_only\n";
    out << "BINDING\tdrawLine2D\tstub\n";
    out << "BINDING\tdrawForegroundNative\tstub\n";
    out << "BINDING\tdrawSome\tstub\n";
    out << "BINDING\tsetBGColor\theadless_noop\n";
    out << "BINDING\tsetWorldScale\theadless_noop\n";
    out << "BINDING\tres.drawString\theadless_noop\n";

    out << "SUMMARY\tsheets=" << sprites.sheets().size()
        << "\tambiguousSheets=" << ambiguousSheets
        << "\tbodyCount=" << physics.bodies.size()
        << "\tspriteObjects=" << spriteObjects
        << "\tmapped=" << mapped
        << "\tmissing=" << missing
        << "\tunresolvedTexture=" << unresolvedTexture
        << "\n";
    out.close();

    std::printf(
        "[stage23.0-manifest] sheets=%zu ambiguousSheets=%d bodies=%zu "
        "spriteObjects=%d mapped=%d missing=%d unresolvedTexture=%d\n",
        sprites.sheets().size(), ambiguousSheets, physics.bodies.size(),
        spriteObjects, mapped, missing, unresolvedTexture);

    // Stage 24.7: SpriteDB intentionally contains menu metadata too.
    // Keep the old Stage23.0 proof scoped to the two Level1 object sheets.
    if (level1ObjectSheets != 2) {
        std::fprintf(stderr, "[stage23.0] expected exactly two Level1 object sheets\n");
        return false;
    }
    if (level1AmbiguousSheets != 0) {
        std::fprintf(stderr, "[stage23.0] Level1 object-sheet texture association is ambiguous; do not guess atlas mapping\n");
        return false;
    }
    if (missing != 0 || unresolvedTexture != 0) {
        std::fprintf(stderr, "[stage23.0] one or more Level1 object sprites lack an exact sheet/texture mapping\n");
        return false;
    }
    if (spriteObjects < 20 || mapped != spriteObjects) {
        std::fprintf(stderr, "[stage23.0] Level1 sprite-object coverage unexpectedly low\n");
        return false;
    }

    std::printf("[angry-stage23.0] EXACT LEVEL1 SPRITE -> SHEET/TEXTURE/RECT/PIVOT MANIFEST PASS\n");
    return true;
}


// -----------------------------------------------------------------------------
// Stage 23.5: real ARM64 GLES1 multi-sprite scene audit.
//
// Fidelity contract recovered from the original ARMv7 renderer in Stage 23.4:
//   * fixed-function GLES1 / client arrays
//   * GL_LINEAR texture filtering for non-mipped 2D textures
//   * GL_CLAMP_TO_EDGE on S/T
//   * texture storage allocation followed by glTexSubImage2D upload
//   * glPixelStorei(GL_UNPACK_ALIGNMENT, 1) on the upload/blt path
//   * standard alpha templates use GL_SRC_ALPHA / GL_ONE_MINUS_SRC_ALPHA
//   * matrices are submitted with glMatrixMode + glLoadMatrixf (not shaders)
//
// This stage intentionally does NOT claim final camera or original draw order.
// It renders three deterministic gameplay snapshots using the Stage 23.2 audit
// view so GPU state, sprite rects, pivots, rotations and dynamic damage sprites
// can be validated before Android-window/lifecycle integration.
// -----------------------------------------------------------------------------

struct Stage235PvrAtlas {
    std::string name;
    std::vector<uint8_t> bytes;
    // Stage 24.31.4c: keep the logical image size separate from the physical
    // EGL_Texture backing. The original EGL_Image constructor rounds each
    // dimension up to the next power of two before createTexture(), while
    // retaining the logical image width/height on EGL_Image itself.
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t backingWidth = 0;
    uint32_t backingHeight = 0;
    uint32_t headerLength = 0;
    uint32_t dataLength = 0;
    uint32_t mipAdditional = 0;
    uint32_t mipLevels = 1;
    bool rgba8 = false;
    bool etc1 = false;
    bool rgb565 = false;
    GLuint texture = 0;
};

static uint32_t stage235_le32(const uint8_t* p) {
    return static_cast<uint32_t>(p[0]) |
           (static_cast<uint32_t>(p[1]) << 8u) |
           (static_cast<uint32_t>(p[2]) << 16u) |
           (static_cast<uint32_t>(p[3]) << 24u);
}

static uint32_t stage24314c_next_pow2(uint32_t v) {
    // Exact bit-spread shape recovered from gr::EGL_Image::EGL_Image():
    // (v-1) | >>1 | >>2 | >>4 | >>8 | >>16, then +1.
    if (v <= 1u) return 1u;
    uint32_t x = v - 1u;
    x |= x >> 1u;
    x |= x >> 2u;
    x |= x >> 4u;
    x |= x >> 8u;
    x |= x >> 16u;
    return x + 1u;
}

static uint32_t stage24314c_max_mip_additional(uint32_t w, uint32_t h) {
    uint32_t m = std::max(w, h);
    uint32_t n = 0u;
    while (m > 1u) {
        m >>= 1u;
        ++n;
    }
    return n;
}

static bool stage235_read_file(const char* path, std::vector<uint8_t>* out) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return false;
    f.seekg(0, std::ios::end);
    const std::streamoff n = f.tellg();
    if (n < 0) return false;
    f.seekg(0, std::ios::beg);
    out->resize(static_cast<size_t>(n));
    if (n > 0) f.read(reinterpret_cast<char*>(out->data()), n);
    return f.good() || f.eof();
}

#ifndef GL_ETC1_RGB8_OES
#define GL_ETC1_RGB8_OES 0x8D64
#endif

static uint64_t stage24144_etc1_level_bytes(uint32_t width, uint32_t height) {
    // ETC1 is 4x4 texels per 64-bit block. The final 2x2 and 1x1 mip
    // levels still occupy one complete 8-byte block.
    const uint32_t blocksWide = (std::max(4u, width) + 3u) / 4u;
    const uint32_t blocksHigh = (std::max(4u, height) + 3u) / 4u;
    return static_cast<uint64_t>(blocksWide) * blocksHigh * 8ull;
}

static bool stage235_parse_rgba4444_pvr(const char* path,
                                         const char* logicalName,
                                         Stage235PvrAtlas* atlas) {
    atlas->name = logicalName;
    if (!stage235_read_file(path, &atlas->bytes)) {
        std::fprintf(stderr, "[stage23.6C-pvr] read FAIL: %s\n", path);
        return false;
    }
    if (atlas->bytes.size() < 52) {
        std::fprintf(stderr, "[stage23.6C-pvr] short PVR: %s\n", path);
        return false;
    }
    const uint8_t* p = atlas->bytes.data();
    const uint32_t header = stage235_le32(p + 0);
    const uint32_t height = stage235_le32(p + 4);
    const uint32_t width = stage235_le32(p + 8);
    const uint32_t mipField = stage235_le32(p + 12);
    const uint32_t flags = stage235_le32(p + 16);
    const uint32_t dataLength = stage235_le32(p + 20);
    const uint32_t bitCount = stage235_le32(p + 24);
    const uint32_t rMask = stage235_le32(p + 28);
    const uint32_t gMask = stage235_le32(p + 32);
    const uint32_t bMask = stage235_le32(p + 36);
    const uint32_t aMask = stage235_le32(p + 40);
    const uint32_t tag = stage235_le32(p + 44);
    const uint32_t surfaces = stage235_le32(p + 48);
    // Stage 24.14.4 / 24.29.1: classify only PVR v2 contracts proven by the
    // user's exact original corpus. Gameplay atlases use raw RGBA4444 (type
    // 0x10); INGAME_THEME_GROUND_1 uses ETC1 (type 0x36); the startup splash
    // sheets (and two long-observed menu/background atlases) use raw RGB565
    // (type 0x13). Validate masks, payload length and surface count exactly;
    // never infer a pixel format from bpp alone.
    uint64_t expectedRgba4444Payload = 0;
    uint64_t expectedEtc1Payload = 0;
    uint32_t mw = width;
    uint32_t mh = height;
    bool mipDimensionsValid = width > 0u && height > 0u && mipField <= 31u;
    if (mipDimensionsValid) {
        for (uint32_t level = 0; level <= mipField; ++level) {
            expectedRgba4444Payload += static_cast<uint64_t>(mw) * mh * 2ull;
            expectedEtc1Payload += stage24144_etc1_level_bytes(mw, mh);
            if (level != mipField) {
                if (mw == 1u && mh == 1u) {
                    mipDimensionsValid = false;
                    break;
                }
                mw = std::max(1u, mw >> 1u);
                mh = std::max(1u, mh >> 1u);
            }
        }
    }

    const uint32_t pixelType = flags & 0xffu;
    const bool exactRgba4444 =
        header == 52u && tag == 0x21525650u &&
        pixelType == 0x10u && bitCount == 16u && surfaces == 1u &&
        rMask == 0x0000f000u && gMask == 0x00000f00u &&
        bMask == 0x000000f0u && aMask == 0x0000000fu &&
        mipDimensionsValid && expectedRgba4444Payload == dataLength &&
        atlas->bytes.size() == static_cast<uint64_t>(header) + dataLength;

    const bool exactEtc1 =
        header == 52u && tag == 0x21525650u &&
        pixelType == 0x36u && bitCount == 4u && surfaces == 1u &&
        rMask == 0xffffffffu && gMask == 0xffffffffu &&
        bMask == 0xffffffffu && aMask == 0x00000000u &&
        mipDimensionsValid && expectedEtc1Payload == dataLength &&
        atlas->bytes.size() == static_cast<uint64_t>(header) + dataLength;

    const bool exactRgb565 =
        header == 52u && tag == 0x21525650u &&
        pixelType == 0x13u && bitCount == 16u && surfaces == 1u &&
        rMask == 0x0000f800u && gMask == 0x000007e0u &&
        bMask == 0x0000001fu && aMask == 0x00000000u &&
        mipDimensionsValid && expectedRgba4444Payload == dataLength &&
        atlas->bytes.size() == static_cast<uint64_t>(header) + dataLength;

    if (!exactRgba4444 && !exactEtc1 && !exactRgb565) {
        std::fprintf(stderr,
            "[stage24.14.4-pvr] unsupported PVR v2 logical=%s bytes=%zu "
            "header=%u size=%ux%u mipAdditional=%u flags=0x%08x type=0x%02x data=%u bpp=%u "
            "masks=%08x/%08x/%08x/%08x tag=0x%08x surfaces=%u expected4444=%llu expectedETC1=%llu\n",
            logicalName, atlas->bytes.size(), header, width, height, mipField, flags, pixelType,
            dataLength, bitCount, rMask, gMask, bMask, aMask, tag, surfaces,
            static_cast<unsigned long long>(expectedRgba4444Payload),
            static_cast<unsigned long long>(expectedEtc1Payload));
        return false;
    }
    atlas->etc1 = exactEtc1;
    atlas->rgb565 = exactRgb565;
    atlas->headerLength = header;
    atlas->width = width;
    atlas->height = height;
    atlas->backingWidth = stage24314c_next_pow2(width);
    atlas->backingHeight = stage24314c_next_pow2(height);
    atlas->dataLength = dataLength;
    atlas->mipAdditional = mipField;
    atlas->mipLevels = mipField + 1u;
    std::printf(
        "[stage24.31.4c-texture] %s logical=%ux%u backing=%ux%u payload=%u format=%s mipAdditional=%u levels=%u exact=yes\n",
        logicalName, width, height, atlas->backingWidth, atlas->backingHeight, dataLength,
        atlas->etc1 ? "ETC1-v2" : (atlas->rgb565 ? "RGB565-v2" : "RGBA4444-v2"),
        mipField, atlas->mipLevels);
    return true;
}

static bool stage24132_parse_rgba8(const char* path,
                                      const char* logicalName,
                                      Stage235PvrAtlas* atlas) {
    atlas->name = logicalName ? logicalName : "";
    atlas->rgba8 = true;
    if (!stage235_read_file(path, &atlas->bytes)) {
        std::fprintf(stderr, "[stage24.13.2-tex] RGBA8 read FAIL: %s\n", path);
        return false;
    }
    if (atlas->bytes.size() < 12 ||
        !(atlas->bytes[0] == 'A' && atlas->bytes[1] == 'B' &&
          atlas->bytes[2] == 'R' && atlas->bytes[3] == '8')) {
        std::fprintf(stderr, "[stage24.13.2-tex] bad ABR8 header: %s\n", path);
        return false;
    }
    atlas->width = stage235_le32(atlas->bytes.data() + 4);
    atlas->height = stage235_le32(atlas->bytes.data() + 8);
    atlas->backingWidth = stage24314c_next_pow2(atlas->width);
    atlas->backingHeight = stage24314c_next_pow2(atlas->height);
    atlas->headerLength = 12;
    atlas->dataLength = static_cast<uint32_t>(atlas->bytes.size() - 12u);
    atlas->mipAdditional = 0;
    atlas->mipLevels = 1;
    const uint64_t expected = static_cast<uint64_t>(atlas->width) * atlas->height * 4ull;
    if (atlas->width == 0 || atlas->height == 0 ||
        atlas->bytes.size() != atlas->headerLength + expected) {
        std::fprintf(stderr, "[stage24.13.2-tex] invalid ABR8 payload: %s size=%zu expected=%llu\n",
                     path, atlas->bytes.size(), (unsigned long long)(atlas->headerLength + expected));
        return false;
    }
    std::printf("[stage24.31.4c-texture] %s logical=%ux%u backing=%ux%u RGBA8 exact-pixels=yes\n",
                atlas->name.c_str(), atlas->width, atlas->height,
                atlas->backingWidth, atlas->backingHeight);
    return true;
}

static std::string stage235_gl_error(GLenum e) {
    char buf[32];
    std::snprintf(buf, sizeof(buf), "0x%04x", (unsigned)e);
    return std::string(buf);
}

static std::string stage235_egl_error() {
    char buf[32];
    std::snprintf(buf, sizeof(buf), "0x%04x", (unsigned)eglGetError());
    return std::string(buf);
}

static const char* stage235_gl_string(GLenum e) {
    const GLubyte* s = glGetString(e);
    return s ? reinterpret_cast<const char*>(s) : "";
}

static bool stage235_write_bmp24(const std::string& path,
                                  const std::vector<uint8_t>& rgbaTopDown,
                                  int width,
                                  int height) {
    const uint32_t rowStride = static_cast<uint32_t>((width * 3 + 3) & ~3);
    const uint32_t pixelBytes = rowStride * static_cast<uint32_t>(height);
    const uint32_t fileBytes = 54u + pixelBytes;
    std::ofstream f(path, std::ios::binary);
    if (!f) return false;
    auto put16 = [&](uint16_t v) {
        char b[2] = {static_cast<char>(v & 255u), static_cast<char>((v >> 8u) & 255u)};
        f.write(b, 2);
    };
    auto put32 = [&](uint32_t v) {
        char b[4] = {
            static_cast<char>(v & 255u), static_cast<char>((v >> 8u) & 255u),
            static_cast<char>((v >> 16u) & 255u), static_cast<char>((v >> 24u) & 255u)};
        f.write(b, 4);
    };
    f.put('B'); f.put('M'); put32(fileBytes); put16(0); put16(0); put32(54);
    put32(40); put32(static_cast<uint32_t>(width)); put32(static_cast<uint32_t>(height));
    put16(1); put16(24); put32(0); put32(pixelBytes); put32(2835); put32(2835);
    put32(0); put32(0);
    std::vector<uint8_t> row(rowStride, 0);
    for (int yBottom = 0; yBottom < height; ++yBottom) {
        const int yTop = height - 1 - yBottom;
        std::fill(row.begin(), row.end(), 0);
        for (int x = 0; x < width; ++x) {
            const size_t s = (static_cast<size_t>(yTop) * width + x) * 4u;
            const size_t d = static_cast<size_t>(x) * 3u;
            row[d + 0] = rgbaTopDown[s + 2];
            row[d + 1] = rgbaTopDown[s + 1];
            row[d + 2] = rgbaTopDown[s + 0];
        }
        f.write(reinterpret_cast<const char*>(row.data()), row.size());
    }
    return static_cast<bool>(f);
}

// Stage 24.28.4 -------------------------------------------------------------
// v0.26.86 proved two distinct updateMenu ownership classes:
//   * pause/result pages are translucent gameplay overlays;
//   * the ordinary menu tree owns a new theme/background frame.
// Keep the classifier narrow and explicit. Unknown future pages remain
// full-frame menus until the original corpus/runtime proves otherwise.
static bool stage24284IsGameplayOverlayPage(const std::string& page) {
    return page == "pause" ||
           page == "levelComplete" || page == "levelFailed" ||
           page == "gameFinished" || page == "gameFinishedThreeStars" ||
           page == "gameFinishedLP2" || page == "gameFinishedThreeStarsLP2";
}

static bool stage24284ProtoHasString(const Proto* p, const char* needle) {
    if (!p || !needle) return false;
    for (int k = 0; k < p->sizek; ++k) {
        const TValue* v = &p->k[k];
        if (ttisstring(v)) {
            const char* q = svalue(v);
            if (q && std::strcmp(q, needle) == 0) return true;
        }
    }
    return false;
}

static void stage24284DumpProtoHits(const char* globalName, const Proto* p) {
    if (!p || !globalName) return;
    const char* needles[] = {
        "openURL", "levelComplete", "levelFailed", "pause",
        "gameFinished", "gameFinishedThreeStars",
        "gameFinishedLP2", "gameFinishedThreeStarsLP2",
        "currentGameMode", "drawMenu", "drawGame"
    };
    std::vector<int> hitKs;
    for (int k = 0; k < p->sizek; ++k) {
        const TValue* v = &p->k[k];
        if (!ttisstring(v)) continue;
        const char* q = svalue(v);
        if (!q) continue;
        for (const char* needle : needles) {
            if (!std::strcmp(q, needle)) {
                hitKs.push_back(k);
                std::printf("[stage24.28.4-lua-contract] GLOBAL name='%s' K[%d]='%s'\n",
                            globalName, k, q);
                break;
            }
        }
    }
    if (hitKs.empty()) return;
    std::set<int> emitted;
    for (int pc = 0; pc < p->sizecode; ++pc) {
        if (!stage24260_instruction_uses_hit(p, pc, hitKs)) continue;
        const int lo = std::max(0, pc - 18);
        const int hi = std::min(p->sizecode - 1, pc + 34);
        std::printf("[stage24.28.4-lua-contract] WINDOW name='%s' hitPc=%d lo=%d hi=%d\n",
                    globalName, pc, lo, hi);
        for (int q = lo; q <= hi; ++q) {
            if (emitted.insert(q).second) stage24261_print_instruction(p, q, globalName);
        }
    }
}

static void stage24284_dump_overlay_platform_contract(lua_State* L) {
    if (!L) return;
    const int base = lua_gettop(L);
    std::printf("[stage24.28.4-lua-contract] BEGIN policy=READ_ONLY originalClosuresBeforeBindingReplacement\n");

    // drawGame is the recovered owner of the terminal-page HUD gate. Keep the
    // relevant constant/instruction windows alongside the runtime overlay fix.
    lua_getglobal(L, "drawGame");
    if (lua_isfunction(L, -1) && !lua_iscfunction(L, -1)) {
        const Closure* cl = static_cast<const Closure*>(lua_topointer(L, -1));
        const Proto* p = cl ? cl->l.p : nullptr;
        std::printf("[stage24.28.4-lua-contract] TARGET name='drawGame' status=%s sizecode=%d sizek=%d\n",
                    p ? "ORIGINAL_LUA" : "PROTO_MISSING", p ? p->sizecode : 0, p ? p->sizek : 0);
        if (p) stage24284DumpProtoHits("drawGame", p);
    } else {
        std::printf("[stage24.28.4-lua-contract] TARGET name='drawGame' status=MISSING_OR_NATIVE\n");
    }
    lua_pop(L, 1);

    // Discover every top-level original Lua function that directly references
    // openURL. This is stronger than hard-coding trailer/social/store callback
    // names and makes newly exercised platform buttons visible in one run.
    int producers = 0;
    lua_getglobal(L, "_G");
    if (lua_istable(L, -1)) {
        const int gt = lua_gettop(L);
        lua_pushnil(L);
        while (lua_next(L, gt) != 0) {
            if (lua_type(L, -2) == LUA_TSTRING && lua_isfunction(L, -1) && !lua_iscfunction(L, -1)) {
                const char* name = lua_tostring(L, -2);
                const Closure* cl = static_cast<const Closure*>(lua_topointer(L, -1));
                const Proto* p = cl ? cl->l.p : nullptr;
                if (name && p && stage24284ProtoHasString(p, "openURL")) {
                    ++producers;
                    std::printf("[stage24.28.4-lua-contract] OPENURL_PRODUCER index=%d name='%s' sizecode=%d sizek=%d\n",
                                producers, name, p->sizecode, p->sizek);
                    stage24284DumpProtoHits(name, p);
                }
            }
            lua_pop(L, 1); // keep key for lua_next
        }
    }
    lua_pop(L, 1);
    std::printf("[stage24.28.4-lua-contract] END openURLProducers=%d\n", producers);
    lua_settop(L, base);
}

static int l_stage24284_openURL(lua_State* L) {
    static unsigned long long calls = 0;
    ++calls;
    std::string args;
    for (int i = 1; i <= lua_gettop(L); ++i) {
        if (i > 1) args += ",";
        const int t = lua_type(L, i);
        if (t == LUA_TSTRING) {
            args += "'";
            args += lua_tostring(L, i) ? lua_tostring(L, i) : "";
            args += "'";
        } else if (t == LUA_TNUMBER) {
            char b[64]; std::snprintf(b, sizeof(b), "%.17g", (double)lua_tonumber(L, i)); args += b;
        } else if (t == LUA_TBOOLEAN) {
            args += lua_toboolean(L, i) ? "true" : "false";
        } else if (t == LUA_TNIL) {
            args += "nil";
        } else {
            args += lua_typename(L, t);
        }
    }
    lua_Debug ar;
    const char* caller = "<unknown>";
    const char* source = "<unknown>";
    int line = -1;
    std::memset(&ar, 0, sizeof(ar));
    if (lua_getstack(L, 1, &ar) && lua_getinfo(L, "nSl", &ar)) {
        if (ar.name) caller = ar.name;
        if (ar.short_src[0]) source = ar.short_src;
        line = ar.currentline;
    }
    std::printf(
        "[stage24.28.4-platform-boundary] URL_REQUEST call=%llu argc=%d args=[%s] caller='%s' source='%s' line=%d mode='%s' page='%s' action=AUDIT_NO_LAUNCH returnCount=0\n",
        calls, lua_gettop(L), args.c_str(), caller, source, line,
        stage24_global_lua_function_name(L, "currentGameMode").c_str(),
        table_field_table_name(L, "currentMenuPage").c_str());
    // Diagnostic-safe compatibility boundary only.  Do not launch a browser
    // or fabricate a boolean result until ARMv7/Android behavior is closed.
    return 0;
}



// Stage 24.30.0 -------------------------------------------------------------
// Original cutscene/story subsystem contract audit.  v0.26.90 reached the
// first-entry 1-1 story through the untouched menu tree and failed at
// _G.res.createSpriteSheet.  Keep this pass diagnostic: expose the missing
// native surface as a void probe so Lua can reveal the NEXT dependency, but do
// not populate the renderer's SpriteDB or claim that any sheet was loaded.
static std::string stage24300_value_repr(lua_State* L, int idx) {
    const int t = lua_type(L, idx);
    switch (t) {
        case LUA_TNIL: return "nil";
        case LUA_TBOOLEAN: return lua_toboolean(L, idx) ? "true" : "false";
        case LUA_TNUMBER: {
            char b[96]; std::snprintf(b, sizeof(b), "%.17g", (double)lua_tonumber(L, idx)); return b;
        }
        case LUA_TSTRING: {
            const char* q = lua_tostring(L, idx); return std::string("'") + (q ? q : "") + "'";
        }
        default: return std::string("<") + lua_typename(L, t) + ">";
    }
}

static std::string stage24300_global_repr(lua_State* L, const char* name) {
    lua_getglobal(L, name);
    std::string out = stage24300_value_repr(L, -1);
    lua_pop(L, 1);
    return out;
}

